            parts.append(('  '*(ind+1))+k+('*' if k in req else '')+': '+compact(v,ind+1))
        ap=s.get('additionalProperties')
        extra=' +AP' if ap is True or isinstance(ap,dict) else ''
        if not parts: return '{}'+extra
        return '{\n'+'\n'.join(parts)+'\n'+('  '*ind)+'}'+extra
    if t=='array': return '['+compact(s.get('items',{}),ind)+']'
    r=t or '?'
    if 'enum' in s: r+=str(s['enum'])
    if 'format' in s: r+='<'+s['format']+'>'
    for k in ('minimum','maximum','minLength','maxLength','default','pattern'):
        if k in s: r+=f' {k}={s[k]}'
