      if op.get('summary') or op.get('description'): print('DESC:',op.get('summary'),op.get('description'))
      for prm in op.get('parameters',[]):
          print('PARAM',prm.get('in'),prm.get('name'),'req=',prm.get('required'),compact(prm.get('schema')), prm.get('description',''))
      rb=op.get('requestBody')
      if rb:
          sc=rb['content']['application/json']['schema']
          print('BODY:',compact(sc))
      for code,r in op['responses'].items():
          cont=r.get('content',{})
          for ct,v in cont.items():
            sc=v['schema']
            if code.startswith('2'):
                print('RESP',code,ct,compact(sc))
            else:
                codes=sc.get('properties',{}).get('code',{}).get('enum')
                print('ERR',code,codes)
          if not cont: print('RESP',code,'(no content)',r.get('description'))
