{"command": "create", "path": "/workspace/backend/internal/geo/geo.go", "file_text": "package geo

import "math"

const earthRadiusKm = 6371.0088

// DistanceKm returns the haversine great-circle distance between two points.
func DistanceKm(lat1, lon1, lat2, lon2 float64) float64 {
	toRad := func(d float64) float64 { return d * math.Pi / 180 }
	dLat := toRad(lat2 - lat1)
	dLon := toRad(lon2 - lon1)
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(toRad(lat1))*math.Cos(toRad(lat2))*math.Sin(dLon/2)*math.Sin(dLon/2)
	return 2 * earthRadiusKm * math.Asin(math.Min(1, math.Sqrt(a)))
}

// FirstMileMinutes estimates travel time for a leg that has no configured connection
// (origin to the entry node) assuming an average urban speed of 25 km/h.
func FirstMileMinutes(distanceKm float64) int {
	m := int(math.Ceil(distanceKm / 25.0 * 60.0))
	if m < 1 {
		m = 1
	}
	return m
}

func ValidCoordinate(lat, lon float64) bool {
	return !math.IsNaN(lat) && !math.IsNaN(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180
}
