{"command": "create", "path": "/workspace/backend/internal/core/errors.go", "file_text": "package core

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/jackc/pgx/v5/pgconn"
)

// Error is an API error carrying the HTTP status and the contract error code.
type Error struct {
	Status  int
	Code    string
	Message string
}

func (e *Error) Error() string { return fmt.Sprintf("%d %s: %s", e.Status, e.Code, e.Message) }

func E(status int, code, msg string) *Error { return &Error{Status: status, Code: code, Message: msg} }

func BadRequest(code, msg string) *Error  { return E(http.StatusBadRequest, code, msg) }
func Conflict(code, msg string) *Error    { return E(http.StatusConflict, code, msg) }
func Forbidden(code, msg string) *Error   { return E(http.StatusForbidden, code, msg) }
func NotFound(msg string) *Error          { return E(http.StatusNotFound, "not_found", msg) }
func Unauthorized() *Error                { return E(http.StatusUnauthorized, "unauthorized", "authentication required") }
func ForbiddenDefault() *Error            { return Forbidden("forbidden", "the selected role may not perform this action") }
func RoleNotSelected() *Error             { return Conflict("role_not_selected", "select an active role before performing this action") }
func Internal(err error) *Error           { return E(http.StatusInternalServerError, "internal_error", err.Error()) }
func IdempotencyRequired() *Error         { return BadRequest("idempotency_required", "idempotencyKey is required") }
func InvalidTime(field string) *Error     { return BadRequest("invalid_time", field+" must be an RFC 3339 timestamp") }
func InvalidJSON(msg string) *Error       { return BadRequest("invalid_json", msg) }

// AsError converts any error into an API error, mapping database serialization
// failures to concurrent_conflict.
func AsError(err error) *Error {
	var ae *Error
	if errors.As(err, &ae) {
		return ae
	}
	var pg *pgconn.PgError
	if errors.As(err, &pg) {
		switch pg.Code {
		case "40001", "40P01", "55P03":
			return Conflict("concurrent_conflict", "the record was modified concurrently; retry the operation")
		}
	}
	return Internal(err)
}
", "security_risk": "MEDIUM", "summary": "Create API error type and helpers"}

