// Q abstracts a pool or transaction.
type Q interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconnCommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// ---- loaders ----

const userCols = `id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units, last_offered_at, created_at`

func scanUser(row pgx.Row) (*User, error) {
	var u User
	var certs []byte
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &u.Roles, &u.Qualifications, &certs, &u.Active, &u.AssignedLocationID, &u.Available, &u.CapacityUnits, &u.LastOfferedAt, &u.CreatedAt); err != nil {
		return nil, err
	}
	_ = json.Unmarshal(certs, &u.Certifications)
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	return &u, nil
}

func loadUser(ctx context.Context, q Q, id string) (*User, error) {
	u, err := scanUser(q.QueryRow(ctx, `SELECT `+userCols+` FROM users WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, NotFound("user not found")
	}
	return u, err
}

func loadUsers(ctx context.Context, q Q, where string, args ...any) ([]*User, error) {
	rows, err := q.Query(ctx, `SELECT `+userCols+` FROM users `+where, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*User
	for rows.Next() {
		u, err := scanUser(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, u)
	}
	return out, rows.Err()
}

const locationCols = `id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, capacity_units, cooled_capacity_units`

func scanLocation(row pgx.Row) (*Location, error) {
