		return nil, err
	}
	return &l, nil
}

func loadLocation(ctx context.Context, q Q, id string) (*Location, error) {
	l, err := scanLocation(q.QueryRow(ctx, `SELECT `+locationCols+` FROM locations WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, NotFound("location not found")
	}
	return l, err
}

func loadLocations(ctx context.Context, q Q) ([]*Location, error) {
	rows, err := q.Query(ctx, `SELECT `+locationCols+` FROM locations ORDER BY created_at, name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Location
	for rows.Next() {
		l, err := scanLocation(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, l)
	}
	return out, rows.Err()
}

const connectionCols = `id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, cooled_capacity_units`

