import (
	"sync"
	"time"
)

// Message is a realtime event delivered to connected clients.
type Message struct {
	ID         int64          `json:"id"`
	Type       string         `json:"type"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Payload    map[string]any `json:"payload"`
	CreatedAt  time.Time      `json:"createdAt"`
	Roles      []string       `json:"-"`
	UserIDs    []string       `json:"-"`
}

// Visible reports whether the message is addressed to a session acting as
// role for userID. Messages without an audience are broadcast to everyone.
func (m Message) Visible(userID, role string) bool {
	if len(m.Roles) == 0 && len(m.UserIDs) == 0 {
		return true
	}
	for _, r := range m.Roles {
		if r == role {
			return true
		}
	}
	for _, u := range m.UserIDs {
		if u == userID {
			return true
		}
	}
	return false
}

type Subscriber struct {
	UserID string
	Role   func() string
	Ch     chan Message
}

type Hub struct {
	mu   sync.Mutex
	subs map[*Subscriber]struct{}
}

func NewHub() *Hub { return &Hub{subs: map[*Subscriber]struct{}{}} }

func (h *Hub) Subscribe(userID string, role func() string) *Subscriber {
	s := &Subscriber{UserID: userID, Role: role, Ch: make(chan Message, 256)}
	h.mu.Lock()
	h.subs[s] = struct{}{}
	h.mu.Unlock()
	return s
}

func (h *Hub) Unsubscribe(s *Subscriber) {
	h.mu.Lock()
	delete(h.subs, s)
	h.mu.Unlock()
}

func (h *Hub) Publish(m Message) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for s := range h.subs {
		if !m.Visible(s.UserID, s.Role()) {
			continue
		}
		select {
		case s.Ch <- m:
		default:
		}
	}
