type pq []*pqItem

func (p pq) Len() int { return len(p) }
func (p pq) Less(i, j int) bool {
	if !p[i].t.Equal(p[j].t) {
		return p[i].t.Before(p[j].t)
	}
	return p[i].cost < p[j].cost
}
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i]; p[i].idx = i; p[j].idx = j }
func (p *pq) Push(x any)         { it := x.(*pqItem); it.idx = len(*p); *p = append(*p, it) }
func (p *pq) Pop() any           { old := *p; n := len(old); it := old[n-1]; *p = old[:n-1]; return it }

// entryCandidates returns active collection points covering the origin, nearest first.
func (s *serviceabilitySnapshot) entryCandidates(lat, lon float64) []*Location {
