		}
	}
	sort.Slice(out, func(i, j int) bool {
		return geo.DistanceKm(lat, lon, out[i].Latitude, out[i].Longitude) < geo.DistanceKm(lat, lon, out[j].Latitude, out[j].Longitude)
	})
	return out
}

// findRoute runs a time-minimising Dijkstra from the entry candidates to any
