		if opt.ignoreCapacity {
			return true
		}
		return availableUnits(l.CapacityUnits, l.CooledCapacityUnits, usageMap[l.ID], cooled) >= units
	}
	connOK := func(c *Connection) bool {
		if !c.Active {
			return false
		}
		if cooled && !c.Cooled {
			return false
		}
		if opt.ignoreCapacity {
			return true
		}
		return availableUnits(c.CapacityUnits, c.CooledCapacityUnits, usageMap[c.ID], cooled) >= units
	}

	type state struct {
		arrive, depart time.Time
		cost           float64
		prev           string
		prevConn       string
		firstMile      int
	}
	best := map[string]*state{}
	h := &pq{}

	if in.OriginType == "node" {
		l := s.Locations[in.OriginNodeID]
		if l == nil || !nodeOK(l) {
			return nil
		}
		depart := in.Start
		if !in.Presealed {
			depart = depart.Add(collectionHandlingMinutes * time.Minute)
		}
		depart = depart.Add(time.Duration(l.HandlingMinutes) * time.Minute)
		best[l.ID] = &state{arrive: in.Start, depart: depart}
		heap.Push(h, &pqItem{node: l.ID, t: depart})
