			}
			arrive = arrive.Add(time.Duration(fm) * time.Minute)
			depart := arrive.Add(time.Duration(l.HandlingMinutes) * time.Minute)
			if cur := best[l.ID]; cur == nil || depart.Before(cur.depart) {
				best[l.ID] = &state{arrive: arrive, depart: depart, firstMile: fm}
				heap.Push(h, &pqItem{node: l.ID, t: depart})
			}
		}
	}

	done := map[string]bool{}
	for h.Len() > 0 {
		it := heap.Pop(h).(*pqItem)
		if done[it.node] {
			continue
		}
		st := best[it.node]
		if st == nil || !st.depart.Equal(it.t) {
			continue
		}
		done[it.node] = true
		l := s.Locations[it.node]
