		}
		isEntry := st.prev == "" && st.prevConn == ""
		if !isEntry && !(l.Hub || l.TransferPoint) {
			continue
		}
		for _, c := range s.Outgoing[it.node] {
			if !connOK(c) {
				continue
			}
			nl := s.Locations[c.ToLocationID]
			if nl == nil || !nodeOK(nl) {
				continue
			}
			arrive := st.depart.Add(time.Duration(c.TravelMinutes) * time.Minute)
			depart := arrive.Add(time.Duration(nl.HandlingMinutes) * time.Minute)
			cost := st.cost + c.CostUnits
