// reserveCapacity reserves one unit per sample on every network node and
// connection of the plan, failing when a pool would be overbooked.
func (a *App) reserveCapacity(ctx context.Context, tx pgx.Tx, journeyID string, b journeyBuild, includeFirstNode bool) error {
	cooled := b.SampleType.RequiresCooledRoute
	units := b.Units
	usageMap, err := usageExcluding(ctx, tx, b.ExcludeJourneyIDs)
	if err != nil {
		return err
	}
	reserve := func(resourceType, resourceID string, capacity, cooledCapacity int) error {
		avail := availableUnits(capacity, cooledCapacity, usageMap[resourceID], cooled)
		if avail < units {
			if cooled {
				return Conflict("cooled_capacity_exhausted", fmt.Sprintf("%s %s has no cooled capacity available", resourceType, resourceID))
			}
			return Conflict("capacity_exhausted", fmt.Sprintf("%s %s has no capacity available", resourceType, resourceID))
		}
		u := usageMap[resourceID]
		if cooled {
			u.Cooled += units
		} else {
			u.Regular += units
		}
		usageMap[resourceID] = u
		for _, sid := range b.SampleIDs {
			if _, err := tx.Exec(ctx, `INSERT INTO capacity_reservations (id, journey_id, sample_id, resource_type, resource_id, cooled, units, status) VALUES ($1,$2,$3,$4,$5,$6,1,'active')`,
				NewID(), journeyID, sid, resourceType, resourceID, cooled); err != nil {
				return err
			}
		}
		return nil
	}
	for i, nodeID := range b.Plan.Path {
		if i == 0 && !includeFirstNode && b.OriginType == "node" && !b.FirstStopIsHandoff {
			// still reserve: the sample physically occupies the origin node
		}
		var cap, ccap int
		if err := tx.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM locations WHERE id = $1 FOR UPDATE`, nodeID).Scan(&cap, &ccap); err != nil {
			return err
		}
		if err := reserve("location", nodeID, cap, ccap); err != nil {
			return err
		}
	}
	for _, connID := range b.Plan.Conns {
		var cap, ccap int
		if err := tx.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM connections WHERE id = $1 FOR UPDATE`, connID).Scan(&cap, &ccap); err != nil {
			return err
		}
		if err := reserve("connection", connID, cap, ccap); err != nil {
			return err
		}
	}
	return nil
}

func releaseReservations(ctx context.Context, q Q, journeyID string, sampleIDs []string) error {
	if sampleIDs == nil {
		_, err := q.Exec(ctx, `UPDATE capacity_reservations SET status = 'released', released_at = now() WHERE journey_id = $1 AND status = 'active'`, journeyID)
		return err
	}
	_, err := q.Exec(ctx, `UPDATE capacity_reservations SET status = 'released', released_at = now() WHERE journey_id = $1 AND sample_id = ANY($2) AND status = 'active'`, journeyID, sampleIDs)
	return err
}

func releaseResourceReservations(ctx context.Context, q Q, journeyID, resourceID string) error {
	_, err := q.Exec(ctx, `UPDATE capacity_reservations SET status = 'released', released_at = now() WHERE journey_id = $1 AND resource_id = $2 AND status = 'active'`, journeyID, resourceID)
	return err
}

func bumpPlanVersion(ctx context.Context, q Q, journeyID string) (int, error) {
	var v int
	err := q.QueryRow(ctx, `UPDATE journeys SET plan_version = plan_version + 1, updated_at = now() WHERE id = $1 RETURNING plan_version`, journeyID).Scan(&v)
	return v, err
}

func setJourneyStatus(ctx context.Context, q Q, journeyID, status, replanStatus string) error {
	_, err := q.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = CASE WHEN $3 = '' THEN replan_status ELSE $3 END, updated_at = now() WHERE id = $1`, journeyID, status, replanStatus)
	return err
}

// cancelUnfinishedAssignments cancels every assignment of the journey that has
// not been started; started work is preserved untouched.
func cancelUnfinishedAssignments(ctx context.Context, q Q, journeyID string, keep map[string]bool) ([]*Assignment, error) {
	asgs, err := loadAssignments(ctx, q, `WHERE journey_id = $1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	var cancelled []*Assignment
	for _, asg := range asgs {
		if keep[asg.ID] || assignmentFinished(asg.Status) {
			continue
		}
		if _, err := q.Exec(ctx, `UPDATE assignments SET status = $2, updated_at = now() WHERE id = $1`, asg.ID, AsgCancelled); err != nil {
			return nil, err
		}
		asg.Status = AsgCancelled
		cancelled = append(cancelled, asg)
	}
	return cancelled, nil
}
