{"command": "create", "path": "/workspace/backend/internal/core/assign.go", "file_text": "package core

import (
	"context"
	"sort"
	"time"
)

var activeAssignmentStatuses = []string{AsgOffered, AsgAccepted, AsgAtPickup, AsgPickedUp, AsgInTransit, AsgArrived, AsgInProgress}

func roleForKind(kind string) string {
	switch kind {
	case KindCollection:
		return RoleCollection
	case KindTransport:
		return RoleDelivery
	case KindNode:
		return RoleNodeHandler
	case KindLaboratory:
		return RoleLaboratory
	}
	return ""
}

// userQualified reports whether the user holds the qualification either as a
// plain qualification or as an active, unexpired certification.
func userQualified(u *User, qual string, now time.Time) bool {
	if qual == "" {
		return true
	}
	if contains(u.Qualifications, qual) {
		return true
	}
	return certificationActive(u, qual, now)
}

func certificationActive(u *User, code string, now time.Time) bool {
	for _, c := range u.Certifications {
		if c.Code == code && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

// certificationInactive reports an explicitly inactive or expired certification for code.
func certificationInactive(u *User, code string, now time.Time) bool {
	if code == "" {
		return false
	}
	for _, c := range u.Certifications {
		if c.Code == code && (!c.Active || (c.ExpiresAt != nil && !c.ExpiresAt.After(now))) {
			return !certificationActive(u, code, now)
		}
	}
	return false
}

// workerEligible checks the structural requirements for a worker to take the assignment.
func workerEligible(u *User, asg *Assignment, now time.Time) bool {
	if !u.Active || !u.HasRole(roleForKind(asg.Kind)) {
		return false
	}
	switch asg.Kind {
	case KindCollection:
		return userQualified(u, asg.RequiredQualification, now)
	case KindNode, KindLaboratory:
		return asg.LocationID != nil && u.AssignedLocationID != nil && *u.AssignedLocationID == *asg.LocationID
	}
	return true
}

func loadWorkloads(ctx context.Context, q Q) (map[string]int, error) {
	rows, err := q.Query(ctx, `SELECT worker_id, COUNT(*) FROM assignments WHERE worker_id IS NOT NULL AND status = ANY($1) GROUP BY worker_id`, activeAssignmentStatuses)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]int{}
	for rows.Next() {
		var id string
		var n int64
		if err := rows.Scan(&id, &n); err != nil {
			return nil, err
		}
		out[id] = int(n)
	}
	return out, rows.Err()
}

func (a *App) loadPenalised(ctx context.Context, q Q, now time.Time) (map[string]bool, error) {
	rows, err := q.Query(ctx, `SELECT worker_id, COUNT(*) FROM decline_events WHERE declined_at > $1 GROUP BY worker_id`, now.Add(-a.Cfg.DeclinePenaltyWindow))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]bool{}
	for rows.Next() {
		var id string
		var n int64
		if err := rows.Scan(&id, &n); err != nil {
			return nil, err
		}
		if int(n) >= a.Cfg.DeclinePenaltyCount {
			out[id] = true
		}
	}
	return out, rows.Err()
}

// candidateWorkers returns eligible, available workers ordered fairly, and the
// number of users that are structurally eligible regardless of availability.
func (a *App) candidateWorkers(ctx context.Context, q Q, asg *Assignment, now time.Time) ([]*User, int, error) {
	users, err := loadUsers(ctx, q, `WHERE $1 = ANY(roles) AND active ORDER BY username`, roleForKind(asg.Kind))
	if err != nil {
		return nil, 0, err
	}
	workloads, err := loadWorkloads(ctx, q)
	if err != nil {
		return nil, 0, err
	}
	penalised, err := a.loadPenalised(ctx, q, now)
	if err != nil {
		return nil, 0, err
	}
	var cands []*User
	structural := 0
	for _, u := range users {
		if !workerEligible(u, asg, now) {
			continue
		}
		structural++
		if !u.Available || contains(asg.DeclinedBy, u.ID) {
			continue
		}
		if asg.Kind == KindTransport && workloads[u.ID] >= u.CapacityUnits {
			continue
		}
		cands = append(cands, u)
	}
	sort.SliceStable(cands, func(i, j int) bool {
		pi, pj := penalised[cands[i].ID], penalised[cands[j].ID]
		if pi != pj {
			return !pi
		}
		wi, wj := workloads[cands[i].ID], workloads[cands[j].ID]
		if wi != wj {
			return wi < wj
		}
		li, lj := cands[i].LastOfferedAt, cands[j].LastOfferedAt
		if (li == nil) != (lj == nil) {
			return li == nil
		}
		if li != nil && lj != nil && !li.Equal(*lj) {
			return li.Before(*lj)
		}
		return cands[i].Username < cands[j].Username
	})
	return cands, structural, nil
}

// offerAssignment offers the assignment to the fairest eligible worker, or
// leaves it unassigned when nobody is available.
func (a *App) offerAssignment(ctx context.Context, q Q, actor *Actor, asg *Assignment, now time.Time) (*User, error) {
	cands, structural, err := a.candidateWorkers(ctx, q, asg, now)
	if err != nil {
		return nil, err
	}
	if len(cands) == 0 {
		var since *time.Time
		if asg.UnassignedSince != nil {
			since = asg.UnassignedSince
		} else {
			since = &now
		}
		if _, err := q.Exec(ctx, `UPDATE assignments SET status = $2, worker_id = NULL, offered_at = NULL, offer_expires_at = NULL, unassigned_since = $3, updated_at = now() WHERE id = $1`, asg.ID, AsgUnassigned, since); err != nil {
			return nil, err
		}
		asg.Status = AsgUnassigned
		asg.WorkerID = nil
		asg.UnassignedSince = since
		if asg.Kind == KindCollection && structural == 0 {
			for _, sid := range asg.SampleIDs {
				if err := a.flagException(ctx, q, actor, sid, "no_qualified_worker", "no certified collection professional holds the required qualification", map[string]any{"assignmentId": asg.ID}); err != nil {
					return nil, err
				}
			}
		}
		return nil, nil
	}
	w := cands[0]
	expires := now.Add(a.Cfg.OfferTimeout)
	if _, err := q.Exec(ctx, `UPDATE assignments SET status = $2, worker_id = $3, offered_at = $4, offer_expires_at = $5, unassigned_since = NULL, updated_at = now() WHERE id = $1`, asg.ID, AsgOffered, w.ID, now, expires); err != nil {
		return nil, err
	}
	if _, err := q.Exec(ctx, `UPDATE users SET last_offered_at = $2 WHERE id = $1`, w.ID, now); err != nil {
		return nil, err
	}
	asg.Status = AsgOffered
	asg.WorkerID = &w.ID
	asg.OfferedAt = &now
	asg.OfferExpiresAt = &expires
	asg.UnassignedSince = nil
	if err := a.Audit(ctx, q, actor, AuditEvent{Action: "assignment.offered", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs,
		Details: map[string]any{"workerId": w.ID, "kind": asg.Kind, "journeyId": asg.JourneyID, "offerExpiresAt": fmtTime(expires)}}); err != nil {
		return nil, err
	}
	if err := a.Emit(ctx, q, Event{Type: "assignment.offered", EntityType: "assignment", EntityID: asg.ID, UserIDs: []string{w.ID}, Roles: []string{RoleDispatcher, RoleAdministrator},
		Payload: map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "sampleId": asg.primarySample(), "journeyId": asg.JourneyID, "workerId": w.ID, "offerExpiresAt": fmtTime(expires)}}); err != nil {
		return nil, err
	}
	return w, nil
}

// flagException marks a sample as an exception with a specific reason.
func (a *App) flagException(ctx context.Context, q Q, actor *Actor, sampleID, reason, message string, extra map[string]any) error {
	s, err := loadSample(ctx, q, sampleID)
	if err != nil {
		return err
	}
	if terminalSample(s.Status) {
		return nil
	}
	exc := map[string]any{"reason": reason, "message": message, "flaggedAt": fmtTime(Now()), "previousStatus": s.Status}
	for k, v := range extra {
		exc[k] = v
	}
	if err := setSampleStatus(ctx, q, sampleID, SampleException, exc); err != nil {
		return err
	}
	if err := a.Audit(ctx, q, actor, AuditEvent{Action: "sample.exception", EntityType: "sample", EntityID: sampleID, Success: true, SampleIDs: []string{sampleID}, Details: exc}); err != nil {
		return err
	}
	return a.Emit(ctx, q, Event{Type: "sample.exception", EntityType: "sample", EntityID: sampleID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: exc})
}

func setSampleStatus(ctx context.Context, q Q, sampleID, status string, exception map[string]any) error {
	if exception == nil {
		_, err := q.Exec(ctx, `UPDATE samples SET status = $2, updated_at = now() WHERE id = $1`, sampleID, status)
		return err
	}
	_, err := q.Exec(ctx, `UPDATE samples SET status = $2, exception = $3, updated_at = now() WHERE id = $1`, sampleID, status, exception)
	return err
}

// recordSampleStatus writes the status transition into the sample timeline and
// publishes it.
func (a *App) transitionSample(ctx context.Context, q Q, actor *Actor, sampleID, status string, details map[string]any) error {
	if details == nil {
		details = map[string]any{}
	}
	details["status"] = status
	if err := setSampleStatus(ctx, q, sampleID, status, nil); err != nil {
		return err
	}
	if err := a.Audit(ctx, q, actor, AuditEvent{Action: "sample.status." + status, EntityType: "sample", EntityID: sampleID, Success: true, SampleIDs: []string{sampleID}, Details: details}); err != nil {
		return err
	}
	return a.Emit(ctx, q, Event{Type: "sample.status", EntityType: "sample", EntityID: sampleID, Payload: details})
}

// offerAll offers every newly created assignment.
func (a *App) offerAll(ctx context.Context, q Q, actor *Actor, asgs []*Assignment, now time.Time) error {
	for _, asg := range asgs {
		if asg.Status != AsgUnassigned {
			continue
		}
		if _, err := a.offerAssignment(ctx, q, actor, asg, now); err != nil {
			return err
		}
	}
	return nil
}
