		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if err := json.Unmarshal(body, &in); err != nil {
		return 0, nil, InvalidJSON("malformed request body")
	}
	if in.FromLocationID == "" || in.ToLocationID == "" || in.TravelMinutes == nil || in.CostUnits == nil || in.Active == nil {
		return 0, nil, InvalidJSON("fromLocationId, toLocationId, travelMinutes, costUnits and active are required")
	}
	if *in.TravelMinutes < 1 || *in.CostUnits < 0 || in.FromLocationID == in.ToLocationID {
		return 0, nil, BadRequest("invalid_connection", "travelMinutes must be >= 1, costUnits >= 0 and the endpoints must differ")
	}
	cooled := in.Cooled != nil && *in.Cooled
	id := NewID()
	var c *Connection
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		if _, err := loadLocation(ctx, tx, in.FromLocationID); err != nil {
			return BadRequest("invalid_connection", "fromLocationId does not reference a location")
		}
		if _, err := loadLocation(ctx, tx, in.ToLocationID); err != nil {
			return BadRequest("invalid_connection", "toLocationId does not reference a location")
		}
		if _, err := tx.Exec(ctx, `INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active) VALUES ($1,$2,$3,$4,$5,$6,$7)`,
			id, in.FromLocationID, in.ToLocationID, *in.TravelMinutes, *in.CostUnits, cooled, *in.Active); err != nil {
			return err
		}
		var err error
		c, err = loadConnection(ctx, tx, id)
		if err != nil {
			return err
		}
		if err := bumpNetworkRevision(ctx, tx); err != nil {
			return err
		}
		return a.Audit(ctx, tx, actor, AuditEvent{Action: "connection.created", EntityType: "connection", EntityID: id, Success: true, Details: connectionView(c)})
	})
	if err != nil {
		return 0, nil, err
	}
	a.afterNetworkChange(ctx)
	return 201, connectionView(c), nil
}

