func (a *App) ConfigureCapacity(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := json.Unmarshal(body, &in); err != nil {
		return 0, nil, InvalidJSON("malformed request body")
	}
	if in.ResourceID == "" || in.CapacityUnits == nil {
		return 0, nil, InvalidJSON("resourceId and capacityUnits are required")
	}
	cooled := 0
	if in.CooledCapacityUnits != nil {
		cooled = *in.CooledCapacityUnits
	}
	if *in.CapacityUnits < 0 || cooled < 0 {
		return 0, nil, BadRequest("invalid_capacity", "capacity units must be >= 0")
	}
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		resourceType := ""
		if _, err := loadLocation(ctx, tx, in.ResourceID); err == nil {
			resourceType = "location"
		} else if _, err := loadConnection(ctx, tx, in.ResourceID); err == nil {
			resourceType = "connection"
		} else {
			return BadRequest("invalid_capacity", "resourceId does not reference a location or connection")
		}
		if resourceType == "connection" && !actor.Is(RoleAdministrator) {
			return ForbiddenDefault()
		}
		if actor.Is(RoleNodeHandler, RoleLaboratory) && (actor.User.AssignedLocationID == nil || *actor.User.AssignedLocationID != in.ResourceID) {
			return ForbiddenDefault()
		}
		usageMap, err := usageExcluding(ctx, tx, nil)
		if err != nil {
			return err
		}
		u := usageMap[in.ResourceID]
		if u.Regular > *in.CapacityUnits || u.Cooled > cooled {
			return Conflict("capacity_reserved", "existing reservations exceed the requested capacity")
		}
		table := "locations"
		if resourceType == "connection" {
			table = "connections"
		}
		if _, err := tx.Exec(ctx, `UPDATE `+table+` SET capacity_units=$2, cooled_capacity_units=$3, updated_at=now() WHERE id=$1`, in.ResourceID, *in.CapacityUnits, cooled); err != nil {
			return err
		}
		if err := bumpNetworkRevision(ctx, tx); err != nil {
			return err
		}
		return a.Audit(ctx, tx, actor, AuditEvent{Action: "capacity.configured", EntityType: resourceType, EntityID: in.ResourceID, Success: true, Details: map[string]any{"capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled}})
	})
	if err != nil {
		return 0, nil, err
	}
	a.afterNetworkChange(ctx)
	return 200, map[string]any{"resourceId": in.ResourceID, "capacityUnits": *in.CapacityUnits, "cooledCapacityUnits": cooled}, nil
}

