func sampleTypeView(s *SampleType) map[string]any {
	return map[string]any{
		"sampleTypeId": s.ID, "name": s.Name, "qualifiedCollectorRequired": s.QualifiedCollectorRequired, "requiredQualification": s.RequiredQualification,
		"containerType": s.ContainerType, "temperatureMinC": s.TemperatureMinC, "temperatureMaxC": s.TemperatureMaxC,
		"incompatibleSampleTypes": s.IncompatibleSampleTypes, "requiresCooledRoute": s.RequiresCooledRoute, "batchingAllowed": s.BatchingAllowed,
	}
}

type sampleTypeIn struct {
	SampleTypeID               string   `json:"sampleTypeId"`
	Name                       string   `json:"name"`
	QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification      *string  `json:"requiredQualification"`
	ContainerType              string   `json:"containerType"`
	TemperatureMinC            *float64 `json:"temperatureMinC"`
	TemperatureMaxC            *float64 `json:"temperatureMaxC"`
