func (a *App) AcceptAssignment(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.AssignmentID == "" {
		return 0, nil, InvalidJSON("assignmentId is required")
	}
	now := Now()
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, true)
		if err != nil {
			return err
		}
		if roleForKind(asg.Kind) != actor.ActiveRole {
			return ForbiddenDefault()
		}
		if assignmentFinished(asg.Status) {
			return Conflict("assignment_inactive", "the assignment is no longer active")
		}
		if asg.Status != AsgOffered {
			if asg.WorkerID != nil && *asg.WorkerID == actor.ID() {
				out = map[string]any{"assignmentId": asg.ID, "workerId": actor.ID(), "status": "accepted"}
				return nil
			}
			if asg.WorkerID != nil {
				return Conflict("assignment_taken", "the assignment was accepted by another worker")
			}
			return Conflict("offer_not_available", "the assignment is not currently offered")
		}
		if asg.WorkerID == nil || *asg.WorkerID != actor.ID() {
			return Conflict("offer_not_offered", "the assignment was offered to a different worker")
		}
		if asg.OfferExpiresAt != nil && asg.OfferExpiresAt.Before(now) {
			return Conflict("offer_not_available", "the offer has expired")
		}
		if !workerEligible(actor.User, asg, now) {
			return Forbidden("ineligible_worker", "the worker is not eligible for this assignment")
		}
		if !actor.User.Available {
			return Conflict("worker_unavailable", "the worker is marked unavailable")
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, accepted_at = $3, offer_expires_at = NULL, updated_at = now() WHERE id = $1`, asg.ID, AsgAccepted, now); err != nil {
			return err
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment.accepted", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: map[string]any{"workerId": actor.ID(), "kind": asg.Kind, "journeyId": asg.JourneyID}}); err != nil {
			return err
		}
		if err := a.Emit(ctx, tx, Event{Type: "assignment.accepted", EntityType: "assignment", EntityID: asg.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, UserIDs: []string{actor.ID()}, Payload: map[string]any{"assignmentId": asg.ID, "workerId": actor.ID(), "kind": asg.Kind}}); err != nil {
			return err
		}
		out = map[string]any{"assignmentId": asg.ID, "workerId": actor.ID(), "status": "accepted"}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) DeclineAssignment(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
		DeclinedAt   string `json:"declinedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.AssignmentID == "" {
		return 0, nil, InvalidJSON("assignmentId is required")
	}
	now := Now()
	declinedAt := now
	if t, err := parseOptTime(in.DeclinedAt, "declinedAt"); err != nil {
		return 0, nil, err
	} else if t != nil {
		declinedAt = *t
	}
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, true)
		if err != nil {
			return err
		}
		if roleForKind(asg.Kind) != actor.ActiveRole {
			return ForbiddenDefault()
		}
		if asg.Status != AsgOffered || asg.WorkerID == nil || *asg.WorkerID != actor.ID() {
			return Conflict("offer_not_available", "the assignment is not currently offered to this worker")
		}
		declined := append(asg.DeclinedBy, actor.ID())
		if _, err := tx.Exec(ctx, `UPDATE assignments SET declined_by = $2, status = $3, worker_id = NULL, offered_at = NULL, offer_expires_at = NULL, updated_at = now() WHERE id = $1`, asg.ID, declined, AsgUnassigned); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO decline_events (worker_id, assignment_id, declined_at) VALUES ($1,$2,$3)`, actor.ID(), asg.ID, declinedAt); err != nil {
			return err
		}
		asg.DeclinedBy = declined
		asg.Status = AsgUnassigned
		asg.WorkerID = nil
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment.declined", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: map[string]any{"workerId": actor.ID(), "reason": in.Reason, "declinedAt": fmtTime(declinedAt)}}); err != nil {
			return err
		}
		next, err := a.offerAssignment(ctx, tx, actor, asg, now)
		if err != nil {
			return err
		}
		out = map[string]any{"assignmentId": asg.ID, "status": "pending", "declinedBy": actor.ID(), "declinedAt": fmtTime(declinedAt)}
		if next != nil {
			out["reofferedTo"] = next.ID
		}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

var transportRank = map[string]int{AsgAccepted: 0, AsgAtPickup: 1, AsgPickedUp: 2, AsgInTransit: 3, AsgArrived: 4, AsgDelivered: 5, AsgCompleted: 6}
var taskRank = map[string]int{AsgAccepted: 0, AsgInProgress: 1, AsgCompleted: 2}

func (a *App) UpdateAssignmentProgress(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		AssignmentID string `json:"assignmentId"`
		Status       string `json:"status"`
		OccurredAt   string `json:"occurredAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.AssignmentID == "" || in.Status == "" {
		return 0, nil, InvalidJSON("assignmentId, status and occurredAt are required")
	}
	if !contains([]string{AsgAtPickup, AsgPickedUp, AsgInTransit, AsgArrived, AsgDelivered, AsgInProgress, AsgCompleted}, in.Status) {
		return 0, nil, InvalidJSON("unknown progress status")
	}
	occurredAt, err := parseTime(in.OccurredAt, "occurredAt")
	if err != nil {
		return 0, nil, err
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, true)
		if err != nil {
			return err
		}
		if asg.WorkerID == nil || *asg.WorkerID != actor.ID() {
			return ForbiddenDefault()
		}
		if roleForKind(asg.Kind) != actor.ActiveRole {
			return Forbidden("ineligible_worker", "the selected role cannot progress this assignment")
		}
		if asg.Status == AsgCancelled {
			return Conflict("assignment_inactive", "the assignment is cancelled")
		}
		if asg.Status == AsgOffered || asg.Status == AsgUnassigned {
			return Conflict("assignment_not_ready", "accept the assignment before reporting progress")
		}
		if occurredAt.After(now.Add(a.Cfg.ClockSkew)) || (asg.LastProgressAt != nil && occurredAt.Before(*asg.LastProgressAt)) || (asg.AcceptedAt != nil && occurredAt.Before(asg.AcceptedAt.Add(-a.Cfg.ClockSkew))) {
			return Conflict("invalid_progress_time", "occurredAt must not precede earlier progress or lie in the future")
		}
		sample, err := loadSampleForUpdate(ctx, tx, asg.primarySample())
		if err != nil {
			return err
		}
		if terminalSample(sample.Status) {
			return Conflict("invalid_sample_state", "the sample is in a terminal state")
		}
		holderIsMe := sample.CurrentHolderID != nil && *sample.CurrentHolderID == actor.ID()
		newStatus := in.Status
		if asg.Kind == KindTransport {
			cur, ok := transportRank[asg.Status]
			next, ok2 := transportRank[in.Status]
			if !ok || !ok2 {
				return Conflict("invalid_transition", "status is not valid for a transport leg")
			}
			if next == cur || (asg.Status == AsgCompleted && in.Status == AsgDelivered) {
				out = map[string]any{"assignmentId": asg.ID, "sampleId": sample.ID, "status": asg.Status}
				return nil
			}
			if next < cur {
				return Conflict("invalid_transition", "progress cannot move backwards")
			}
			if next >= transportRank[AsgPickedUp] && cur < transportRank[AsgPickedUp] {
				if !sample.Sealed {
					return Conflict("collection_required", "the sample must be collected and sealed before pickup")
				}
				prior, err := a.priorAssignment(ctx, tx, asg)
				if err != nil {
					return err
				}
				if prior != nil && !assignmentFinished(prior.Status) && !holderIsMe {
					return Conflict("prior_leg_incomplete", "the previous leg has not been completed")
				}
				if !holderIsMe {
					return Conflict("custody_required", "custody must be transferred through a confirmed handoff before pickup")
				}
			}
			if in.Status == AsgDelivered {
				if holderIsMe {
					return Conflict("invalid_transition", "hand the sample off to the next custodian before marking the leg delivered")
				}
			}
		} else {
			cur, ok := taskRank[asg.Status]
			next, ok2 := taskRank[in.Status]
			if !ok || !ok2 {
				return Conflict("invalid_transition", "status is not valid for this assignment kind")
			}
			if next == cur {
				out = map[string]any{"assignmentId": asg.ID, "sampleId": sample.ID, "status": asg.Status}
				return nil
			}
			if next < cur {
				return Conflict("invalid_transition", "progress cannot move backwards")
			}
			if in.Status == AsgCompleted {
				switch asg.Kind {
				case KindCollection:
					if !sample.Sealed {
						return Conflict("collection_required", "collect and seal the sample before completing the assignment")
					}
					if holderIsMe {
						return Conflict("invalid_transition", "hand the sealed sample off before completing the collection assignment")
					}
				case KindNode:
					if holderIsMe {
						return Conflict("invalid_transition", "hand the sample off before completing the node assignment")
					}
				case KindLaboratory:
					if sample.Status != SampleReceived {
						return Conflict("invalid_transition", "confirm laboratory receipt to complete the laboratory assignment")
					}
				}
			}
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, last_progress_at = $3, completed_at = CASE WHEN $2 IN ('completed','delivered') THEN $3 ELSE completed_at END, updated_at = now() WHERE id = $1`, asg.ID, newStatus, occurredAt); err != nil {
			return err
		}
		details := map[string]any{"status": newStatus, "kind": asg.Kind, "workerId": actor.ID(), "occurredAt": fmtTime(occurredAt), "journeyId": asg.JourneyID}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment.progress", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: details}); err != nil {
			return err
		}
		if asg.Kind == KindTransport && holderIsMe {
			var lat, lon *float64
			switch newStatus {
			case AsgAtPickup:
				lat, lon = asg.FromLatitude, asg.FromLongitude
			case AsgArrived:
				lat, lon = asg.ToLatitude, asg.ToLongitude
			}
			if lat != nil {
				if _, err := tx.Exec(ctx, `UPDATE samples SET latest_latitude = $2, latest_longitude = $3, location_recorded_at = $4, updated_at = now() WHERE id = ANY($1)`, asg.SampleIDs, *lat, *lon, occurredAt); err != nil {
					return err
				}
			}
			if (newStatus == AsgPickedUp || newStatus == AsgInTransit) && sample.Status != SampleInTransit && sample.Status != SampleException {
				for _, sid := range asg.SampleIDs {
					if err := a.transitionSample(ctx, tx, actor, sid, SampleInTransit, map[string]any{"assignmentId": asg.ID}); err != nil {
						return err
					}
				}
			}
		}
		if err := a.Emit(ctx, tx, Event{Type: "assignment.progress", EntityType: "assignment", EntityID: asg.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: details}); err != nil {
			return err
		}
		out = map[string]any{"assignmentId": asg.ID, "sampleId": sample.ID, "status": newStatus}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

// priorAssignment returns the assignment immediately preceding asg in its journey.
func (a *App) priorAssignment(ctx context.Context, q Q, asg *Assignment) (*Assignment, error) {
	j, err := loadJourney(ctx, q, asg.JourneyID, false)
	if err != nil {
		return nil, err
	}
	asgs, err := loadJourneyAssignments(ctx, q, j)
	if err != nil {
		return nil, err
	}
	var prior *Assignment
	for _, x := range asgs {
		if x.Sequence < asg.Sequence && x.Status != AsgCancelled && (prior == nil || x.Sequence > prior.Sequence) {
			prior = x
		}
	}
	return prior, nil
}

func (a *App) CollectAndSealSample(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID       string   `json:"sampleId"`
		AssignmentID   string   `json:"assignmentId"`
		CollectedAt    string   `json:"collectedAt"`
		ContainerType  string   `json:"containerType"`
		ObservedTempC  *float64 `json:"observedTemperatureC"`
		IdempotencyKey string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" || in.AssignmentID == "" || in.ContainerType == "" || in.ObservedTempC == nil {
		return 0, nil, InvalidJSON("sampleId, assignmentId, collectedAt, containerType and observedTemperatureC are required")
	}
	collectedAt, err := parseTime(in.CollectedAt, "collectedAt")
	if err != nil {
		return 0, nil, err
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		sample, err := loadSampleForUpdate(ctx, tx, in.SampleID)
		if err != nil {
			return err
		}
		req, err := loadRequest(ctx, tx, sample.RequestID)
		if err != nil {
			return err
		}
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, true)
		if err != nil {
			return err
		}
		if asg.Kind != KindCollection || !contains(asg.SampleIDs, sample.ID) {
			return NotFound("assignment is not a collection assignment for this sample")
		}
		if asg.WorkerID == nil || *asg.WorkerID != actor.ID() {
			return ForbiddenDefault()
		}
		if assignmentFinished(asg.Status) {
			return Conflict("assignment_inactive", "the collection assignment is no longer active")
		}
		if asg.Status == AsgOffered || asg.Status == AsgUnassigned {
			return Conflict("collection_not_ready", "accept the collection assignment before collecting")
		}
		if sample.Sealed {
			if sample.CurrentHolderID != nil && *sample.CurrentHolderID == actor.ID() {
				out = map[string]any{"sampleId": sample.ID, "status": "sealed", "currentHolderId": actor.ID(), "sealedAt": fmtTimePtr(sample.SealedAt), "handlingCompliant": sample.Exception == nil}
				return nil
			}
			return Conflict("invalid_sample_state", "the sample is already sealed")
		}
		if terminalSample(sample.Status) {
			return Conflict("invalid_sample_state", "the sample is in a terminal state")
		}
		if asg.RequiredQualification != "" {
			if certificationInactive(actor.User, asg.RequiredQualification, now) {
				return Conflict("certification_inactive", "the collector's certification for this sample type is inactive or expired")
			}
			if !userQualified(actor.User, asg.RequiredQualification, now) {
				return ForbiddenDefault()
			}
		}
		if collectedAt.After(now.Add(a.Cfg.ClockSkew)) || collectedAt.Before(req.RequestedAt.Add(-a.Cfg.ClockSkew)) {
			return Conflict("invalid_collection_time", "collectedAt must lie between the request time and now")
		}
		if collectedAt.Before(req.EarliestCollectionAt) || collectedAt.After(req.LatestCollectionAt) {
			return Conflict("outside_collection_window", "collection must take place inside the collection window")
		}
		if !strings.EqualFold(strings.TrimSpace(in.ContainerType), strings.TrimSpace(req.ContainerType)) {
			return BadRequest("handling_noncompliant", "the container type does not match the sample's required container")
		}
		compliant := *in.ObservedTempC >= req.TemperatureMinC && *in.ObservedTempC <= req.TemperatureMaxC
		if _, err := tx.Exec(ctx, `UPDATE samples SET sealed = true, sealed_at = $2, collected_at = $2, current_holder_id = $3, status = $4, latest_latitude = $5, latest_longitude = $6, location_recorded_at = $7, updated_at = now() WHERE id = $1`,
			sample.ID, collectedAt, actor.ID(), SampleSealed, req.OriginLatitude, req.OriginLongitude, now); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, last_progress_at = $3, updated_at = now() WHERE id = $1`, asg.ID, AsgInProgress, collectedAt); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE journey_stops SET completed_at = $2 WHERE journey_id = $1 AND stop_type = 'pickup' AND completed_at IS NULL`, asg.JourneyID, collectedAt); err != nil {
			return err
		}
		details := map[string]any{"assignmentId": asg.ID, "collectedAt": fmtTime(collectedAt), "containerType": in.ContainerType, "observedTemperatureC": *in.ObservedTempC, "handlingCompliant": compliant, "collectorId": actor.ID()}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.collected", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
			return err
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.status.sealed", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: map[string]any{"status": SampleSealed, "currentHolderId": actor.ID()}}); err != nil {
			return err
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "custody.established", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: map[string]any{"holderId": actor.ID(), "assignmentId": asg.ID}}); err != nil {
			return err
		}
		if !compliant {
			if err := a.flagException(ctx, tx, actor, sample.ID, "handling_noncompliant", "observed temperature outside the required range at collection", details); err != nil {
				return err
			}
		}
		if err := a.Emit(ctx, tx, Event{Type: "sample.sealed", EntityType: "sample", EntityID: sample.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, UserIDs: []string{req.RequesterID}, Payload: details}); err != nil {
			return err
		}
		out = map[string]any{"sampleId": sample.ID, "status": "sealed", "currentHolderId": actor.ID(), "sealedAt": fmtTime(collectedAt), "handlingCompliant": compliant}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) RecordWorkerLocation(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		AssignmentID string   `json:"assignmentId"`
		Coordinate   *coordIn `json:"coordinate"`
		Sequence     *int     `json:"sequence"`
		RecordedAt   string   `json:"recordedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.AssignmentID == "" || in.Sequence == nil {
		return 0, nil, InvalidJSON("assignmentId, coordinate, sequence and recordedAt are required")
	}
	if !in.Coordinate.valid() {
		return 0, nil, BadRequest("invalid_coordinate", "coordinate must contain a valid latitude and longitude")
	}
	if *in.Sequence < 1 {
		return 0, nil, BadRequest("invalid_sequence", "sequence must be >= 1")
	}
	recordedAt, err := parseTime(in.RecordedAt, "recordedAt")
	if err != nil {
		return 0, nil, err
	}
	lat, lon := *in.Coordinate.Latitude, *in.Coordinate.Longitude
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, true)
		if err != nil {
			return err
		}
		if asg.WorkerID == nil || *asg.WorkerID != actor.ID() {
			return ForbiddenDefault()
		}
		var lastSeq int
		var lastAt time.Time
		err = tx.QueryRow(ctx, `SELECT sequence, recorded_at FROM worker_locations WHERE assignment_id = $1 ORDER BY sequence DESC LIMIT 1`, asg.ID).Scan(&lastSeq, &lastAt)
		if err != nil && err != pgx.ErrNoRows {
			return err
		}
		if err == nil && (*in.Sequence <= lastSeq || recordedAt.Before(lastAt)) {
			return Conflict("stale_location", "a newer location was already recorded for this assignment")
		}
		if _, err := tx.Exec(ctx, `INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at) VALUES ($1,$2,$3,$4,$5,$6)`, actor.ID(), asg.ID, lat, lon, *in.Sequence, recordedAt); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE samples SET latest_latitude = $2, latest_longitude = $3, location_recorded_at = $4, updated_at = now() WHERE id = ANY($1) AND current_holder_id = $5`, asg.SampleIDs, lat, lon, recordedAt, actor.ID()); err != nil {
			return err
		}
		payload := map[string]any{"workerId": actor.ID(), "assignmentId": asg.ID, "coordinate": map[string]any{"latitude": lat, "longitude": lon}, "sequence": *in.Sequence, "recordedAt": fmtTime(recordedAt)}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "worker.location_recorded", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: payload}); err != nil {
			return err
		}
		return a.Emit(ctx, tx, Event{Type: "worker.location", EntityType: "worker", EntityID: actor.ID(), Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: payload})
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, map[string]any{"assignmentId": in.AssignmentID, "coordinate": map[string]any{"latitude": lat, "longitude": lon}, "sequence": *in.Sequence, "recordedAt": fmtTime(recordedAt)}, nil
}

func (a *App) RecordHandlingCheckpoint(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID      string   `json:"sampleId"`
		AssignmentID  string   `json:"assignmentId"`
		LocationID    string   `json:"locationId"`
		ContainerType string   `json:"containerType"`
		ObservedTempC *float64 `json:"observedTemperatureC"`
		RecordedAt    string   `json:"recordedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" || in.AssignmentID == "" || in.ContainerType == "" || in.ObservedTempC == nil {
		return 0, nil, InvalidJSON("sampleId, assignmentId, containerType, observedTemperatureC and recordedAt are required")
	}
	recordedAt, err := parseTime(in.RecordedAt, "recordedAt")
	if err != nil {
		return 0, nil, err
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		sample, err := loadSampleForUpdate(ctx, tx, in.SampleID)
		if err != nil {
			return err
		}
		if terminalSample(sample.Status) {
			return Conflict("terminal_sample", "the sample is in a terminal state")
		}
		req, err := loadRequest(ctx, tx, sample.RequestID)
		if err != nil {
			return err
		}
		asg, err := loadAssignment(ctx, tx, in.AssignmentID, false)
		if err != nil {
			return err
		}
		if !contains(asg.SampleIDs, sample.ID) {
			return NotFound("assignment does not involve this sample")
		}
		if asg.WorkerID == nil || *asg.WorkerID != actor.ID() || sample.CurrentHolderID == nil || *sample.CurrentHolderID != actor.ID() {
			return ForbiddenDefault()
		}
		if assignmentFinished(asg.Status) {
			return Conflict("assignment_inactive", "the assignment is no longer active")
		}
		if sample.ActiveJourneyID != nil {
			j, err := loadJourney(ctx, tx, *sample.ActiveJourneyID, false)
			if err == nil && j.Status != JourneyActive {
				return Conflict("journey_inactive", "the sample's journey is not active")
			}
		}
		if recordedAt.After(now.Add(a.Cfg.ClockSkew)) || (sample.SealedAt != nil && recordedAt.Before(*sample.SealedAt)) {
			return Conflict("invalid_checkpoint_time", "recordedAt must lie between sealing and now")
		}
		var locID *string
		if in.LocationID != "" {
			if _, err := loadLocation(ctx, tx, in.LocationID); err != nil {
				return err
			}
			locID = &in.LocationID
		}
		compliant := strings.EqualFold(strings.TrimSpace(in.ContainerType), strings.TrimSpace(req.ContainerType)) && *in.ObservedTempC >= req.TemperatureMinC && *in.ObservedTempC <= req.TemperatureMaxC
		id := NewID()
		if _, err := tx.Exec(ctx, `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, actor_id, location_id, container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
			id, sample.ID, asg.ID, actor.ID(), locID, in.ContainerType, *in.ObservedTempC, compliant, recordedAt); err != nil {
			return err
		}
		details := map[string]any{"checkpointId": id, "assignmentId": asg.ID, "containerType": in.ContainerType, "observedTemperatureC": *in.ObservedTempC, "compliant": compliant, "recordedAt": fmtTime(recordedAt), "locationId": locID}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.handling_checkpoint", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
			return err
		}
		status := sample.Status
		if !compliant {
			if err := a.flagException(ctx, tx, actor, sample.ID, "handling_noncompliant", "observed container or temperature outside the required range", details); err != nil {
				return err
			}
			status = SampleException
		}
		out = map[string]any{"checkpointId": id, "sampleId": sample.ID, "compliant": compliant, "sampleStatus": status}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) InitiateHandoff(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" || in.FromAssignmentID == "" || in.ToAssignmentID == "" || in.ReceiverID == "" {
		return 0, nil, InvalidJSON("sampleId, fromAssignmentId, toAssignmentId, receiverId and initiatedAt are required")
	}
	initiatedAt, err := parseTime(in.InitiatedAt, "initiatedAt")
	if err != nil {
		return 0, nil, err
	}
	if in.ReceiverID == actor.ID() {
		return 0, nil, BadRequest("invalid_receiver", "a sample cannot be handed off to the current holder")
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		sample, err := loadSampleForUpdate(ctx, tx, in.SampleID)
		if err != nil {
			return err
		}
		if terminalSample(sample.Status) || !sample.Sealed {
			return Conflict("invalid_assignment_state", "the sample is not sealed and in transit")
		}
		from, err := loadAssignment(ctx, tx, in.FromAssignmentID, true)
		if err != nil {
			return err
		}
		if !contains(from.SampleIDs, sample.ID) {
			return NotFound("fromAssignmentId does not involve this sample")
		}
		if from.WorkerID == nil || *from.WorkerID != actor.ID() {
			return Forbidden("sender_assignment_mismatch", "the sender does not hold the source assignment")
		}
		if assignmentFinished(from.Status) {
			return Conflict("invalid_assignment_state", "the source assignment is already finished")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != actor.ID() {
			return Conflict("not_current_holder", "only the current holder may initiate a handoff")
		}
		pending, err := loadHandoffs(ctx, tx, `WHERE sample_id = $1 AND status = 'pending'`, sample.ID)
		if err != nil {
			return err
		}
		if len(pending) > 0 {
			p := pending[0]
			if p.FromAssignmentID == from.ID && p.ToAssignmentID == in.ToAssignmentID && p.ReceiverID == in.ReceiverID {
				out = map[string]any{"handoffId": p.ID, "senderId": p.SenderID, "receiverId": p.ReceiverID, "currentHolderId": actor.ID(), "status": "pending"}
				return nil
			}
			return Conflict("pending_handoff_exists", "a handoff is already pending for this sample")
		}
		to, err := loadAssignment(ctx, tx, in.ToAssignmentID, true)
		if err != nil {
			return err
		}
		if !contains(to.SampleIDs, sample.ID) {
			return NotFound("toAssignmentId does not involve this sample")
		}
		activeJourney := ""
		if sample.ActiveJourneyID != nil {
			activeJourney = *sample.ActiveJourneyID
		}
		if to.JourneyID != activeJourney {
			return BadRequest("invalid_handoff_route", "the target assignment does not belong to the sample's active journey")
		}
		if assignmentFinished(to.Status) {
			return Conflict("invalid_assignment_state", "the target assignment is already finished")
		}
		if to.Status == AsgOffered || to.Status == AsgUnassigned {
			return Conflict("offer_not_available", "the target assignment has not been accepted by a worker yet")
		}
		if to.WorkerID == nil || *to.WorkerID != in.ReceiverID {
			return Conflict("receiver_assignment_mismatch", "receiverId is not the worker of the target assignment")
		}
		receiver, err := loadUser(ctx, tx, in.ReceiverID)
		if err != nil {
			return BadRequest("invalid_receiver", "receiverId does not reference a user")
		}
		if !receiver.Active || !receiver.Available {
			return Conflict("receiver_unavailable", "the receiver is not available")
		}
		switch from.Kind {
		case KindTransport:
			if from.Status != AsgPickedUp && from.Status != AsgInTransit && from.Status != AsgArrived {
				return Conflict("transport_leg_incomplete", "the transport leg must be picked up before it can be handed off")
			}
			if to.Kind == KindNode && (to.LocationID == nil || from.ToLocationID == nil || *to.LocationID != *from.ToLocationID) {
				return Conflict("node_assignment_mismatch", "the node assignment is not at the leg's destination")
			}
			if to.Kind == KindLaboratory && (to.LocationID == nil || from.ToLocationID == nil || *to.LocationID != *from.ToLocationID) {
				return Conflict("invalid_handoff_route", "the laboratory assignment is not at the leg's destination")
			}
			if to.Kind == KindTransport && (to.FromLocationID == nil || from.ToLocationID == nil || *to.FromLocationID != *from.ToLocationID) {
				return Conflict("invalid_handoff_route", "the next leg does not start where this leg ends")
			}
		case KindCollection:
			if !sample.Sealed {
				return Conflict("prior_leg_incomplete", "the sample must be sealed before handoff")
			}
		}
		// Adjacency, allowing an unstaffed node assignment to be skipped.
		j, err := loadJourney(ctx, tx, activeJourney, true)
		if err != nil {
			return err
		}
		asgs, err := loadJourneyAssignments(ctx, tx, j)
		if err != nil {
			return err
		}
		var between []*Assignment
		for _, x := range asgs {
			if x.Sequence > from.Sequence && x.Sequence < to.Sequence && x.Status != AsgCancelled {
				between = append(between, x)
			}
		}
		if to.Sequence <= from.Sequence {
			return Conflict("nonadjacent_handoff", "the target assignment does not follow the source assignment")
		}
		for _, x := range between {
			if x.Kind == KindNode && (x.Status == AsgUnassigned || x.Status == AsgOffered) {
				if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, updated_at = now() WHERE id = $1`, x.ID, AsgCancelled); err != nil {
					return err
				}
				if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment.skipped", EntityType: "assignment", EntityID: x.ID, Success: true, SampleIDs: x.SampleIDs, Details: map[string]any{"reason": "unstaffed node bypassed by direct handoff"}}); err != nil {
					return err
				}
				continue
			}
			return Conflict("nonadjacent_handoff", "the target assignment is not the next step of the journey")
		}
		if initiatedAt.After(now.Add(a.Cfg.ClockSkew)) || (sample.SealedAt != nil && initiatedAt.Before(*sample.SealedAt)) {
			return Conflict("invalid_handoff_time", "initiatedAt must lie between sealing and now")
		}
		id := NewID()
		if _, err := tx.Exec(ctx, `INSERT INTO handoffs (id, sample_id, journey_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,'pending',$8)`,
			id, sample.ID, activeJourney, from.ID, to.ID, actor.ID(), in.ReceiverID, initiatedAt); err != nil {
			return err
		}
		details := map[string]any{"handoffId": id, "senderId": actor.ID(), "receiverId": in.ReceiverID, "fromAssignmentId": from.ID, "toAssignmentId": to.ID, "initiatedAt": fmtTime(initiatedAt)}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "custody.handoff_initiated", EntityType: "handoff", EntityID: id, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
			return err
		}
		if err := a.Emit(ctx, tx, Event{Type: "handoff.initiated", EntityType: "handoff", EntityID: id, UserIDs: []string{in.ReceiverID, actor.ID()}, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: details}); err != nil {
			return err
		}
		out = map[string]any{"handoffId": id, "senderId": actor.ID(), "receiverId": in.ReceiverID, "currentHolderId": actor.ID(), "status": "pending"}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) ConfirmHandoff(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.HandoffID == "" {
		return 0, nil, InvalidJSON("handoffId, confirmationSide and confirmedAt are required")
	}
	if in.ConfirmationSide != "sender" && in.ConfirmationSide != "receiver" {
		return 0, nil, BadRequest("invalid_confirmation_side", "confirmationSide must be sender or receiver")
	}
	confirmedAt, err := parseTime(in.ConfirmedAt, "confirmedAt")
	if err != nil {
		return 0, nil, err
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		h, err := loadHandoff(ctx, tx, in.HandoffID, true)
		if err != nil {
			return err
		}
		if in.ConfirmationSide == "sender" && h.SenderID != actor.ID() || in.ConfirmationSide == "receiver" && h.ReceiverID != actor.ID() {
			return ForbiddenDefault()
		}
		sample, err := loadSampleForUpdate(ctx, tx, h.SampleID)
		if err != nil {
			return err
		}
		view := func() map[string]any {
			holder := ""
			if sample.CurrentHolderID != nil {
				holder = *sample.CurrentHolderID
			}
			return map[string]any{"handoffId": h.ID, "status": h.Status, "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil, "currentHolderId": holder}
		}
		if h.Status == "confirmed" {
			out = view()
			return nil
		}
		if h.Status != "pending" {
			return Conflict("handoff_inactive", "the handoff is no longer pending")
		}
		if confirmedAt.Before(h.InitiatedAt) || confirmedAt.After(now.Add(a.Cfg.ClockSkew)) {
			return Conflict("invalid_confirmation_time", "confirmedAt must lie between initiation and now")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != h.SenderID {
			return Conflict("custody_conflict", "the sample is no longer held by the handoff sender")
		}
		col := "sender_confirmed_at"
		already := h.SenderConfirmedAt != nil
		if in.ConfirmationSide == "receiver" {
			col = "receiver_confirmed_at"
			already = h.ReceiverConfirmedAt != nil
		}
		if !already {
			if _, err := tx.Exec(ctx, `UPDATE handoffs SET `+col+` = $2 WHERE id = $1`, h.ID, confirmedAt); err != nil {
				return err
			}
			if in.ConfirmationSide == "receiver" {
				h.ReceiverConfirmedAt = &confirmedAt
			} else {
				h.SenderConfirmedAt = &confirmedAt
			}
			if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "custody.handoff_confirmed", EntityType: "handoff", EntityID: h.ID, Success: true, SampleIDs: []string{sample.ID}, Details: map[string]any{"side": in.ConfirmationSide, "confirmedAt": fmtTime(confirmedAt)}}); err != nil {
				return err
			}
		}
		if h.SenderConfirmedAt != nil && h.ReceiverConfirmedAt != nil {
			if err := a.completeHandoff(ctx, tx, actor, h, sample, confirmedAt); err != nil {
				return err
			}
		}
		out = view()
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

// completeHandoff transfers custody once both sides confirmed.
func (a *App) completeHandoff(ctx context.Context, tx pgx.Tx, actor *Actor, h *Handoff, sample *Sample, at time.Time) error {
	from, err := loadAssignment(ctx, tx, h.FromAssignmentID, true)
	if err != nil {
		return err
	}
	to, err := loadAssignment(ctx, tx, h.ToAssignmentID, true)
	if err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, `UPDATE handoffs SET status = 'confirmed', completed_at = $2 WHERE id = $1`, h.ID, at); err != nil {
		return err
	}
	h.Status = "confirmed"
	fromStatus := AsgCompleted
	if from.Kind == KindTransport {
		fromStatus = AsgDelivered
	}
	if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, completed_at = $3, last_progress_at = $3, updated_at = now() WHERE id = $1`, from.ID, fromStatus, at); err != nil {
		return err
	}
	toStatus := AsgInProgress
	if to.Kind == KindTransport {
		toStatus = AsgPickedUp
	}
	if !assignmentStarted(to.Status) {
		if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, last_progress_at = $3, updated_at = now() WHERE id = $1`, to.ID, toStatus, at); err != nil {
			return err
		}
	}
	// Release pools that are no longer needed.
	if from.Kind == KindNode && from.LocationID != nil {
		if err := releaseResourceReservations(ctx, tx, sample.ActiveJourneyOrEmpty(), *from.LocationID); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE journey_stops SET completed_at = $3 WHERE journey_id = $1 AND location_id = $2 AND stop_type = 'handoff' AND completed_at IS NULL`, from.JourneyID, *from.LocationID, at); err != nil {
			return err
		}
	}
	if from.Kind == KindTransport && from.ConnectionID != nil {
		if err := releaseResourceReservations(ctx, tx, from.JourneyID, *from.ConnectionID); err != nil {
			return err
		}
	}
	if from.Kind == KindTransport && to.Kind == KindTransport && from.ToLocationID != nil {
		if _, err := tx.Exec(ctx, `UPDATE journey_stops SET completed_at = $3 WHERE journey_id = $1 AND location_id = $2 AND stop_type = 'handoff' AND completed_at IS NULL`, to.JourneyID, *from.ToLocationID, at); err != nil {
			return err
		}
	}
	status := SampleInTransit
	var lat, lon *float64
	switch to.Kind {
	case KindNode:
		status = SampleAtNode
		lat, lon = to.FromLatitude, to.FromLongitude
	case KindLaboratory:
		status = SampleAtLaboratory
		lat, lon = to.FromLatitude, to.FromLongitude
	case KindTransport:
		lat, lon = to.FromLatitude, to.FromLongitude
	}
	if sample.Status == SampleException {
		status = SampleException
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET current_holder_id = $2, status = $3, latest_latitude = COALESCE($4, latest_latitude), latest_longitude = COALESCE($5, latest_longitude), location_recorded_at = $6, updated_at = now() WHERE id = $1`,
		sample.ID, h.ReceiverID, status, lat, lon, at); err != nil {
		return err
	}
	sample.CurrentHolderID = &h.ReceiverID
	sample.Status = status
	details := map[string]any{"handoffId": h.ID, "fromHolderId": h.SenderID, "toHolderId": h.ReceiverID, "fromAssignmentId": from.ID, "toAssignmentId": to.ID, "completedAt": fmtTime(at), "status": status}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "custody.transferred", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
		return err
	}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.status." + status, EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: map[string]any{"status": status, "currentHolderId": h.ReceiverID}}); err != nil {
		return err
	}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment." + fromStatus, EntityType: "assignment", EntityID: from.ID, Success: true, SampleIDs: from.SampleIDs, Details: map[string]any{"status": fromStatus, "via": "handoff", "handoffId": h.ID}}); err != nil {
		return err
	}
	return a.Emit(ctx, tx, Event{Type: "custody.transferred", EntityType: "sample", EntityID: sample.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, UserIDs: []string{h.SenderID, h.ReceiverID}, Payload: details})
}

func (s *Sample) ActiveJourneyOrEmpty() string {
	if s.ActiveJourneyID == nil {
		return ""
	}
	return *s.ActiveJourneyID
}

func (a *App) ConfirmLaboratoryReceipt(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID     string `json:"sampleId"`
		LaboratoryID string `json:"laboratoryId"`
		ReceivedAt   string `json:"receivedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" || in.LaboratoryID == "" {
		return 0, nil, InvalidJSON("sampleId, laboratoryId and receivedAt are required")
	}
	receivedAt, err := parseTime(in.ReceivedAt, "receivedAt")
	if err != nil {
		return 0, nil, err
	}
	if actor.User.AssignedLocationID == nil || *actor.User.AssignedLocationID != in.LaboratoryID {
		return 0, nil, Forbidden("wrong_laboratory_operator", "the operator is not assigned to this laboratory")
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		sample, err := loadSampleForUpdate(ctx, tx, in.SampleID)
		if err != nil {
			return err
		}
		lab, err := loadLocation(ctx, tx, in.LaboratoryID)
		if err != nil {
			return err
		}
		req, err := loadRequest(ctx, tx, sample.RequestID)
		if err != nil {
			return err
		}
		if sample.Status == SampleReceived {
			if sample.ReceivedLaboratoryID != nil && *sample.ReceivedLaboratoryID == lab.ID {
				out = map[string]any{"sampleId": sample.ID, "laboratoryId": lab.ID, "status": "received", "receivedAt": fmtTimePtr(sample.ReceivedAt)}
				return nil
			}
			return Conflict("custody_conflict", "the sample was already received at another laboratory")
		}
		if terminalSample(sample.Status) || !sample.Sealed {
			return Conflict("receipt_not_ready", "the sample is not ready for laboratory receipt")
		}
		if !lab.Active || !lab.Laboratory {
			return Conflict("laboratory_unavailable", "the laboratory is inactive")
		}
		var accepts bool
		_ = tx.QueryRow(ctx, `SELECT accepts FROM laboratory_acceptances WHERE laboratory_id = $1 AND sample_type_id = $2`, lab.ID, req.SampleTypeID).Scan(&accepts)
		if !accepts {
			return Conflict("laboratory_unavailable", "the laboratory does not accept this sample type")
		}
		pending, err := loadHandoffs(ctx, tx, `WHERE sample_id = $1 AND status = 'pending'`, sample.ID)
		if err != nil {
			return err
		}
		if len(pending) > 0 {
			return Conflict("pending_handoff_exists", "a handoff is still pending for this sample")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != actor.ID() {
			return Conflict("receipt_not_ready", "custody has not been transferred to this laboratory operator")
		}
		if receivedAt.After(now.Add(a.Cfg.ClockSkew)) || (sample.SealedAt != nil && receivedAt.Before(*sample.SealedAt)) {
			return Conflict("invalid_receipt_time", "receivedAt must lie between sealing and now")
		}
		if receivedAt.After(req.DeliveryDeadline) {
			return Conflict("delivery_deadline_exceeded", "the sample arrived after its delivery deadline; record a laboratory exception instead")
		}
		if _, err := tx.Exec(ctx, `UPDATE samples SET status = $2, received_laboratory_id = $3, received_at = $4, latest_latitude = $5, latest_longitude = $6, location_recorded_at = $4, updated_at = now() WHERE id = $1`,
			sample.ID, SampleReceived, lab.ID, receivedAt, lab.Latitude, lab.Longitude); err != nil {
			return err
		}
		if sample.ActiveJourneyID != nil {
			jid := *sample.ActiveJourneyID
			if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $3, completed_at = $4, last_progress_at = $4, updated_at = now() WHERE journey_id = $1 AND kind = 'laboratory' AND $2 = ANY(sample_ids) AND status NOT IN ('cancelled','completed')`, jid, sample.ID, AsgCompleted, receivedAt); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `UPDATE journey_stops SET completed_at = $2 WHERE journey_id = $1 AND stop_type = 'delivery' AND completed_at IS NULL`, jid, receivedAt); err != nil {
				return err
			}
			if err := releaseReservations(ctx, tx, jid, []string{sample.ID}); err != nil {
				return err
			}
			if err := a.completeJourneyIfDone(ctx, tx, actor, jid); err != nil {
				return err
			}
		}
		details := map[string]any{"laboratoryId": lab.ID, "receivedAt": fmtTime(receivedAt), "operatorId": actor.ID(), "status": SampleReceived}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.received", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
			return err
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.status.received", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: details}); err != nil {
			return err
		}
		if err := a.Emit(ctx, tx, Event{Type: "sample.received", EntityType: "sample", EntityID: sample.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, UserIDs: []string{req.RequesterID}, Payload: details}); err != nil {
			return err
		}
		out = map[string]any{"sampleId": sample.ID, "laboratoryId": lab.ID, "status": "received", "receivedAt": fmtTime(receivedAt)}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

// completeJourneyIfDone marks the journey completed once every sample reached its laboratory.
func (a *App) completeJourneyIfDone(ctx context.Context, tx pgx.Tx, actor *Actor, journeyID string) error {
	j, err := loadJourney(ctx, tx, journeyID, true)
	if err != nil {
		return err
	}
	if j.Status != JourneyActive {
		return nil
	}
	var remaining int
	if err := tx.QueryRow(ctx, `SELECT COUNT(*) FROM samples WHERE id = ANY($1) AND status <> 'received'`, j.SampleIDs).Scan(&remaining); err != nil {
		return err
	}
	if remaining > 0 {
		return nil
	}
	if _, err := tx.Exec(ctx, `UPDATE assignments SET status = 'cancelled', updated_at = now() WHERE journey_id = $1 AND status IN ('unassigned','offered','accepted')`, journeyID); err != nil {
		return err
	}
	if err := setJourneyStatus(ctx, tx, journeyID, JourneyCompleted, "not_required"); err != nil {
		return err
	}
	if err := releaseReservations(ctx, tx, journeyID, nil); err != nil {
		return err
	}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.completed", EntityType: "journey", EntityID: journeyID, Success: true, SampleIDs: j.SampleIDs, Details: map[string]any{"status": JourneyCompleted}}); err != nil {
		return err
	}
	return a.Emit(ctx, tx, Event{Type: "journey.completed", EntityType: "journey", EntityID: journeyID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: map[string]any{"journeyId": journeyID}})
}

func (a *App) RecordLaboratoryException(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID     string `json:"sampleId"`
		LaboratoryID string `json:"laboratoryId"`
		Reason       string `json:"reason"`
		ObservedAt   string `json:"observedAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" || in.LaboratoryID == "" || strings.TrimSpace(in.Reason) == "" {
		return 0, nil, InvalidJSON("sampleId, laboratoryId, reason and observedAt are required")
	}
	observedAt, err := parseTime(in.ObservedAt, "observedAt")
	if err != nil {
		return 0, nil, err
	}
	if actor.User.AssignedLocationID == nil || *actor.User.AssignedLocationID != in.LaboratoryID {
		return 0, nil, Forbidden("wrong_laboratory_operator", "the operator is not assigned to this laboratory")
	}
	now := Now()
	var out map[string]any
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		sample, err := loadSampleForUpdate(ctx, tx, in.SampleID)
		if err != nil {
			return err
		}
		if _, err := loadLocation(ctx, tx, in.LaboratoryID); err != nil {
			return err
		}
		if sample.ActiveJourneyID == nil {
			return Conflict("journey_inactive", "the sample has no active journey")
		}
		j, err := loadJourney(ctx, tx, *sample.ActiveJourneyID, true)
		if err != nil {
			return err
		}
		if j.Status != JourneyActive {
			return Conflict("journey_inactive", "the sample's journey is not active")
		}
		if j.TargetLaboratoryID == nil || *j.TargetLaboratoryID != in.LaboratoryID {
			return Conflict("wrong_laboratory", "the sample is not routed to this laboratory")
		}
		atLab := sample.CurrentHolderID != nil && *sample.CurrentHolderID == actor.ID()
		if !atLab {
			var n int
			if err := tx.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id = $1 AND kind = 'laboratory' AND worker_id = $2 AND status NOT IN ('cancelled')`, j.ID, actor.ID()).Scan(&n); err != nil {
				return err
			}
			if n == 0 {
				return Conflict("laboratory_not_ready", "the sample is not expected by this operator's laboratory")
			}
		}
		if observedAt.After(now.Add(a.Cfg.ClockSkew)) || observedAt.Before(sample.CreatedAt.Add(-a.Cfg.ClockSkew)) {
			return Conflict("invalid_exception_time", "observedAt must lie between the request and now")
		}
		id := NewID()
		if _, err := tx.Exec(ctx, `INSERT INTO laboratory_exceptions (id, sample_id, laboratory_id, actor_id, reason, observed_at) VALUES ($1,$2,$3,$4,$5,$6)`, id, sample.ID, in.LaboratoryID, actor.ID(), in.Reason, observedAt); err != nil {
			return err
		}
		if err := a.flagException(ctx, tx, actor, sample.ID, "laboratory_exception", in.Reason, map[string]any{"exceptionId": id, "laboratoryId": in.LaboratoryID, "observedAt": fmtTime(observedAt)}); err != nil {
			return err
		}
		if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, nil); err != nil {
			return err
		}
		if err := setJourneyStatus(ctx, tx, j.ID, JourneyException, "exception"); err != nil {
			return err
		}
		if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
			return err
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "laboratory.exception_recorded", EntityType: "sample", EntityID: sample.ID, Success: true, SampleIDs: []string{sample.ID}, Details: map[string]any{"exceptionId": id, "laboratoryId": in.LaboratoryID, "reason": in.Reason, "observedAt": fmtTime(observedAt)}}); err != nil {
			return err
		}
		out = map[string]any{"exceptionId": id, "sampleId": sample.ID, "status": "exception", "reason": in.Reason}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

