// position describes where a journey's samples currently are, which decides
// what unfinished work can be replanned.
type position struct {
	Kind               string // origin, node, transit, laboratory, terminal
	NodeID             string
	Preserved          []*Assignment
	SkipCollection     bool
	FirstStopIsHandoff bool
	Sealed             bool
}

func (a *App) journeyPosition(ctx context.Context, q Q, j *Journey) (*position, []*Assignment, *Sample, *Request, error) {
	if len(j.SampleIDs) == 0 {
		return nil, nil, nil, nil, Conflict("invalid_plan", "journey has no samples")
	}
	sample, err := loadSample(ctx, q, j.SampleIDs[0])
	if err != nil {
		return nil, nil, nil, nil, err
	}
	req, err := loadRequest(ctx, q, sample.RequestID)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	asgs, err := loadJourneyAssignments(ctx, q, j)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	pos := &position{Kind: "origin", Sealed: sample.Sealed, SkipCollection: sample.Sealed}
	if req.OriginType == "node" && req.OriginNodeID != nil {
		pos.Kind = "node"
		pos.NodeID = *req.OriginNodeID
	}
	if terminalSample(sample.Status) {
		pos.Kind = "terminal"
		return pos, asgs, sample, req, nil
	}
	for _, asg := range asgs {
		if asg.Status == AsgCancelled {
			continue
		}
		if assignmentFinished(asg.Status) {
			pos.Preserved = append(pos.Preserved, asg)
			continue
		}
		holder := sample.CurrentHolderID != nil && asg.WorkerID != nil && *asg.WorkerID == *sample.CurrentHolderID
		switch asg.Kind {
		case KindCollection:
			if asg.Status == AsgInProgress || (holder && sample.Sealed) {
				pos.Preserved = append(pos.Preserved, asg)
				pos.SkipCollection = true
			} else if asg.Status == AsgAccepted {
				// Keep an accepted collector when they remain available.
				if u, err := loadUser(ctx, q, *asg.WorkerID); err == nil && u.Active && u.Available && workerEligible(u, asg, Now()) {
					pos.Preserved = append(pos.Preserved, asg)
					pos.SkipCollection = true
				}
			}
		case KindTransport:
			if assignmentStarted(asg.Status) {
				pos.Preserved = append(pos.Preserved, asg)
				pos.Kind = "transit"
				pos.FirstStopIsHandoff = true
				if asg.ToLocationID != nil {
					pos.NodeID = *asg.ToLocationID
				}
			}
		case KindNode:
			if asg.Status == AsgInProgress {
				pos.Preserved = append(pos.Preserved, asg)
				pos.Kind = "node"
				pos.FirstStopIsHandoff = false
				if asg.LocationID != nil {
					pos.NodeID = *asg.LocationID
				}
			}
		case KindLaboratory:
			if asg.Status == AsgInProgress {
				pos.Preserved = append(pos.Preserved, asg)
				pos.Kind = "laboratory"
			}
		}
	}
	return pos, asgs, sample, req, nil
}

func (p *position) routeInput(req *Request, st *SampleType, deadline time.Time, now time.Time, units int) routeInput {
	in := routeInput{SampleType: st, Start: now, Deadline: deadline, Units: units, Presealed: p.SkipCollection}
	switch p.Kind {
	case "node", "transit":
		in.OriginType = "node"
		in.OriginNodeID = p.NodeID
		in.Presealed = true
	default:
		in.OriginType = req.OriginType
		in.OriginLat, in.OriginLon = req.OriginLatitude, req.OriginLongitude
		if req.OriginType == "node" && req.OriginNodeID != nil {
			in.OriginNodeID = *req.OriginNodeID
		}
		if req.EarliestCollectionAt.After(in.Start) && !p.SkipCollection {
			in.Start = req.EarliestCollectionAt
		}
	}
	return in
}

type replanResult struct {
	Status      string
	Replacement *Journey
}

// replanJourney replaces the unfinished part of an active journey with a new
// plan. explicitPath, when given, forces the remaining node sequence.
func (a *App) replanJourney(ctx context.Context, tx pgx.Tx, actor *Actor, j *Journey, reason string, explicitPath []string, now time.Time) (*replanResult, error) {
	if j.Status != JourneyActive {
		return &replanResult{Status: "not_required"}, nil
	}
	pos, _, sample, req, err := a.journeyPosition(ctx, tx, j)
	if err != nil {
		return nil, err
	}
	if pos.Kind == "terminal" || pos.Kind == "laboratory" {
		return &replanResult{Status: "not_required"}, nil
	}
	st, err := loadSampleType(ctx, tx, req.SampleTypeID)
	if err != nil {
		return nil, err
	}
	deadline := req.DeliveryDeadline
	for _, sid := range j.SampleIDs[1:] {
		if s, err := loadSample(ctx, tx, sid); err == nil {
			if r, err := loadRequest(ctx, tx, s.RequestID); err == nil && r.DeliveryDeadline.Before(deadline) {
				deadline = r.DeliveryDeadline
			}
		}
	}
	usageMap, err := usageExcluding(ctx, tx, []string{j.ID})
	if err != nil {
		return nil, err
	}
	snap := a.Snapshot()
	ri := pos.routeInput(req, st, deadline, now, len(j.SampleIDs))
	ri.ExcludeJourneyID = j.ID
	var plan *routePlan
	failure := ""
	if explicitPath != nil {
		plan, err = snap.planExplicitPath(ri, explicitPath, usageMap)
		if err != nil {
			return nil, err
		}
	} else if !pos.SkipCollection && ri.Start.After(req.LatestCollectionAt) {
		failure = ReasonDeadline
	} else {
		plan, failure = snap.evaluate(ri, usageMap)
	}
	if plan == nil {
		if err := a.failJourney(ctx, tx, actor, j, failure, reason); err != nil {
			return nil, err
		}
		if failure == ReasonDeadline {
			return &replanResult{Status: "expired"}, nil
		}
		return &replanResult{Status: "exception"}, nil
	}
	// Replacement plans always keep the current holder; only unfinished work changes.
	keep := map[string]bool{}
	for _, p := range pos.Preserved {
		keep[p.ID] = true
	}
	if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, keep); err != nil {
		return nil, err
	}
	if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
		return nil, err
	}
	b := journeyBuild{SampleIDs: j.SampleIDs, SampleType: st, Plan: plan, OriginType: ri.OriginType, OriginLat: ri.OriginLat, OriginLon: ri.OriginLon, OriginNodeID: ri.OriginNodeID,
		SkipCollection: pos.SkipCollection, FirstStopIsHandoff: pos.FirstStopIsHandoff, ParentJourneyID: &j.ID, Preserved: pos.Preserved, Now: now, Units: len(j.SampleIDs), ExcludeJourneyIDs: []string{j.ID}}
	if pos.Kind == "transit" || pos.Kind == "node" {
		b.OriginType = "node"
	}
	nj, asgs, err := a.buildJourney(ctx, tx, b)
	if err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = 'replaced', replacement_journey_id = $3, plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, JourneyReplaced, nj.ID); err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2, updated_at = now() WHERE id = ANY($1)`, j.SampleIDs, nj.ID); err != nil {
		return nil, err
	}
	if err := a.offerAll(ctx, tx, actor, asgs, now); err != nil {
		return nil, err
	}
	details := map[string]any{"previousJourneyId": j.ID, "replacementJourneyId": nj.ID, "reason": reason, "position": pos.Kind, "path": plan.Path, "estimatedDeliveryAt": fmtTime(plan.ETA), "currentHolderId": sample.CurrentHolderID}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.replanned", EntityType: "journey", EntityID: j.ID, Success: true, SampleIDs: j.SampleIDs, Details: details}); err != nil {
		return nil, err
	}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.created", EntityType: "journey", EntityID: nj.ID, Success: true, SampleIDs: j.SampleIDs, Details: details}); err != nil {
		return nil, err
	}
	if err := a.Emit(ctx, tx, Event{Type: "journey.replanned", EntityType: "journey", EntityID: j.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, UserIDs: []string{req.RequesterID}, Payload: details}); err != nil {
		return nil, err
	}
	return &replanResult{Status: "replaced", Replacement: nj}, nil
}

// failJourney records that no valid plan exists: expired when the deadline is
// unreachable, otherwise an exception.
func (a *App) failJourney(ctx context.Context, tx pgx.Tx, actor *Actor, j *Journey, failure, reason string) error {
	if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, nil); err != nil {
		return err
	}
	if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
		return err
	}
	status, replan := JourneyException, "exception"
	if failure == ReasonDeadline {
		status, replan = JourneyExpired, "expired"
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = $3, plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, status, replan); err != nil {
		return err
	}
	for _, sid := range j.SampleIDs {
		if failure == ReasonDeadline {
			exc := map[string]any{"reason": "deadline_unreachable", "message": "no valid route can meet the delivery deadline", "trigger": reason, "flaggedAt": fmtTime(Now())}
			if err := setSampleStatus(ctx, tx, sid, SampleExpired, exc); err != nil {
				return err
			}
			if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "sample.status.expired", EntityType: "sample", EntityID: sid, Success: true, SampleIDs: []string{sid}, Details: exc}); err != nil {
				return err
			}
			if err := a.Emit(ctx, tx, Event{Type: "sample.expired", EntityType: "sample", EntityID: sid, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: exc}); err != nil {
				return err
			}
		} else {
			if err := a.flagException(ctx, tx, actor, sid, "no_valid_route", "no valid replacement route is available: "+failure, map[string]any{"trigger": reason}); err != nil {
				return err
			}
		}
	}
	return a.Audit(ctx, tx, actor, AuditEvent{Action: "journey." + status, EntityType: "journey", EntityID: j.ID, Success: true, SampleIDs: j.SampleIDs, Details: map[string]any{"failure": failure, "reason": reason}})
}

// planExplicitPath validates and times a dispatcher-chosen node sequence.
func (s *serviceabilitySnapshot) planExplicitPath(in routeInput, path []string, usageMap map[string]usage) (*routePlan, error) {
	if len(path) == 0 {
		return nil, Conflict("invalid_route", "the route must contain at least the laboratory")
	}
	units := in.Units
	if units <= 0 {
		units = 1
	}
	cooled := in.SampleType.RequiresCooledRoute
	best := map[string]*routeState{}
	first := s.Locations[path[0]]
	if first == nil || !first.Active {
		return nil, Conflict("invalid_stop", "the first stop is not an active location")
	}
	st := &routeState{}
	if in.OriginType == "node" {
		if in.OriginNodeID != path[0] {
			return nil, Conflict("invalid_route", "the route must start at the sample's current node")
		}
		st.arrive = in.Start
		st.depart = in.Start.Add(time.Duration(first.HandlingMinutes) * time.Minute)
	} else {
		fm := geo.FirstMileMinutes(geo.DistanceKm(in.OriginLat, in.OriginLon, first.Latitude, first.Longitude))
		st.firstMile = fm
		st.arrive = in.Start.Add(time.Duration(collectionHandlingMinutes+fm) * time.Minute)
		if in.Presealed {
			st.arrive = in.Start.Add(time.Duration(fm) * time.Minute)
		}
		st.depart = st.arrive.Add(time.Duration(first.HandlingMinutes) * time.Minute)
	}
	best[path[0]] = st
	for i := 0; i < len(path); i++ {
		l := s.Locations[path[i]]
		if l == nil || !l.Active {
			return nil, Conflict("invalid_stop", "stop "+path[i]+" is not an active location")
		}
		if availableUnits(l.CapacityUnits, l.CooledCapacityUnits, usageMap[l.ID], cooled) < units {
			if cooled {
				return nil, Conflict("cooled_capacity_exhausted", "no cooled capacity at "+l.Name)
			}
			return nil, Conflict("capacity_exhausted", "no capacity at "+l.Name)
		}
		if i == len(path)-1 {
			break
		}
		if i > 0 && !(l.Hub || l.TransferPoint) {
			return nil, Conflict("invalid_stop", l.Name+" cannot act as a transfer point")
		}
		var conn *Connection
		for _, c := range s.Outgoing[path[i]] {
			if c.ToLocationID == path[i+1] && c.Active && (!cooled || c.Cooled) {
				if conn == nil || c.TravelMinutes < conn.TravelMinutes {
					conn = c
				}
			}
		}
		if conn == nil {
			return nil, Conflict("invalid_route", fmt.Sprintf("no active connection from %s to %s", path[i], path[i+1]))
		}
		if availableUnits(conn.CapacityUnits, conn.CooledCapacityUnits, usageMap[conn.ID], cooled) < units {
			return nil, Conflict("capacity_exhausted", "no capacity on the connection")
		}
		next := s.Locations[path[i+1]]
		if next == nil || !next.Active {
			return nil, Conflict("invalid_stop", "stop is not an active location")
		}
		prev := best[path[i]]
		arrive := prev.depart.Add(time.Duration(conn.TravelMinutes) * time.Minute)
		best[path[i+1]] = &routeState{arrive: arrive, depart: arrive.Add(time.Duration(next.HandlingMinutes) * time.Minute), cost: prev.cost + conn.CostUnits, prev: path[i], prevConn: conn.ID, firstMile: prev.firstMile}
	}
	lab := path[len(path)-1]
	if !s.labAccepts(lab, in.SampleType.ID) {
		return nil, Conflict("invalid_destination", "the final stop is not an active laboratory accepting this sample type")
	}
	eta := best[lab].arrive.Add(time.Duration(s.Locations[lab].HandlingMinutes) * time.Minute)
	if eta.After(in.Deadline) {
		return nil, Conflict("deadline_exceeded", "the route cannot meet the delivery deadline")
	}
	return s.buildPlan(lab, best, eta, in), nil
}

func (a *App) checkPlanVersion(j *Journey, expected int) error {
	if expected < 1 {
		return BadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	if j.Status != JourneyActive {
		return Conflict("inactive_plan", "the journey is not active")
	}
	if j.PlanVersion != expected {
		return Conflict("stale_plan", fmt.Sprintf("expectedPlanVersion %d does not match current plan version %d", expected, j.PlanVersion))
	}
	return nil
}

func (a *App) CancelJourney(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.JourneyID == "" || in.ExpectedPlanVersion == nil {
		return 0, nil, InvalidJSON("journeyId and expectedPlanVersion are required")
	}
	if *in.ExpectedPlanVersion < 1 {
		return 0, nil, BadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		j, err := loadJourney(ctx, tx, in.JourneyID, true)
		if err != nil {
			return err
		}
		if err := a.checkPlanVersion(j, *in.ExpectedPlanVersion); err != nil {
			return err
		}
		if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, nil); err != nil {
			return err
		}
		if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = 'not_required', plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, JourneyCancelled); err != nil {
			return err
		}
		for _, sid := range j.SampleIDs {
			if err := a.transitionSample(ctx, tx, actor, sid, SampleCancelled, map[string]any{"journeyId": j.ID, "reason": in.Reason}); err != nil {
				return err
			}
		}
		if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.cancelled", EntityType: "journey", EntityID: j.ID, Success: true, SampleIDs: j.SampleIDs, Details: map[string]any{"reason": in.Reason}}); err != nil {
			return err
		}
		if err := a.Emit(ctx, tx, Event{Type: "journey.cancelled", EntityType: "journey", EntityID: j.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: map[string]any{"journeyId": j.ID, "sampleIds": j.SampleIDs}}); err != nil {
			return err
		}
		out = map[string]any{"journeyId": j.ID, "status": "cancelled", "sampleIds": j.SampleIDs}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) RerouteJourney(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.JourneyID == "" || in.ExpectedPlanVersion == nil {
		return 0, nil, InvalidJSON("journeyId and expectedPlanVersion are required")
	}
	if *in.ExpectedPlanVersion < 1 {
		return 0, nil, BadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		j, err := loadJourney(ctx, tx, in.JourneyID, true)
		if err != nil {
			return err
		}
		if err := a.checkPlanVersion(j, *in.ExpectedPlanVersion); err != nil {
			return err
		}
		res, err := a.replanJourney(ctx, tx, actor, j, "reroute: "+in.Reason, nil, Now())
		if err != nil {
			return err
		}
		out = map[string]any{"journeyId": j.ID, "replanStatus": res.Status}
		if res.Replacement != nil {
			out["replacementPlanId"] = res.Replacement.ID
			plan, err := a.journeyPlanView(ctx, tx, res.Replacement)
			if err != nil {
				return err
			}
			out["replacementJourney"] = plan
		}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) ReportDisruption(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		OccurredAt   string `json:"occurredAt"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.ResourceType == "" || in.ResourceID == "" {
		return 0, nil, InvalidJSON("resourceType, resourceId and occurredAt are required")
	}
	if !contains([]string{"location", "node", "laboratory", "connection", "route", "worker", "capacity"}, in.ResourceType) {
		return 0, nil, BadRequest("invalid_resource_type", "unknown resourceType")
	}
	occurredAt, err := parseTime(in.OccurredAt, "occurredAt")
	if err != nil {
		return 0, nil, err
	}
	// Mark the resource unavailable first so replanning cannot reuse it.
	resourceKind := in.ResourceType
	err = a.Tx(ctx, func(tx pgx.Tx) error {
		switch in.ResourceType {
		case "location", "node", "laboratory":
			if _, err := loadLocation(ctx, tx, in.ResourceID); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `UPDATE locations SET active = false, updated_at = now() WHERE id = $1`, in.ResourceID); err != nil {
				return err
			}
			resourceKind = "location"
			return bumpNetworkRevision(ctx, tx)
		case "connection":
			if _, err := loadConnection(ctx, tx, in.ResourceID); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `UPDATE connections SET active = false, updated_at = now() WHERE id = $1`, in.ResourceID); err != nil {
				return err
			}
			return bumpNetworkRevision(ctx, tx)
		case "worker":
			if _, err := loadUser(ctx, tx, in.ResourceID); err != nil {
				return err
			}
			_, err := tx.Exec(ctx, `UPDATE users SET available = false, updated_at = now() WHERE id = $1`, in.ResourceID)
			return err
		case "capacity":
			if _, err := loadLocation(ctx, tx, in.ResourceID); err == nil {
				if _, err := tx.Exec(ctx, `UPDATE locations SET capacity_units = 0, cooled_capacity_units = 0, updated_at = now() WHERE id = $1`, in.ResourceID); err != nil {
					return err
				}
				resourceKind = "location"
			} else if _, err := loadConnection(ctx, tx, in.ResourceID); err == nil {
				if _, err := tx.Exec(ctx, `UPDATE connections SET capacity_units = 0, cooled_capacity_units = 0, updated_at = now() WHERE id = $1`, in.ResourceID); err != nil {
					return err
				}
				resourceKind = "connection"
			} else {
				return NotFound("capacity pool not found")
			}
			return bumpNetworkRevision(ctx, tx)
		case "route":
			if _, err := loadJourney(ctx, tx, in.ResourceID, false); err != nil {
				return err
			}
			resourceKind = "route"
		}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	a.refreshSnapshotLogged(ctx)
	affected, replacements, status := a.replanForResource(ctx, actor, resourceKind, in.ResourceID, "disruption: "+in.Reason)
	id := NewID()
	_, err = a.Pool.Exec(ctx, `INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, actor_id, affected_sample_ids, replacement_plan_ids, replan_status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, in.ResourceType, in.ResourceID, in.Reason, occurredAt, actor.ID(), affected, replacements, status)
	if err != nil {
		return 0, nil, err
	}
	a.AuditOutsideTx(ctx, actor, AuditEvent{Action: "disruption.reported", EntityType: in.ResourceType, EntityID: in.ResourceID, Success: true, SampleIDs: affected,
		Details: map[string]any{"disruptionId": id, "reason": in.Reason, "occurredAt": fmtTime(occurredAt), "affectedSampleIds": affected, "replacementPlanIds": replacements, "replanStatus": status}})
	return 201, map[string]any{"disruptionId": id, "affectedSampleIds": affected, "replacementPlanIds": replacements, "replanStatus": status}, nil
}

// replanForResource replans every active journey whose unfinished work
// depends on the resource. It returns affected sample ids, replacement plan
// ids and an aggregate replan status.
func (a *App) replanForResource(ctx context.Context, actor *Actor, resourceType, resourceID, reason string) ([]string, []string, string) {
	affected, replacements := []string{}, []string{}
	status := "not_required"
	var journeyIDs []string
	var err error
	switch {
	case resourceType == "location" || len(resourceType) > 18 && resourceType[:18] == "location_function:":
		journeyIDs, err = queryIDs(ctx, a.Pool, `SELECT DISTINCT j.id FROM journeys j WHERE j.status = 'active' AND (
			j.target_laboratory_id = $1
			OR EXISTS (SELECT 1 FROM journey_stops s WHERE s.journey_id = j.id AND s.location_id = $1 AND s.completed_at IS NULL)
			OR EXISTS (SELECT 1 FROM assignments a WHERE a.journey_id = j.id AND a.status NOT IN ('completed','cancelled','delivered') AND (a.location_id = $1 OR a.to_location_id = $1)))`, resourceID)
	case resourceType == "connection":
		journeyIDs, err = queryIDs(ctx, a.Pool, `SELECT DISTINCT j.id FROM journeys j JOIN assignments a ON a.journey_id = j.id WHERE j.status = 'active' AND a.connection_id = $1 AND a.status NOT IN ('completed','cancelled','delivered','picked_up','in_transit','arrived')`, resourceID)
	case resourceType == "worker":
		journeyIDs, err = queryIDs(ctx, a.Pool, `SELECT DISTINCT j.id FROM journeys j JOIN assignments a ON a.journey_id = j.id WHERE j.status = 'active' AND a.worker_id = $1 AND a.status IN ('offered','accepted','at_pickup')`, resourceID)
	case resourceType == "route":
		journeyIDs = []string{resourceID}
	case len(resourceType) > 22 && resourceType[:22] == "laboratory_acceptance:":
		journeyIDs, err = queryIDs(ctx, a.Pool, `SELECT DISTINCT j.id FROM journeys j JOIN samples s ON s.id = ANY(j.sample_ids) JOIN collection_requests r ON r.id = s.request_id WHERE j.status = 'active' AND j.target_laboratory_id = $1 AND r.sample_type_id = $2`, resourceID, resourceType[22:])
	}
	if err != nil {
		log.Printf("replan lookup failed: %v", err)
		return affected, replacements, status
	}
	now := Now()
	for _, jid := range journeyIDs {
		var res *replanResult
		err := a.Tx(ctx, func(tx pgx.Tx) error {
			j, err := loadJourney(ctx, tx, jid, true)
			if err != nil {
				return err
			}
			affected = append(affected, j.SampleIDs...)
			res, err = a.replanJourney(ctx, tx, actor, j, reason, nil, now)
			return err
		})
		if err != nil {
			log.Printf("replan of journey %s failed: %v", jid, err)
			continue
		}
		if res.Replacement != nil {
			replacements = append(replacements, res.Replacement.ID)
		}
		status = mergeReplanStatus(status, res.Status)
	}
	a.refreshSnapshotLogged(ctx)
	return affected, replacements, status
}

func mergeReplanStatus(cur, next string) string {
	rank := map[string]int{"not_required": 0, "exception": 1, "expired": 2, "replaced": 3}
	if rank[next] > rank[cur] {
		return next
	}
	return cur
}

func queryIDs(ctx context.Context, q Q, sql string, args ...any) ([]string, error) {
	rows, err := q.Query(ctx, sql, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}
