			return err
		}
		jv, err := a.journeyPlanView(ctx, tx, j2)
		if err != nil {
			return err
		}
		sv, err := a.journeyPlanView(ctx, tx, nj)
		if err != nil {
			return err
		}
		out = map[string]any{"journey": jv, "splitJourney": sv}
		return nil
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

func (a *App) splitJourneyTx(ctx context.Context, tx pgx.Tx, actor *Actor, j *Journey, sampleIDs []string, now time.Time) (*Journey, error) {
	if len(sampleIDs) == 0 || len(sampleIDs) >= len(j.SampleIDs) {
		return nil, Conflict("invalid_split", "sampleIds must be a strict non-empty subset of the journey's samples")
	}
	seen := map[string]bool{}
	for _, sid := range sampleIDs {
		if !contains(j.SampleIDs, sid) || seen[sid] {
			return nil, Conflict("invalid_split", "sampleIds must belong to the journey")
		}
		seen[sid] = true
	}
	asgs, err := loadJourneyAssignments(ctx, tx, j)
	if err != nil {
		return nil, err
	}
	for _, asg := range asgs {
		if asg.Kind == KindTransport && assignmentStarted(asg.Status) && asg.Status != AsgCancelled {
			return nil, Conflict("split_in_progress", "the batch is already in transit; it cannot be split")
		}
	}
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if !seen[sid] {
			remaining = append(remaining, sid)
		}
	}
	first, err := loadSample(ctx, tx, sampleIDs[0])
	if err != nil {
		return nil, err
	}
	req, err := loadRequest(ctx, tx, first.RequestID)
	if err != nil {
		return nil, err
	}
	st, err := loadSampleType(ctx, tx, req.SampleTypeID)
	if err != nil {
		return nil, err
	}
	// Move the split samples' collection assignments; batch assignments drop them.
	var movedCollections []*Assignment
	for _, asg := range asgs {
		if asg.JourneyID != j.ID {
			continue
		}
		if asg.Kind == KindCollection {
			if len(asg.SampleIDs) == 1 && seen[asg.SampleIDs[0]] && !assignmentFinished(asg.Status) {
				movedCollections = append(movedCollections, asg)
			}
			continue
		}
		newIDs := []string{}
		for _, sid := range asg.SampleIDs {
			if !seen[sid] {
				newIDs = append(newIDs, sid)
			}
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET sample_ids = $2, updated_at = now() WHERE id = $1`, asg.ID, newIDs); err != nil {
			return nil, err
		}
	}
	if err := releaseReservations(ctx, tx, j.ID, sampleIDs); err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, `DELETE FROM journey_stops WHERE journey_id = $1 AND stop_type = 'pickup' AND sample_id = ANY($2)`, j.ID, sampleIDs); err != nil {
		return nil, err
	}
	// Position of the split samples.
	pos := &position{Kind: "origin", SkipCollection: first.Sealed || len(movedCollections) > 0}
	if first.Status == SampleAtNode {
		for _, asg := range asgs {
			if asg.Kind == KindNode && asg.Status == AsgInProgress && asg.LocationID != nil {
				pos.Kind, pos.NodeID = "node", *asg.LocationID
				pos.Preserved = append(pos.Preserved, asg)
			}
		}
	}
	deadline := req.DeliveryDeadline
	usageMap, err := usageExcluding(ctx, tx, nil)
	if err != nil {
		return nil, err
	}
	ri := pos.routeInput(req, st, deadline, now, len(sampleIDs))
	plan, failure := a.Snapshot().evaluate(ri, usageMap)
	if plan == nil {
		return nil, Conflict(mapFailure(failure), "the split samples cannot be routed: "+failure)
	}
	b := journeyBuild{SampleIDs: sampleIDs, SampleType: st, Plan: plan, OriginType: ri.OriginType, OriginLat: ri.OriginLat, OriginLon: ri.OriginLon, OriginNodeID: ri.OriginNodeID,
		SkipCollection: pos.SkipCollection, ParentJourneyID: &j.ID, Preserved: pos.Preserved, Now: now, Units: len(sampleIDs)}
	nj, newAsgs, err := a.buildJourney(ctx, tx, b)
	if err != nil {
		return nil, err
	}
	for _, col := range movedCollections {
		if _, err := tx.Exec(ctx, `UPDATE assignments SET journey_id = $2, sequence = 0, updated_at = now() WHERE id = $1`, col.ID, nj.ID); err != nil {
			return nil, err
		}
	}
	mode := "direct"
	legs := 0
	for _, asg := range asgs {
		if asg.Kind == KindTransport && asg.JourneyID == j.ID && asg.Status != AsgCancelled {
			legs++
		}
	}
	if legs > 1 {
		mode = "multi_stop"
	}
	if len(remaining) > 1 {
		mode = "batched"
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET sample_ids = $2, split_journey_id = $3, route_mode = $4, plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, remaining, nj.ID, mode); err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2, updated_at = now() WHERE id = ANY($1)`, sampleIDs, nj.ID); err != nil {
		return nil, err
	}
	if err := a.offerAll(ctx, tx, actor, newAsgs, now); err != nil {
		return nil, err
	}
	details := map[string]any{"journeyId": j.ID, "splitJourneyId": nj.ID, "sampleIds": sampleIDs, "remainingSampleIds": remaining}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.split", EntityType: "journey", EntityID: j.ID, Success: true, SampleIDs: j.SampleIDs, Details: details}); err != nil {
		return nil, err
	}
	if err := a.Emit(ctx, tx, Event{Type: "journey.split", EntityType: "journey", EntityID: j.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: details}); err != nil {
		return nil, err
	}
	return nj, nil
}

func mapFailure(reason string) string {
	switch reason {
	case ReasonDeadline:
		return "deadline_exceeded"
	case ReasonCapacity:
		return "capacity_exhausted"
	case ReasonHandling:
		return "incompatible_batch"
	}
	return "no_valid_route"
}

func (a *App) MergeJourneys(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.TargetJourneyID == "" || in.ExpectedPlanVersion == nil || in.SourceJourneyIDs == nil {
		return 0, nil, InvalidJSON("targetJourneyId, expectedPlanVersion and sourceJourneyIds are required")
	}
	if *in.ExpectedPlanVersion < 1 {
		return 0, nil, BadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		j, err := loadJourney(ctx, tx, in.TargetJourneyID, true)
		if err != nil {
			return err
		}
		if err := a.checkPlanVersion(j, *in.ExpectedPlanVersion); err != nil {
			return err
		}
		if err := a.mergeJourneysTx(ctx, tx, actor, j, in.SourceJourneyIDs, Now()); err != nil {
			return err
		}
		j2, err := loadJourney(ctx, tx, j.ID, false)
		if err != nil {
			return err
		}
		out, err = a.journeyPlanView(ctx, tx, j2)
		return err
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

// remainingNetworkPath returns the location ids of the journey's stops that
// still lie ahead, excluding non-network pickups.
func remainingNetworkPath(stops []*Stop, originType string) []string {
	var path []string
	for _, s := range stops {
		if s.CompletedAt != nil || s.LocationID == nil {
			continue
		}
		if s.StopType == "pickup" && originType != "node" {
			continue
		}
		if len(path) > 0 && path[len(path)-1] == *s.LocationID {
			continue
		}
		path = append(path, *s.LocationID)
	}
	return path
}

func samePath(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (a *App) mergeJourneysTx(ctx context.Context, tx pgx.Tx, actor *Actor, target *Journey, sourceIDs []string, now time.Time) error {
	if len(sourceIDs) == 0 {
		return Conflict("invalid_merge", "sourceJourneyIds must not be empty")
	}
	tPos, tAsgs, tSample, tReq, err := a.journeyPosition(ctx, tx, target)
	if err != nil {
		return err
	}
	if tPos.Kind == "transit" || tPos.Kind == "laboratory" || tPos.Kind == "terminal" {
		return Conflict("work_in_progress", "the target journey is already in transit")
	}
	tType, err := loadSampleType(ctx, tx, tReq.SampleTypeID)
	if err != nil {
		return err
	}
	tStops, err := loadStops(ctx, tx, target.ID)
	if err != nil {
		return err
	}
	tPath := remainingNetworkPath(tStops, tReq.OriginType)
	if tPos.Kind == "node" {
		tPath = trimPathTo(tPath, tPos.NodeID)
	}
	snap := a.Snapshot()
	type sourceInfo struct {
		j      *Journey
		sample *Sample
		req    *Request
		st     *SampleType
		asgs   []*Assignment
	}
	var sources []sourceInfo
	allTypes := []*SampleType{tType}
	allReqs := []*Request{tReq}
	seen := map[string]bool{target.ID: true}
	for _, sid := range sourceIDs {
		if seen[sid] {
			return Conflict("invalid_merge", "duplicate or self-referencing source journey")
		}
		seen[sid] = true
		sj, err := loadJourney(ctx, tx, sid, true)
		if err != nil {
			return err
		}
		if sj.Status != JourneyActive {
			return Conflict("invalid_merge", "source journey "+sid+" is not active")
		}
		sPos, sAsgs, sSample, sReq, err := a.journeyPosition(ctx, tx, sj)
		if err != nil {
			return err
		}
		for _, asg := range sAsgs {
			if asg.Kind == KindTransport && assignmentFinished(asg.Status) && asg.Status != AsgCancelled {
				return Conflict("partial_journey_merge", "source journey "+sid+" has completed transport legs")
			}
		}
		if sPos.Kind == "transit" || sPos.Kind == "laboratory" || sPos.Kind == "terminal" {
			return Conflict("work_in_progress", "source journey "+sid+" is already in transit")
		}
		sType, err := loadSampleType(ctx, tx, sReq.SampleTypeID)
		if err != nil {
			return err
		}
		if !sType.BatchingAllowed || !tType.BatchingAllowed {
			return Conflict("pulse_no_batch", "time-critical samples must not be batched")
		}
		sStops, err := loadStops(ctx, tx, sj.ID)
		if err != nil {
			return err
		}
		sPath := remainingNetworkPath(sStops, sReq.OriginType)
		if sPos.Kind == "node" {
			sPath = trimPathTo(sPath, sPos.NodeID)
		}
		if !samePath(sPath, tPath) || sj.TargetLaboratoryID == nil || target.TargetLaboratoryID == nil || *sj.TargetLaboratoryID != *target.TargetLaboratoryID {
			return Conflict("invalid_merge", "source journey "+sid+" does not share the target's remaining route")
		}
		if (sPos.Kind == "node") != (tPos.Kind == "node") || sPos.NodeID != tPos.NodeID {
			return Conflict("invalid_merge", "journeys must be at the same point of the network to merge")
		}
		if sType.RequiresCooledRoute != tType.RequiresCooledRoute {
			return Conflict("incompatible_batch", "cooled and uncooled samples cannot share a batch")
		}
		allTypes = append(allTypes, sType)
		allReqs = append(allReqs, sReq)
		sources = append(sources, sourceInfo{j: sj, sample: sSample, req: sReq, st: sType, asgs: sAsgs})
	}
	// Compatibility: no sample type may list another member as incompatible.
	for _, x := range allTypes {
		for _, y := range allTypes {
			if x.ID != y.ID && (contains(x.IncompatibleSampleTypes, y.ID) || strings.EqualFold(x.Name, "indigo") && strings.EqualFold(y.Name, "amber")) {
				return Conflict("incompatible_batch", x.Name+" samples must not share a container with "+y.Name)
			}
		}
	}
	for _, r := range allReqs {
		for _, y := range allTypes {
			if r.SampleTypeID != y.ID && contains(r.IncompatibleSampleTypes, y.ID) {
				return Conflict("incompatible_batch", "a request forbids travelling with another sample type in the batch")
			}
		}
	}
	// Deadlines: every sample must still be delivered in time on the target plan.
	if target.EstimatedDeliveryAt != nil {
		for _, s := range sources {
			if target.EstimatedDeliveryAt.After(s.req.DeliveryDeadline) {
				return Conflict("deadline_exceeded", "sample "+s.sample.ID+" cannot meet its deadline on the target plan")
			}
		}
	}
	// Capacity for the additional samples.
	added := 0
	var addedIDs []string
	for _, s := range sources {
		added += len(s.j.SampleIDs)
		addedIDs = append(addedIDs, s.j.SampleIDs...)
	}
	sourceJourneyIDs := []string{}
	for _, s := range sources {
		sourceJourneyIDs = append(sourceJourneyIDs, s.j.ID)
	}
	usageMap, err := usageExcluding(ctx, tx, sourceJourneyIDs)
	if err != nil {
		return err
	}
	tRes, err := loadReservations(ctx, tx, `WHERE journey_id = $1 AND status = 'active' AND sample_id = $2`, target.ID, tSample.ID)
	if err != nil {
		return err
	}
	cooled := tType.RequiresCooledRoute
	for _, r := range tRes {
		var cap, ccap int
		table := "locations"
		if r.ResourceType == "connection" {
			table = "connections"
		}
		if err := tx.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM `+table+` WHERE id = $1 FOR UPDATE`, r.ResourceID).Scan(&cap, &ccap); err != nil {
			return err
		}
		if availableUnits(cap, ccap, usageMap[r.ResourceID], cooled) < added {
			if cooled {
				return Conflict("cooled_capacity_exhausted", "insufficient cooled capacity on the target route")
			}
			return Conflict("capacity_exhausted", "insufficient capacity on the target route")
		}
		for _, sid := range addedIDs {
			if _, err := tx.Exec(ctx, `INSERT INTO capacity_reservations (id, journey_id, sample_id, resource_type, resource_id, cooled, units, status) VALUES ($1,$2,$3,$4,$5,$6,1,'active')`, NewID(), target.ID, sid, r.ResourceType, r.ResourceID, r.Cooled); err != nil {
				return err
			}
		}
	}
	// Apply: move samples and collection assignments, retire sources.
	newSampleIDs := append(append([]string{}, target.SampleIDs...), addedIDs...)
	for _, asg := range tAsgs {
		if asg.Kind == KindCollection || asg.JourneyID != target.ID || assignmentFinished(asg.Status) {
			continue
		}
		if _, err := tx.Exec(ctx, `UPDATE assignments SET sample_ids = $2, updated_at = now() WHERE id = $1`, asg.ID, newSampleIDs); err != nil {
			return err
		}
	}
	maxPickup := 0
	for _, s := range tStops {
		if s.StopType == "pickup" && s.Sequence > maxPickup {
			maxPickup = s.Sequence
		}
	}
	for _, s := range sources {
		for _, asg := range s.asgs {
			if asg.JourneyID != s.j.ID {
				continue
			}
			if asg.Kind == KindCollection && !assignmentFinished(asg.Status) {
				if _, err := tx.Exec(ctx, `UPDATE assignments SET journey_id = $2, sequence = 0, updated_at = now() WHERE id = $1`, asg.ID, target.ID); err != nil {
					return err
				}
			}
		}
		if _, err := cancelUnfinishedAssignments(ctx, tx, s.j.ID, nil); err != nil {
			return err
		}
		if err := releaseReservations(ctx, tx, s.j.ID, nil); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = 'replaced', replacement_journey_id = $3, plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, s.j.ID, JourneyMerged, target.ID); err != nil {
			return err
		}
		if s.req.OriginType != "node" && tPos.Kind == "origin" {
			if _, err := tx.Exec(ctx, `UPDATE journey_stops SET sequence = sequence + 1 WHERE journey_id = $1 AND sequence > $2`, target.ID, maxPickup); err != nil {
				return err
			}
			maxPickup++
			if _, err := tx.Exec(ctx, `INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, sample_id)
				VALUES ($1,$2,$3,'pickup',$4,$5,$6,$7,$8,$9)`, NewID(), target.ID, s.j.TargetLaboratoryID, maxPickup, now, collectionHandlingMinutes, s.req.OriginLatitude, s.req.OriginLongitude, s.sample.ID); err != nil {
				return err
			}
		}
	}
	if _, err := tx.Exec(ctx, `UPDATE samples SET active_journey_id = $2, updated_at = now() WHERE id = ANY($1)`, addedIDs, target.ID); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, `UPDATE journeys SET sample_ids = $2, route_mode = 'batched', plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, target.ID, newSampleIDs); err != nil {
		return err
	}
	_ = snap
	details := map[string]any{"targetJourneyId": target.ID, "sourceJourneyIds": sourceJourneyIDs, "sampleIds": newSampleIDs}
	if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.merged", EntityType: "journey", EntityID: target.ID, Success: true, SampleIDs: newSampleIDs, Details: details}); err != nil {
		return err
	}
	return a.Emit(ctx, tx, Event{Type: "journey.merged", EntityType: "journey", EntityID: target.ID, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: details})
}

func trimPathTo(path []string, node string) []string {
	for i, p := range path {
		if p == node {
			return path[i:]
		}
	}
	return path
}

func (a *App) EditActivePlan(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		JourneyID           string          `json:"journeyId"`
		ExpectedPlanVersion *int            `json:"expectedPlanVersion"`
		ChangeType          string          `json:"changeType"`
		Changes             json.RawMessage `json:"changes"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.JourneyID == "" || in.ExpectedPlanVersion == nil || in.ChangeType == "" {
		return 0, nil, InvalidJSON("journeyId, expectedPlanVersion, changeType and changes are required")
	}
	if *in.ExpectedPlanVersion < 1 {
		return 0, nil, BadRequest("invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	validTypes := []string{"add_stop", "remove_stop", "reorder_stops", "replace_worker", "reassign_worker", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route"}
	if !contains(validTypes, in.ChangeType) {
		return 0, nil, BadRequest("invalid_change_type", "unknown changeType")
	}
	var ch struct {
		AssignmentID    string   `json:"assignmentId"`
		WorkerID        string   `json:"workerId"`
		LocationID      string   `json:"locationId"`
		StopID          string   `json:"stopId"`
		AfterStopID     string   `json:"afterStopId"`
		AfterLocationID string   `json:"afterLocationId"`
		Position        *int     `json:"position"`
		DwellMinutes    *int     `json:"dwellMinutes"`
		StopIDs         []string `json:"stopIds"`
		OrderedStopIDs  []string `json:"orderedStopIds"`
		LocationIDs     []string `json:"locationIds"`
		Path            []string `json:"path"`
		SampleIDs       []string `json:"sampleIds"`
		SourceJourneys  []string `json:"sourceJourneyIds"`
		Reason          string   `json:"reason"`
	}
	if len(in.Changes) > 0 {
		if err := json.Unmarshal(in.Changes, &ch); err != nil {
			return 0, nil, InvalidJSON("changes must be an object")
		}
	}
	if ch.DwellMinutes != nil && (*ch.DwellMinutes < 0 || *ch.DwellMinutes > 1440) {
		return 0, nil, BadRequest("invalid_dwell", "dwellMinutes must be between 0 and 1440")
	}
	now := Now()
	var out map[string]any
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		j, err := loadJourney(ctx, tx, in.JourneyID, true)
		if err != nil {
			return err
		}
		if err := a.checkPlanVersion(j, *in.ExpectedPlanVersion); err != nil {
			return err
		}
		switch in.ChangeType {
		case "replace_worker", "reassign_worker":
			if ch.AssignmentID == "" || ch.WorkerID == "" {
				return BadRequest("invalid_worker", "changes.assignmentId and changes.workerId are required")
			}
			asg, err := loadAssignment(ctx, tx, ch.AssignmentID, true)
			if err != nil {
				return err
			}
			if asg.JourneyID != j.ID && !contains(j.PreservedAssignmentIDs, asg.ID) {
				return Conflict("invalid_assignment", "the assignment does not belong to the journey")
			}
			if assignmentFinished(asg.Status) {
				return Conflict("completed_work_immutable", "completed work cannot be reassigned")
			}
			if assignmentStarted(asg.Status) {
				return Conflict("work_in_progress", "work in progress cannot be reassigned")
			}
			w, err := loadUser(ctx, tx, ch.WorkerID)
			if err != nil {
				return BadRequest("invalid_worker", "workerId does not reference a user")
			}
			if !workerEligible(w, asg, now) {
				return Conflict("ineligible_worker", "the worker is not eligible for this assignment")
			}
			if !w.Available {
				return Conflict("worker_unavailable", "the worker is unavailable")
			}
			expires := now.Add(a.Cfg.OfferTimeout)
			if _, err := tx.Exec(ctx, `UPDATE assignments SET status = $2, worker_id = $3, offered_at = $4, offer_expires_at = $5, accepted_at = NULL, unassigned_since = NULL, updated_at = now() WHERE id = $1`, asg.ID, AsgOffered, w.ID, now, expires); err != nil {
				return err
			}
			if _, err := bumpPlanVersion(ctx, tx, j.ID); err != nil {
				return err
			}
			details := map[string]any{"assignmentId": asg.ID, "workerId": w.ID, "previousWorkerId": asg.WorkerID, "changeType": in.ChangeType}
			if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "assignment.reassigned", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: details}); err != nil {
				return err
			}
			if err := a.Emit(ctx, tx, Event{Type: "assignment.offered", EntityType: "assignment", EntityID: asg.ID, UserIDs: []string{w.ID}, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: details}); err != nil {
				return err
			}
		case "cancel_work":
			if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, nil); err != nil {
				return err
			}
			if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = 'not_required', plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, JourneyCancelled); err != nil {
				return err
			}
			for _, sid := range j.SampleIDs {
				if err := a.transitionSample(ctx, tx, actor, sid, SampleCancelled, map[string]any{"journeyId": j.ID, "reason": ch.Reason}); err != nil {
					return err
				}
			}
			if err := a.Audit(ctx, tx, actor, AuditEvent{Action: "journey.cancelled", EntityType: "journey", EntityID: j.ID, Success: true, SampleIDs: j.SampleIDs, Details: map[string]any{"reason": ch.Reason, "changeType": in.ChangeType}}); err != nil {
				return err
			}
		case "merge_samples":
			if err := a.mergeJourneysTx(ctx, tx, actor, j, ch.SourceJourneys, now); err != nil {
				return err
			}
		case "split_samples", "split_batch":
			if _, err := a.splitJourneyTx(ctx, tx, actor, j, ch.SampleIDs, now); err != nil {
				return err
			}
		case "reroute":
			if _, err := a.replanJourney(ctx, tx, actor, j, "edit: reroute "+ch.Reason, nil, now); err != nil {
				return err
			}
		case "replace_route", "add_stop", "remove_stop", "reorder_stops":
			path, err := a.editedPath(ctx, tx, j, in.ChangeType, ch.LocationID, ch.StopID, ch.AfterStopID, ch.AfterLocationID, ch.Position, ch.StopIDs, ch.OrderedStopIDs, ch.LocationIDs, ch.Path)
			if err != nil {
				return err
			}
			res, err := a.replanJourney(ctx, tx, actor, j, "edit: "+in.ChangeType, path, now)
			if err != nil {
				return err
			}
			if res.Status != "replaced" {
				return Conflict("invalid_plan", "the edited route could not be applied")
			}
		}
		j2, err := loadJourney(ctx, tx, j.ID, false)
		if err != nil {
			return err
		}
		out, err = a.journeyPlanView(ctx, tx, j2)
		return err
	})
	if err != nil {
		return 0, nil, err
	}
	return 201, out, nil
}

// editedPath derives the new remaining node path for a stop-level edit.
func (a *App) editedPath(ctx context.Context, tx pgx.Tx, j *Journey, changeType, locationID, stopID, afterStopID, afterLocationID string, pos *int, stopIDs, orderedStopIDs, locationIDs, explicit []string) ([]string, error) {
	position, _, _, req, err := a.journeyPosition(ctx, tx, j)
	if err != nil {
		return nil, err
	}
	stops, err := loadStops(ctx, tx, j.ID)
	if err != nil {
		return nil, err
	}
	// Remaining stops in order, excluding non-network pickups.
	var remaining []*Stop
	for _, s := range stops {
		if s.CompletedAt != nil || s.LocationID == nil || (s.StopType == "pickup" && req.OriginType != "node") {
			continue
		}
		if len(remaining) > 0 && *remaining[len(remaining)-1].LocationID == *s.LocationID {
			continue
		}
		remaining = append(remaining, s)
	}
	if position.Kind == "node" || position.Kind == "transit" {
		for i, s := range remaining {
			if *s.LocationID == position.NodeID {
				remaining = remaining[i:]
				break
			}
		}
	}
	path := make([]string, 0, len(remaining))
	for _, s := range remaining {
		path = append(path, *s.LocationID)
	}
	fixedHead := position.Kind == "node" || position.Kind == "transit" // the current node cannot change
	snap := a.Snapshot()
	connected := func(from, to string) bool {
		for _, c := range snap.Outgoing[from] {
			if c.ToLocationID == to && c.Active {
				return true
			}
		}
		return true && hasConn(snap, from, to)
	}
	switch changeType {
	case "replace_route":
		p := explicit
		if p == nil {
			p = locationIDs
		}
		if len(p) == 0 {
			return nil, Conflict("invalid_route", "changes.locationIds must list the remaining stops")
		}
		return p, nil
	case "add_stop":
		if locationID == "" {
			return nil, Conflict("invalid_stop", "changes.locationId is required")
		}
		if _, err := loadLocation(ctx, tx, locationID); err != nil {
			return nil, Conflict("invalid_stop", "locationId does not reference a location")
		}
		if contains(path, locationID) {
			return nil, Conflict("invalid_stop", "the location is already part of the route")
		}
		insertAt := -1
		switch {
		case afterStopID != "":
			for i, s := range remaining {
				if s.ID == afterStopID {
					insertAt = i + 1
				}
			}
			if insertAt < 0 {
				for _, s := range stops {
					if s.ID == afterStopID {
						return nil, Conflict("completed_work_immutable", "cannot add a stop after a completed stop")
					}
				}
				return nil, Conflict("invalid_stop", "afterStopId does not reference a remaining stop")
			}
		case afterLocationID != "":
			for i, p := range path {
				if p == afterLocationID {
					insertAt = i + 1
				}
			}
			if insertAt < 0 {
				return nil, Conflict("invalid_stop", "afterLocationId is not part of the remaining route")
			}
		case pos != nil:
			insertAt = *pos
		default:
			// Find every feasible insertion point; ambiguity must be resolved by the dispatcher.
			var feasible []int
			lo := 0
			if fixedHead {
				lo = 1
			}
			for i := lo; i < len(path); i++ {
				prevOK := i == 0 || connected(path[i-1], locationID)
				if prevOK && connected(locationID, path[i]) {
					feasible = append(feasible, i)
				}
			}
			if len(feasible) == 0 {
				return nil, Conflict("invalid_route", "no connections allow the stop to be inserted")
			}
			if len(feasible) > 1 {
				return nil, Conflict("ambiguous_stop", "several positions are possible; specify afterStopId or position")
			}
			insertAt = feasible[0]
		}
		if insertAt < 0 || insertAt > len(path)-1 || (fixedHead && insertAt == 0) {
			return nil, Conflict("invalid_stop_order", "the stop cannot be inserted at that position")
		}
		out := append([]string{}, path[:insertAt]...)
		out = append(out, locationID)
		out = append(out, path[insertAt:]...)
		return out, nil
	case "remove_stop":
		target := locationID
		if stopID != "" {
			for _, s := range stops {
				if s.ID == stopID {
					if s.CompletedAt != nil {
						return nil, Conflict("completed_work_immutable", "completed stops cannot be removed")
					}
					if s.LocationID != nil {
						target = *s.LocationID
					}
				}
			}
		}
		if target == "" {
			return nil, Conflict("invalid_stop", "changes.stopId or changes.locationId is required")
		}
		idx := -1
		for i, p := range path {
			if p == target {
				idx = i
			}
		}
		if idx < 0 {
			return nil, Conflict("invalid_stop", "the stop is not part of the remaining route")
		}
		if idx == len(path)-1 {
			return nil, Conflict("invalid_stop", "the delivery stop cannot be removed")
		}
		if idx == 0 && (fixedHead || req.OriginType == "node") {
			return nil, Conflict("invalid_stop", "the current stop cannot be removed")
		}
		out := append([]string{}, path[:idx]...)
		return append(out, path[idx+1:]...), nil
	case "reorder_stops":
		ids := orderedStopIDs
		if ids == nil {
			ids = stopIDs
		}
		var newPath []string
		if ids != nil {
			for _, id := range ids {
				found := false
				for _, s := range remaining {
					if s.ID == id {
						newPath = append(newPath, *s.LocationID)
						found = true
					}
				}
				if !found {
					for _, s := range stops {
						if s.ID == id && s.CompletedAt != nil {
							return nil, Conflict("completed_work_immutable", "completed stops cannot be reordered")
						}
					}
					return nil, Conflict("invalid_stop", "stop "+id+" is not part of the remaining route")
				}
			}
		} else {
			newPath = locationIDs
		}
		if len(newPath) == 0 {
			return nil, Conflict("ambiguous_stop_order", "the new stop order must be specified")
		}
		if len(newPath) != len(path) {
			return nil, Conflict("ambiguous_stop_order", "the new order must include every remaining stop exactly once")
		}
		counts := map[string]int{}
		for _, p := range path {
			counts[p]++
		}
		for _, p := range newPath {
			counts[p]--
		}
		for _, c := range counts {
			if c != 0 {
				return nil, Conflict("invalid_stop_order", "the new order must be a permutation of the remaining stops")
			}
		}
		if newPath[len(newPath)-1] != path[len(path)-1] {
			return nil, Conflict("invalid_stop_order", "the delivery stop must remain last")
		}
		if fixedHead && newPath[0] != path[0] {
			return nil, Conflict("invalid_stop_order", "the current stop must remain first")
		}
		return newPath, nil
	}
	return nil, Conflict("invalid_plan", "unsupported edit")
}

