func (a *App) journeyPlanViewDepth(ctx context.Context, q Q, j *Journey, depth int) (map[string]any, error) {
	stops, err := loadStops(ctx, q, j.ID)
	if err != nil {
		return nil, err
	}
	asgs, err := loadJourneyAssignments(ctx, q, j)
	if err != nil {
		return nil, err
	}
	stopsOut := make([]map[string]any, 0, len(stops))
	for _, s := range stops {
		stopsOut = append(stopsOut, stopView(s))
	}
	legs := []map[string]any{}
	workers := []string{}
	collections, nodes, labs, transports := []string{}, []string{}, []string{}, []string{}
	legSeq := 0
	for _, asg := range asgs {
		if asg.WorkerID != nil && !contains(workers, *asg.WorkerID) && asg.Status != AsgCancelled {
			workers = append(workers, *asg.WorkerID)
		}
		switch asg.Kind {
		case KindTransport:
			legSeq++
			legs = append(legs, legView(asg, legSeq))
			if asg.Status != AsgCancelled {
				transports = append(transports, asg.ID)
			}
		case KindCollection:
			collections = append(collections, asg.ID)
		case KindNode:
			nodes = append(nodes, asg.ID)
		case KindLaboratory:
			labs = append(labs, asg.ID)
		}
	}
	usageMap, err := usageExcluding(ctx, q, nil)
	if err != nil {
		return nil, err
	}
	used := 0
	avail := -1
	res, err := loadReservations(ctx, q, `WHERE journey_id = $1 AND status = 'active'`, j.ID)
	if err != nil {
		return nil, err
	}
	seenRes := map[string]bool{}
	for _, r := range res {
		used += r.Units
		if seenRes[r.ResourceID] {
			continue
		}
		seenRes[r.ResourceID] = true
		var cap, ccap int
		table := "locations"
		if r.ResourceType == "connection" {
			table = "connections"
		}
		if err := q.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM `+table+` WHERE id = $1`, r.ResourceID).Scan(&cap, &ccap); err == nil {
			av := availableUnits(cap, ccap, usageMap[r.ResourceID], r.Cooled)
			if avail < 0 || av < avail {
				avail = av
			}
		}
	}
	if avail < 0 {
		avail = 0
	}
	m := map[string]any{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "totalCostUnits": j.TotalCostUnits,
		"capacityUsed": used, "capacityAvailable": avail, "sampleIds": j.SampleIDs, "orderedStops": stopsOut, "legs": legs, "assignedWorkerIds": workers,
		"collectionAssignmentIds": collections, "nodeAssignmentIds": nodes, "laboratoryAssignmentIds": labs, "valid": j.Status == JourneyActive,
	}
	putIf(m, "parentJourneyId", j.ParentJourneyID)
	if j.EstimatedDeliveryAt != nil {
		m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if len(collections) > 0 {
		m["collectionAssignmentId"] = collections[0]
	}
	if len(transports) > 0 {
		m["firstTransportAssignmentId"] = transports[0]
		m["finalTransportAssignmentId"] = transports[len(transports)-1]
		if len(transports) >= 3 {
			m["middleTransportAssignmentId"] = transports[1]
		}
	}
	if j.ReplanStatus != "" {
		m["replanStatus"] = j.ReplanStatus
	}
	if depth == 0 {
		if j.SplitJourneyID != nil {
			if sj, err := loadJourney(ctx, q, *j.SplitJourneyID, false); err == nil {
				if v, err := a.journeyPlanViewDepth(ctx, q, sj, depth+1); err == nil {
					m["splitJourney"] = v
				}
			}
		}
		if j.ReplacementJourneyID != nil {
			if rj, err := loadJourney(ctx, q, *j.ReplacementJourneyID, false); err == nil {
				if v, err := a.journeyPlanViewDepth(ctx, q, rj, depth+1); err == nil {
					m["replacementJourney"] = v
				}
			}
		}
	}
	return m, nil
}

func (a *App) ReadJourneyPlan(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		JourneyID string `json:"journeyId"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.JourneyID == "" {
		return 0, nil, InvalidJSON("journeyId is required")
	}
	j, err := loadJourney(ctx, a.Pool, in.JourneyID, false)
	if err != nil {
		return 0, nil, err
	}
	switch actor.ActiveRole {
	case RoleAdministrator, RoleDispatcher:
		v, err := a.journeyPlanView(ctx, a.Pool, j)
		if err != nil {
			return 0, nil, err
		}
		return 200, v, nil
	case RoleRequester:
		owns := false
		for _, sid := range j.SampleIDs {
			if s, err := loadSample(ctx, a.Pool, sid); err == nil {
				if r, err := loadRequest(ctx, a.Pool, s.RequestID); err == nil && r.RequesterID == actor.ID() {
					owns = true
				}
			}
		}
		if !owns {
			return 0, nil, ForbiddenDefault()
		}
		full, err := a.journeyPlanView(ctx, a.Pool, j)
		if err != nil {
			return 0, nil, err
		}
		legs := []map[string]any{}
		for _, l := range full["legs"].([]map[string]any) {
			lm := map[string]any{"sequence": l["sequence"], "status": l["status"]}
			for _, k := range []string{"fromLocationId", "toLocationId"} {
				if v, ok := l[k]; ok {
					lm[k] = v
				}
			}
			legs = append(legs, lm)
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "totalCostUnits": j.TotalCostUnits, "sampleIds": j.SampleIDs, "orderedStops": full["orderedStops"], "legs": legs}
		putIf(out, "parentJourneyId", j.ParentJourneyID)
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
		}
		return 200, out, nil
	default:
		asgs, err := loadJourneyAssignments(ctx, a.Pool, j)
		if err != nil {
			return 0, nil, err
		}
		var mine []*Assignment
		for _, asg := range asgs {
			if asg.WorkerID != nil && *asg.WorkerID == actor.ID() {
				mine = append(mine, asg)
			}
		}
		if len(mine) == 0 {
			return 0, nil, ForbiddenDefault()
		}
		stops, err := loadStops(ctx, a.Pool, j.ID)
		if err != nil {
			return 0, nil, err
		}
		ids, legs, workers := []string{}, []map[string]any{}, []string{actor.ID()}
		relevant := map[string]bool{}
		collections, nodes, labs := []string{}, []string{}, []string{}
		for _, asg := range mine {
			ids = append(ids, asg.ID)
			switch asg.Kind {
			case KindTransport:
				legs = append(legs, legView(asg, asg.LegIndex))
				if asg.FromLocationID != nil {
					relevant[*asg.FromLocationID] = true
				}
				if asg.ToLocationID != nil {
					relevant[*asg.ToLocationID] = true
				}
			case KindCollection:
				collections = append(collections, asg.ID)
				relevant["pickup"] = true
			case KindNode:
				nodes = append(nodes, asg.ID)
				if asg.LocationID != nil {
					relevant[*asg.LocationID] = true
				}
			case KindLaboratory:
				labs = append(labs, asg.ID)
				if asg.LocationID != nil {
					relevant[*asg.LocationID] = true
				}
			}
		}
		stopsOut := []map[string]any{}
		for _, s := range stops {
			if (s.LocationID != nil && relevant[*s.LocationID]) || (s.StopType == "pickup" && relevant["pickup"]) {
				stopsOut = append(stopsOut, stopView(s))
			}
		}
		out := map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "scope": "assigned_legs", "assignmentIds": ids, "sampleIds": j.SampleIDs, "legs": legs, "orderedStops": stopsOut,
			"collectionAssignmentIds": collections, "nodeAssignmentIds": nodes, "laboratoryAssignmentIds": labs, "assignedWorkerIds": workers}
		putIf(out, "parentJourneyId", j.ParentJourneyID)
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
		}
		return 200, out, nil
	}
}

