// canViewSample enforces data-level access to a sample for the actor's role(s).
func (a *App) canViewSample(ctx context.Context, actor *Actor, s *Sample, req *Request) (bool, error) {
	roles := actor.EffectiveRoles(true)
	for _, r := range roles {
		switch r {
		case RoleAdministrator, RoleDispatcher:
			return true, nil
		case RoleRequester:
			if req.RequesterID == actor.ID() {
				return true, nil
			}
		default:
			if s.CurrentHolderID != nil && *s.CurrentHolderID == actor.ID() {
				return true, nil
			}
			var n int
			if err := a.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE worker_id = $1 AND $2 = ANY(sample_ids)`, actor.ID(), s.ID).Scan(&n); err != nil {
				return false, err
			}
			if n > 0 {
				return true, nil
			}
		}
	}
	return false, nil
}

func (a *App) activeAssignmentIDs(ctx context.Context, q Q, s *Sample) ([]string, error) {
	ids := []string{}
	if s.ActiveJourneyID == nil {
		return ids, nil
	}
	j, err := loadJourney(ctx, q, *s.ActiveJourneyID, false)
	if err != nil {
		return ids, nil
	}
	asgs, err := loadJourneyAssignments(ctx, q, j)
	if err != nil {
		return nil, err
	}
	for _, asg := range asgs {
		if contains(asg.SampleIDs, s.ID) && !assignmentFinished(asg.Status) {
			ids = append(ids, asg.ID)
		}
	}
	return ids, nil
}

func (a *App) ReadSampleState(ctx context.Context, actor *Actor, sampleID string) (int, any, error) {
	s, err := loadSample(ctx, a.Pool, sampleID)
	if err != nil {
		return 0, nil, err
	}
	req, err := loadRequest(ctx, a.Pool, s.RequestID)
	if err != nil {
		return 0, nil, err
	}
	ok, err := a.canViewSample(ctx, actor, s, req)
	if err != nil {
		return 0, nil, err
	}
	if !ok {
		return 0, nil, ForbiddenDefault()
	}
	timeline, err := a.sampleTimeline(ctx, a.Pool, s.ID)
	if err != nil {
		return 0, nil, err
	}
	active, err := a.activeAssignmentIDs(ctx, a.Pool, s)
	if err != nil {
		return 0, nil, err
	}
	m := map[string]any{
		"sampleId": s.ID, "requestId": req.ID, "requesterId": req.RequesterID, "origin": coord(req.OriginLatitude, req.OriginLongitude), "originType": req.OriginType,
		"requestedAt": fmtTime(req.RequestedAt), "deliveryDeadline": fmtTime(req.DeliveryDeadline), "sampleTypeId": req.SampleTypeID, "containerType": req.ContainerType,
		"temperatureMinC": req.TemperatureMinC, "temperatureMaxC": req.TemperatureMaxC, "incompatibleSampleTypes": req.IncompatibleSampleTypes, "serviceability": req.Serviceability,
		"activeAssignmentIds": active, "state": map[string]any{"status": s.Status}, "timeline": timeline, "locationStale": a.stale(s.LocationRecordedAt),
	}
	putIf(m, "activeJourneyId", s.ActiveJourneyID)
	putIf(m, "targetLaboratoryId", req.TargetLaboratoryID)
	if s.LatestLatitude != nil && s.LatestLongitude != nil {
		m["latestLocation"] = coord(*s.LatestLatitude, *s.LatestLongitude)
	}
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return 200, m, nil
}

func (a *App) ReadSampleLifecycle(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		SampleID string `json:"sampleId"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.SampleID == "" {
		return 0, nil, InvalidJSON("sampleId is required")
	}
	s, err := loadSample(ctx, a.Pool, in.SampleID)
	if err != nil {
		return 0, nil, err
	}
	req, err := loadRequest(ctx, a.Pool, s.RequestID)
	if err != nil {
		return 0, nil, err
	}
	ok, err := a.canViewSample(ctx, actor, s, req)
	if err != nil {
		return 0, nil, err
	}
	if !ok {
		return 0, nil, ForbiddenDefault()
	}
	timeline, err := a.sampleTimeline(ctx, a.Pool, s.ID)
	if err != nil {
		return 0, nil, err
	}
	completed, err := queryIDs(ctx, a.Pool, `SELECT id FROM assignments WHERE kind = 'transport' AND $1 = ANY(sample_ids) AND status IN ('delivered','completed') ORDER BY sequence`, s.ID)
	if err != nil {
		return 0, nil, err
	}
	if completed == nil {
		completed = []string{}
	}
	replacements, err := queryIDs(ctx, a.Pool, `SELECT id FROM journeys WHERE $1 = ANY(sample_ids) AND parent_journey_id IS NOT NULL AND status = 'active'`, s.ID)
	if err != nil {
		return 0, nil, err
	}
	if replacements == nil {
		replacements = []string{}
	}
	m := map[string]any{"sampleId": s.ID, "status": s.Status, "sealed": s.Sealed, "completedLegIds": completed, "activeReplacementPlanIds": replacements, "timeline": timeline, "locationStale": a.stale(s.LocationRecordedAt)}
	putIf(m, "activeJourneyId", s.ActiveJourneyID)
	putIf(m, "currentHolderId", s.CurrentHolderID)
	putIf(m, "receivedLaboratoryId", s.ReceivedLaboratoryID)
	if s.Exception != nil {
		m["exception"] = s.Exception
	}
	pending, err := loadHandoffs(ctx, a.Pool, `WHERE sample_id = $1 AND status = 'pending' ORDER BY initiated_at DESC LIMIT 1`, s.ID)
	if err != nil {
		return 0, nil, err
	}
	if len(pending) > 0 {
		h := pending[0]
		m["pendingHandoffId"] = h.ID
		m["pendingHandoff"] = map[string]any{"handoffId": h.ID, "senderId": h.SenderID, "receiverId": h.ReceiverID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID, "initiatedAt": fmtTime(h.InitiatedAt), "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil, "status": h.Status}
	}
	if s.LatestLatitude != nil && s.LatestLongitude != nil {
		m["latestLocation"] = coord(*s.LatestLatitude, *s.LatestLongitude)
	}
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return 200, m, nil
}

