func (a *App) sampleWorkItem(ctx context.Context, q Q, s *Sample, req *Request, withHistory bool) (map[string]any, error) {
	m := map[string]any{"kind": "sample", "sampleId": s.ID, "sample_id": s.ID, "requestId": req.ID, "status": s.Status, "serviceability": req.Serviceability,
		"requestedAt": fmtTime(req.RequestedAt), "deliveryDeadline": fmtTime(req.DeliveryDeadline), "earliestCollectionAt": fmtTime(req.EarliestCollectionAt), "latestCollectionAt": fmtTime(req.LatestCollectionAt),
		"requesterId": req.RequesterID, "locationStale": a.stale(s.LocationRecordedAt), "history": []map[string]any{}}
	putIf(m, "journeyId", s.ActiveJourneyID)
	putIf(m, "activeJourneyId", s.ActiveJourneyID)
	putIf(m, "laboratoryId", req.TargetLaboratoryID)
	putIf(m, "currentHolderId", s.CurrentHolderID)
	if s.LocationRecordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	if withHistory {
		h, err := a.sampleTimeline(ctx, q, s.ID)
		if err != nil {
			return nil, err
		}
		m["history"] = h
	}
	return m, nil
}

func (a *App) assignmentWorkItem(ctx context.Context, q Q, asg *Assignment) (map[string]any, error) {
	m := map[string]any{"kind": asg.Kind, "assignmentId": asg.ID, "assignment_id": asg.ID, "sampleId": asg.primarySample(), "sample_id": asg.primarySample(), "status": asg.Status, "journeyId": asg.JourneyID, "sequence": asg.Sequence}
	putIf(m, "fromLocationId", asg.FromLocationID)
	putIf(m, "toLocationId", asg.ToLocationID)
	if asg.OfferExpiresAt != nil && asg.Status == AsgOffered {
		m["offerExpiresAt"] = fmtTime(*asg.OfferExpiresAt)
	}
	switch asg.Kind {
	case KindTransport:
		if asg.ToLocationID != nil {
			if l, err := loadLocation(ctx, q, *asg.ToLocationID); err == nil {
				usageMap, _ := usageExcluding(ctx, q, nil)
				m["destinationCapacity"] = capacityView(l.CapacityUnits, l.CooledCapacityUnits, usageMap[l.ID])
			}
		}
	case KindNode:
		putIf(m, "nodeId", asg.LocationID)
		prev, err := loadAssignments(ctx, q, `WHERE journey_id = $1 AND kind = 'transport' AND to_location_id = $2 AND status <> 'cancelled' ORDER BY sequence LIMIT 1`, asg.JourneyID, asg.LocationID)
		if err == nil && len(prev) > 0 {
			putIf(m, "incomingFromLocationId", prev[0].FromLocationID)
		}
		next, err := loadAssignments(ctx, q, `WHERE journey_id = $1 AND kind = 'transport' AND from_location_id = $2 AND status <> 'cancelled' ORDER BY sequence LIMIT 1`, asg.JourneyID, asg.LocationID)
		if err == nil && len(next) > 0 {
			putIf(m, "outgoingToLocationId", next[0].ToLocationID)
		}
	case KindLaboratory:
		putIf(m, "laboratoryId", asg.LocationID)
		if sid := asg.primarySample(); sid != "" {
			if s, err := loadSample(ctx, q, sid); err == nil {
				if r, err := loadRequest(ctx, q, s.RequestID); err == nil {
					m["expectedSampleTypeId"] = r.SampleTypeID
				}
			}
		}
	}
	h, err := a.entityTimeline(ctx, q, "assignment", asg.ID)
	if err != nil {
		return nil, err
	}
	m["history"] = h
	return m, nil
}

func capacityView(cap, ccap int, u usage) map[string]any {
	return map[string]any{"capacityUnits": cap, "reservedUnits": u.Regular, "availableUnits": cap - u.Regular, "cooledCapacityUnits": ccap, "cooledReservedUnits": u.Cooled, "cooledAvailableUnits": ccap - u.Cooled}
}

func (a *App) journeyWorkItem(ctx context.Context, q Q, j *Journey) (map[string]any, error) {
	var n int
	if err := q.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id = $1 AND status <> 'cancelled'`, j.ID).Scan(&n); err != nil {
		return nil, err
	}
	eta := ""
	if j.EstimatedDeliveryAt != nil {
		eta = fmtTime(*j.EstimatedDeliveryAt)
	}
	h, err := a.entityTimeline(ctx, q, "journey", j.ID)
	if err != nil {
		return nil, err
	}
	return map[string]any{"kind": "journey", "journeyId": j.ID, "journey_id": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "estimatedDeliveryAt": eta, "assignmentCount": n, "history": h}, nil
}

func (a *App) ListRoleWork(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if len(strings.TrimSpace(string(body))) > 0 {
		if err := json.Unmarshal(body, &in); err != nil {
			return 0, nil, InvalidJSON("malformed request body")
		}
	}
	role := actor.ActiveRole
	if in.Role != "" {
		if !IsRole(in.Role) {
			return 0, nil, BadRequest("invalid_role", "unknown role")
		}
		if in.Role != actor.ActiveRole {
			if actor.ActiveRole == "" && actor.User.HasRole(in.Role) {
				role = in.Role
			} else {
				return 0, nil, ForbiddenDefault()
			}
		}
	}
	if role == "" {
		return 0, nil, RoleNotSelected()
	}
	pending, inProgress, completed := []map[string]any{}, []map[string]any{}, []map[string]any{}
	switch role {
	case RoleRequester:
		samples, err := loadSamples(ctx, a.Pool, `WHERE request_id IN (SELECT id FROM collection_requests WHERE requester_id = $1) ORDER BY created_at DESC`, actor.ID())
		if err != nil {
			return 0, nil, err
		}
		for _, s := range samples {
			req, err := loadRequest(ctx, a.Pool, s.RequestID)
			if err != nil {
				return 0, nil, err
			}
			item, err := a.sampleWorkItem(ctx, a.Pool, s, req, true)
			if err != nil {
				return 0, nil, err
			}
			switch {
			case terminalSample(s.Status):
				completed = append(completed, item)
			case s.Sealed:
				inProgress = append(inProgress, item)
			default:
				pending = append(pending, item)
			}
		}
	case RoleDispatcher, RoleAdministrator:
		journeys, err := loadJourneys(ctx, a.Pool, `ORDER BY created_at DESC`)
		if err != nil {
			return 0, nil, err
		}
		for _, j := range journeys {
			item, err := a.journeyWorkItem(ctx, a.Pool, j)
			if err != nil {
				return 0, nil, err
			}
			if j.Status != JourneyActive {
				completed = append(completed, item)
				continue
			}
			var started int
			if err := a.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id = $1 AND status NOT IN ('unassigned','offered','cancelled')`, j.ID).Scan(&started); err != nil {
				return 0, nil, err
			}
			if started > 0 {
				inProgress = append(inProgress, item)
			} else {
				pending = append(pending, item)
			}
		}
	default:
		kind := ""
		for k, r := range map[string]string{KindCollection: RoleCollection, KindTransport: RoleDelivery, KindNode: RoleNodeHandler, KindLaboratory: RoleLaboratory} {
			if r == role {
				kind = k
			}
		}
		asgs, err := loadAssignments(ctx, a.Pool, `WHERE worker_id = $1 AND kind = $2 ORDER BY created_at DESC`, actor.ID(), kind)
		if err != nil {
			return 0, nil, err
		}
		for _, asg := range asgs {
			item, err := a.assignmentWorkItem(ctx, a.Pool, asg)
			if err != nil {
				return 0, nil, err
			}
			switch {
			case asg.Status == AsgOffered:
				pending = append(pending, item)
			case assignmentFinished(asg.Status):
				completed = append(completed, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
	}
	filter := func(items []map[string]any) []map[string]any {
		if in.Status == "" {
			return items
		}
		out := []map[string]any{}
		for _, it := range items {
			if fmt.Sprint(it["status"]) == in.Status {
				out = append(out, it)
			}
		}
		return out
	}
	switch in.Status {
	case "pending":
		return 200, map[string]any{"pending": pending, "inProgress": []map[string]any{}, "completed": []map[string]any{}}, nil
	case "inProgress", "in_progress":
		return 200, map[string]any{"pending": []map[string]any{}, "inProgress": inProgress, "completed": []map[string]any{}}, nil
	case "completed":
		return 200, map[string]any{"pending": []map[string]any{}, "inProgress": []map[string]any{}, "completed": completed}, nil
	}
	return 200, map[string]any{"pending": filter(pending), "inProgress": filter(inProgress), "completed": filter(completed)}, nil
}

// ---- operations state ----

func (a *App) operationsState(ctx context.Context, sampleTypeFilter string) (map[string]any, error) {
	q := a.Pool
	usageMap, err := usageExcluding(ctx, q, nil)
	if err != nil {
		return nil, err
	}
	samplesOut := []map[string]any{}
	exceptions := []map[string]any{}
	delays := []map[string]any{}
	where := `ORDER BY created_at DESC`
	args := []any{}
	if sampleTypeFilter != "" {
		where = `WHERE request_id IN (SELECT id FROM collection_requests WHERE sample_type_id = $1) ORDER BY created_at DESC`
		args = append(args, sampleTypeFilter)
	}
	samples, err := loadSamples(ctx, q, where, args...)
	if err != nil {
		return nil, err
	}
	now := Now()
	typeFilterSamples := map[string]bool{}
	for _, s := range samples {
		typeFilterSamples[s.ID] = true
		req, err := loadRequest(ctx, q, s.RequestID)
		if err != nil {
			return nil, err
		}
		m := map[string]any{"sampleId": s.ID, "sample_id": s.ID, "status": s.Status, "requestId": req.ID, "origin": coord(req.OriginLatitude, req.OriginLongitude), "deliveryDeadline": fmtTime(req.DeliveryDeadline), "locationStale": a.stale(s.LocationRecordedAt)}
		putIf(m, "currentHolderId", s.CurrentHolderID)
		putIf(m, "activeJourneyId", s.ActiveJourneyID)
		if s.LatestLatitude != nil && s.LatestLongitude != nil {
			m["latestLocation"] = coord(*s.LatestLatitude, *s.LatestLongitude)
		}
		if s.LocationRecordedAt != nil {
			m["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
		}
		samplesOut = append(samplesOut, m)
		if s.Exception != nil {
			exc := map[string]any{"sampleId": s.ID, "status": s.Status, "exception": s.Exception, "requestId": req.ID}
			for k, v := range s.Exception {
				if _, exists := exc[k]; !exists {
					exc[k] = v
				}
			}
			exceptions = append(exceptions, exc)
		}
		if !terminalSample(s.Status) && s.ActiveJourneyID != nil {
			if j, err := loadJourney(ctx, q, *s.ActiveJourneyID, false); err == nil {
				late := j.EstimatedDeliveryAt != nil && j.EstimatedDeliveryAt.After(req.DeliveryDeadline)
				if late || now.After(req.DeliveryDeadline) {
					d := map[string]any{"sampleId": s.ID, "journeyId": j.ID, "deliveryDeadline": fmtTime(req.DeliveryDeadline), "status": s.Status, "reason": "estimated delivery after deadline"}
					if j.EstimatedDeliveryAt != nil {
						d["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
					}
					if now.After(req.DeliveryDeadline) {
						d["reason"] = "delivery deadline passed"
					}
					delays = append(delays, d)
				}
			}
		}
	}
	workersOut := []map[string]any{}
	users, err := loadUsers(ctx, q, `WHERE roles && $1 ORDER BY username`, WorkerRoles)
	if err != nil {
		return nil, err
	}
	workloads, err := loadWorkloads(ctx, q)
	if err != nil {
		return nil, err
	}
	minCount, maxCount := -1, 0
	for _, u := range users {
		st := "unavailable"
		if u.Available && u.Active {
			st = "available"
			if minCount < 0 || workloads[u.ID] < minCount {
				minCount = workloads[u.ID]
			}
			if workloads[u.ID] > maxCount {
				maxCount = workloads[u.ID]
			}
		}
		m := map[string]any{"workerId": u.ID, "worker_id": u.ID, "fullName": u.FullName, "roles": u.Roles, "available": u.Available && u.Active, "status": st, "capacityUnits": u.CapacityUnits, "assignmentCount": workloads[u.ID], "locationStale": true}
		var lat, lon float64
		var at time.Time
		if err := q.QueryRow(ctx, `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id = $1 ORDER BY recorded_at DESC, id DESC LIMIT 1`, u.ID).Scan(&lat, &lon, &at); err == nil {
			m["latestLocation"] = coord(lat, lon)
			m["latest_location"] = coord(lat, lon)
			m["locationRecordedAt"] = fmtTime(at)
			m["locationStale"] = a.stale(&at)
		}
		workersOut = append(workersOut, m)
	}
	if minCount < 0 {
		minCount = 0
	}
	locsOut := []map[string]any{}
	locs, err := loadLocations(ctx, q)
	if err != nil {
		return nil, err
	}
	accRows, err := q.Query(ctx, `SELECT laboratory_id, sample_type_id FROM laboratory_acceptances WHERE accepts`)
	if err != nil {
		return nil, err
	}
	accepted := map[string][]string{}
	for accRows.Next() {
		var lab, st string
		if err := accRows.Scan(&lab, &st); err != nil {
			accRows.Close()
			return nil, err
		}
		accepted[lab] = append(accepted[lab], st)
	}
	accRows.Close()
	for _, l := range locs {
		acc := accepted[l.ID]
		if acc == nil {
			acc = []string{}
		}
		locsOut = append(locsOut, map[string]any{"id": l.ID, "locationId": l.ID, "name": l.Name, "coordinate": coord(l.Latitude, l.Longitude), "active": l.Active, "coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes,
			"functions": functionStates(l), "capacity": capacityView(l.CapacityUnits, l.CooledCapacityUnits, usageMap[l.ID]), "acceptedSampleTypeIds": acc})
	}
	connsOut := []map[string]any{}
	conns, err := loadConnections(ctx, q)
	if err != nil {
		return nil, err
	}
	for _, c := range conns {
		connsOut = append(connsOut, map[string]any{"id": c.ID, "connectionId": c.ID, "fromLocationId": c.FromLocationID, "toLocationId": c.ToLocationID, "travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
			"capacity": capacityView(c.CapacityUnits, c.CooledCapacityUnits, usageMap[c.ID])})
	}
	routesOut := []map[string]any{}
	journeys, err := loadJourneys(ctx, q, `WHERE status = 'active' ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	for _, j := range journeys {
		if sampleTypeFilter != "" {
			match := false
			for _, sid := range j.SampleIDs {
				if typeFilterSamples[sid] {
					match = true
				}
			}
			if !match {
				continue
			}
		}
		stops, err := loadStops(ctx, q, j.ID)
		if err != nil {
			return nil, err
		}
		asgs, err := loadJourneyAssignments(ctx, q, j)
		if err != nil {
			return nil, err
		}
		stopsOut := []map[string]any{}
		for _, s := range stops {
			stopsOut = append(stopsOut, stopView(s))
		}
		legs := []map[string]any{}
		seq := 0
		for _, asg := range asgs {
			if asg.Kind == KindTransport {
				seq++
				legs = append(legs, legView(asg, seq))
			}
		}
		r := map[string]any{"journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs, "orderedStops": stopsOut, "legs": legs}
		putIf(r, "targetLaboratoryId", j.TargetLaboratoryID)
		if j.EstimatedDeliveryAt != nil {
			r["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
		}
		routesOut = append(routesOut, r)
	}
	handoffsOut := []map[string]any{}
	hs, err := loadHandoffs(ctx, q, `WHERE status = 'pending' ORDER BY initiated_at DESC`)
	if err != nil {
		return nil, err
	}
	for _, h := range hs {
		handoffsOut = append(handoffsOut, map[string]any{"handoffId": h.ID, "sampleId": h.SampleID, "journeyId": h.JourneyID, "senderId": h.SenderID, "receiverId": h.ReceiverID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID, "status": h.Status, "initiatedAt": fmtTime(h.InitiatedAt), "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil})
	}
	var ineligible int
	if err := q.QueryRow(ctx, `SELECT COUNT(*) FROM assignments a JOIN journeys j ON j.id = a.journey_id WHERE a.status = 'unassigned' AND j.status = 'active'`).Scan(&ineligible); err != nil {
		return nil, err
	}
	return map[string]any{"samples": samplesOut, "workers": workersOut, "locations": locsOut, "connections": connsOut, "routes": routesOut, "handoffs": handoffsOut, "delays": delays, "exceptions": exceptions,
		"assignmentCountSpread": maxCount - minCount, "ineligibleAssignmentCount": ineligible}, nil
}

func (a *App) ReadOperationsState(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		Filters struct {
			SampleTypeID  string `json:"sampleTypeId"`
			SampleTypeID2 string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if len(strings.TrimSpace(string(body))) > 0 {
		if err := json.Unmarshal(body, &in); err != nil {
			return 0, nil, InvalidJSON("malformed request body")
		}
	}
	f := in.Filters.SampleTypeID
	if f == "" {
		f = in.Filters.SampleTypeID2
	}
	if f != "" && !isUUID(f) {
		return 0, nil, InvalidJSON("filters.sampleTypeId must be a uuid")
	}
	st, err := a.operationsState(ctx, f)
	if err != nil {
		return 0, nil, err
	}
	return 200, st, nil
}

// ---- audit search ----

func (a *App) SearchAuditTrail(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      *int   `json:"limit"`
		Offset     *int   `json:"offset"`
		Order      string `json:"order"`
	}
	if len(strings.TrimSpace(string(body))) > 0 {
		if err := json.Unmarshal(body, &in); err != nil {
			return 0, nil, InvalidJSON("malformed request body")
		}
	}
	limit, offset, order := 500, 0, "newest_first"
	if in.Limit != nil {
		limit = *in.Limit
	}
	if in.Offset != nil {
		offset = *in.Offset
	}
	if in.Order != "" {
		order = in.Order
	}
	if limit < 1 || limit > 5000 {
		return 0, nil, BadRequest("invalid_limit", "limit must be between 1 and 5000")
	}
	if offset < 0 {
		return 0, nil, BadRequest("invalid_offset", "offset must be >= 0")
	}
	if order != "newest_first" && order != "oldest_first" {
		return 0, nil, BadRequest("invalid_order", "order must be newest_first or oldest_first")
	}
	where := []string{"TRUE"}
	args := []any{}
	add := func(cond string, v any) {
		args = append(args, v)
		where = append(where, fmt.Sprintf(cond, len(args)))
	}
	if in.Query != "" {
		add("search_text LIKE '%%' || $%d || '%%'", strings.ToLower(in.Query))
	}
	if in.ActorID != "" {
		add("actor_id = $%d", in.ActorID)
	}
	if in.EntityType != "" {
		add("entity_type = $%d", in.EntityType)
	}
	if in.EntityID != "" {
		add("(entity_id = $%d OR details::text LIKE '%%' || $%d || '%%')", in.EntityID)
		args = append(args, in.EntityID)
		where[len(where)-1] = fmt.Sprintf("(entity_id = $%d OR $%d::text = ANY(sample_ids::text[]))", len(args)-1, len(args))
	}
	if in.Action != "" {
		add("action = $%d", in.Action)
	}
	if in.Role != "" {
		add("role = $%d", in.Role)
	}
	if in.Success != nil {
		add("success = $%d", *in.Success)
	}
	if in.FromTime != "" {
		t, err := parseTime(in.FromTime, "fromTime")
		if err != nil {
			return 0, nil, err
		}
		add("occurred_at >= $%d", t)
	}
	if in.ToTime != "" {
		t, err := parseTime(in.ToTime, "toTime")
		if err != nil {
			return 0, nil, err
		}
		add("occurred_at <= $%d", t)
	}
	cond := strings.Join(where, " AND ")
	var total int
	if err := a.Pool.QueryRow(ctx, `SELECT COUNT(*) FROM audit_log WHERE `+cond, args...).Scan(&total); err != nil {
		return 0, nil, err
	}
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	rows, err := a.Pool.Query(ctx, fmt.Sprintf(`SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE %s ORDER BY occurred_at %s, id %s LIMIT %d OFFSET %d`, cond, dir, dir, limit, offset), args...)
	if err != nil {
		return 0, nil, err
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actorID, role, action, et, eid string
		var success bool
		var at time.Time
		var details []byte
		if err := rows.Scan(&id, &actorID, &role, &action, &et, &eid, &success, &at, &details); err != nil {
			return 0, nil, err
		}
		var d map[string]any
		_ = json.Unmarshal(details, &d)
		if d == nil {
			d = map[string]any{}
		}
		sid := fmt.Sprint(id)
		entries = append(entries, map[string]any{"auditId": sid, "audit_id": sid, "actorId": actorID, "actor_id": actorID, "role": role, "actorRole": role, "action": action, "entityType": et, "entity_type": et, "entityId": eid, "entity_id": eid, "success": success, "occurredAt": fmtTime(at), "occurred_at": fmtTime(at), "details": d})
	}
	if err := rows.Err(); err != nil {
		return 0, nil, err
	}
	out := map[string]any{"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": order, "hasMore": offset+len(entries) < total}
	if offset+len(entries) < total {
		out["nextOffset"] = offset + len(entries)
	}
	return 200, out, nil
}

// ---- bootstrap & catalog ----

func (a *App) Bootstrap(ctx context.Context, actor *Actor) (int, any, error) {
	u := actor.User
	out := map[string]any{
		"user":       map[string]any{"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "activeRole": actor.ActiveRole, "roleSelectionRequired": actor.ActiveRole == ""},
		"serverTime": fmtTime(Now()),
	}
	switch actor.ActiveRole {
	case RoleRequester:
		samples, err := loadSamples(ctx, a.Pool, `WHERE request_id IN (SELECT id FROM collection_requests WHERE requester_id = $1) ORDER BY created_at DESC`, actor.ID())
		if err != nil {
			return 0, nil, err
		}
		items := []map[string]any{}
		for _, s := range samples {
			req, err := loadRequest(ctx, a.Pool, s.RequestID)
			if err != nil {
				return 0, nil, err
			}
			item, err := a.sampleWorkItem(ctx, a.Pool, s, req, false)
			if err != nil {
				return 0, nil, err
			}
			delete(item, "history")
			item["sampleTypeId"] = req.SampleTypeID
			if s.Exception != nil {
				item["exception"] = s.Exception
			}
			items = append(items, item)
		}
		out["requesterSamples"] = items
	case RoleDispatcher, RoleAdministrator:
		st, err := a.operationsState(ctx, "")
		if err != nil {
			return 0, nil, err
		}
		out["operations"] = st
	}
	return 200, out, nil
}

// Catalog is a UI helper exposing reference data (sample types, locations,
// and the users a dispatcher may hand work to).
func (a *App) Catalog(ctx context.Context, actor *Actor) (int, any, error) {
	types, err := loadSampleTypes(ctx, a.Pool)
	if err != nil {
		return 0, nil, err
	}
	locs, err := loadLocations(ctx, a.Pool)
	if err != nil {
		return 0, nil, err
	}
	typesOut := []map[string]any{}
	for _, t := range types {
		typesOut = append(typesOut, sampleTypeView(t))
	}
	locsOut := []map[string]any{}
	for _, l := range locs {
		locsOut = append(locsOut, locationView(l))
	}
	out := map[string]any{"sampleTypes": typesOut, "locations": locsOut, "users": []map[string]any{}}
	if actor.Is(RoleAdministrator, RoleDispatcher) || actor.User.HasRole(RoleCollection) || actor.User.HasRole(RoleDelivery) || actor.User.HasRole(RoleNodeHandler) || actor.User.HasRole(RoleLaboratory) {
		users, err := loadUsers(ctx, a.Pool, `ORDER BY username`)
		if err != nil {
			return 0, nil, err
		}
		usersOut := []map[string]any{}
		for _, u := range users {
			m := map[string]any{"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "active": u.Active, "available": u.Available}
			if actor.Is(RoleAdministrator, RoleDispatcher) {
				m["qualifications"] = u.Qualifications
				m["certifications"] = userView(u)["certifications"]
				m["capacityUnits"] = u.CapacityUnits
				putIf(m, "assignedLocationId", u.AssignedLocationID)
			}
			usersOut = append(usersOut, m)
		}
		sort.Slice(usersOut, func(i, j int) bool { return usersOut[i]["username"].(string) < usersOut[j]["username"].(string) })
		out["users"] = usersOut
	}
	return 200, out, nil
}
