{"command": "create", "path": "/workspace/backend/internal/core/monitor.go", "file_text": "package core

import (
	"context"
	"log"
	"time"

	"github.com/jackc/pgx/v5"
)

// RunMonitor periodically expires stale offers, re-offers unassigned work,
// flags work that nobody can take and expires samples past their deadline.
func (a *App) RunMonitor(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			a.tick(ctx)
		}
	}
}

func (a *App) tick(ctx context.Context) {
	if err := a.expireOffers(ctx); err != nil {
		log.Printf("monitor: expire offers: %v", err)
	}
	a.retryUnassigned(ctx)
	if err := a.flagStarvedAssignments(ctx); err != nil {
		log.Printf("monitor: starved assignments: %v", err)
	}
	if err := a.expireSamples(ctx); err != nil {
		log.Printf("monitor: expire samples: %v", err)
	}
}

// expireOffers treats offers without a response as declined and re-offers them.
func (a *App) expireOffers(ctx context.Context) error {
	now := Now()
	return a.Tx(ctx, func(tx pgx.Tx) error {
		asgs, err := loadAssignments(ctx, tx, `WHERE status = 'offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < $1 FOR UPDATE`, now)
		if err != nil {
			return err
		}
		for _, asg := range asgs {
			worker := *asg.WorkerID
			declined := append(asg.DeclinedBy, worker)
			if _, err := tx.Exec(ctx, `UPDATE assignments SET declined_by = $2, status = $3, worker_id = NULL, offered_at = NULL, offer_expires_at = NULL, updated_at = now() WHERE id = $1`, asg.ID, declined, AsgUnassigned); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `INSERT INTO decline_events (worker_id, assignment_id, declined_at) VALUES ($1,$2,$3)`, worker, asg.ID, now); err != nil {
				return err
			}
			asg.DeclinedBy = declined
			asg.Status = AsgUnassigned
			asg.WorkerID = nil
			if err := a.Audit(ctx, tx, nil, AuditEvent{Action: "assignment.offer_expired", EntityType: "assignment", EntityID: asg.ID, Success: true, SampleIDs: asg.SampleIDs, Details: map[string]any{"workerId": worker, "treatedAs": "declined"}}); err != nil {
				return err
			}
			if _, err := a.offerAssignment(ctx, tx, nil, asg, now); err != nil {
				return err
			}
		}
		return nil
	})
}

// retryUnassigned re-offers assignments that have no worker, e.g. after a
// worker became available or was granted a qualification.
func (a *App) retryUnassigned(ctx context.Context) {
	now := Now()
	err := a.Tx(ctx, func(tx pgx.Tx) error {
		asgs, err := loadAssignments(ctx, tx, `WHERE status = 'unassigned' AND journey_id IN (SELECT id FROM journeys WHERE status = 'active') ORDER BY created_at FOR UPDATE`)
		if err != nil {
			return err
		}
		for _, asg := range asgs {
			// A worker who declined earlier may be considered again once everybody else has had a turn.
			cands, _, err := a.candidateWorkers(ctx, tx, asg, now)
			if err != nil {
				return err
			}
			if len(cands) == 0 && len(asg.DeclinedBy) > 0 {
				if _, err := tx.Exec(ctx, `UPDATE assignments SET declined_by = '{}' WHERE id = $1`, asg.ID); err != nil {
					return err
				}
				asg.DeclinedBy = []string{}
			}
			if _, err := a.offerAssignment(ctx, tx, nil, asg, now); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		log.Printf("monitor: retry unassigned: %v", err)
	}
}

// flagStarvedAssignments raises a no_qualified_worker exception for due work
// that stayed unassigned beyond the grace period.
func (a *App) flagStarvedAssignments(ctx context.Context) error {
	now := Now()
	return a.Tx(ctx, func(tx pgx.Tx) error {
		asgs, err := loadAssignments(ctx, tx, `WHERE status = 'unassigned' AND unassigned_since IS NOT NULL AND unassigned_since < $1 AND journey_id IN (SELECT id FROM journeys WHERE status = 'active')`, now.Add(-a.Cfg.NoWorkerGrace))
		if err != nil {
			return err
		}
		for _, asg := range asgs {
			prior, err := a.priorAssignment(ctx, tx, asg)
			if err != nil {
				return err
			}
			if prior != nil && !assignmentFinished(prior.Status) && !assignmentStarted(prior.Status) {
				continue // not yet due
			}
			for _, sid := range asg.SampleIDs {
				s, err := loadSample(ctx, tx, sid)
				if err != nil {
					return err
				}
				if s.Exception != nil && s.Exception["reason"] == "no_qualified_worker" {
					continue
				}
				if err := a.flagException(ctx, tx, nil, sid, "no_qualified_worker", "no eligible worker accepted the "+asg.Kind+" assignment within the grace period", map[string]any{"assignmentId": asg.ID, "kind": asg.Kind}); err != nil {
					return err
				}
			}
		}
		return nil
	})
}

// expireSamples expires samples whose deadline or collection window passed
// without the required progress.
func (a *App) expireSamples(ctx context.Context) error {
	now := Now()
	return a.Tx(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `SELECT s.id, r.delivery_deadline, r.latest_collection_at, s.sealed FROM samples s JOIN collection_requests r ON r.id = s.request_id
			WHERE s.status NOT IN ('received','expired','cancelled','unserviceable') AND (r.delivery_deadline < $1 OR (NOT s.sealed AND r.latest_collection_at < $1))`, now)
		if err != nil {
			return err
		}
		type row struct {
			id     string
			sealed bool
			dl, lc time.Time
		}
		var expired []row
		for rows.Next() {
			var r row
			if err := rows.Scan(&r.id, &r.dl, &r.lc, &r.sealed); err != nil {
				rows.Close()
				return err
			}
			expired = append(expired, r)
		}
		rows.Close()
		for _, r := range expired {
			reason, msg := "deadline_missed", "the delivery deadline passed before laboratory receipt"
			if !r.sealed && r.lc.Before(now) && !r.dl.Before(now) {
				reason, msg = "collection_window_missed", "the collection window closed before the sample was collected"
			}
			exc := map[string]any{"reason": reason, "message": msg, "flaggedAt": fmtTime(now)}
			if err := setSampleStatus(ctx, tx, r.id, SampleExpired, exc); err != nil {
				return err
			}
			if err := a.Audit(ctx, tx, nil, AuditEvent{Action: "sample.status.expired", EntityType: "sample", EntityID: r.id, Success: true, SampleIDs: []string{r.id}, Details: exc}); err != nil {
				return err
			}
			if err := a.Emit(ctx, tx, Event{Type: "sample.expired", EntityType: "sample", EntityID: r.id, Roles: []string{RoleDispatcher, RoleAdministrator}, Payload: exc}); err != nil {
				return err
			}
			journeys, err := loadJourneys(ctx, tx, `WHERE $1 = ANY(sample_ids) AND status = 'active'`, r.id)
			if err != nil {
				return err
			}
			for _, j := range journeys {
				if len(j.SampleIDs) > 1 {
					continue // batched journeys continue for the remaining samples
				}
				if _, err := cancelUnfinishedAssignments(ctx, tx, j.ID, nil); err != nil {
					return err
				}
				if err := releaseReservations(ctx, tx, j.ID, nil); err != nil {
					return err
				}
				if _, err := tx.Exec(ctx, `UPDATE journeys SET status = $2, replan_status = 'expired', plan_version = plan_version + 1, updated_at = now() WHERE id = $1`, j.ID, JourneyExpired); err != nil {
					return err
				}
			}
		}
		return nil
	})
}
", "security_risk": "MEDIUM", "summary": "Create background monitor for offers, grace and deadline expiry"}

