	post("/api/read-sample-lifecycle", op{Name: "read_sample_lifecycle", Roles: any, AllowUnselected: true, Fn: a.ReadSampleLifecycle})
	post("/api/read-operations-state", op{Name: "read_operations_state", Roles: ops, Fn: a.ReadOperationsState})
	post("/api/search-audit-trail", op{Name: "search_audit_trail", Roles: ops, Fn: a.SearchAuditTrail})
	post("/api/cancel-journey", op{Name: "cancel_journey", Roles: ops, IdemRequired: true, Mutating: true, Fn: a.CancelJourney})
	post("/api/reroute-journey", op{Name: "reroute_journey", Roles: ops, IdemRequired: true, Mutating: true, Fn: a.RerouteJourney})
