	post("/api/edit-active-plan", op{Name: "edit_active_plan", Roles: ops, IdemRequired: true, Mutating: true, Fn: a.EditActivePlan})
	post("/api/report-disruption", op{Name: "report_disruption", Roles: ops, IdemRequired: true, Mutating: true, Fn: a.ReportDisruption})
	_ = workersAndOps

	s.handle("GET", "/api/read-sample-state/{sampleId}", op{Name: "read_sample_state", Roles: any, AllowUnselected: true, Fn: nil})
	s.handle("GET", "/api/read-user/{userId}", op{Name: "read_user", Roles: any, AllowUnselected: true, Fn: nil})
	s.handle("GET", "/api/ui/bootstrap", op{Name: "read_ui_bootstrap", Roles: any, AllowUnselected: true, Fn: func(ctx context.Context, actor *core.Actor, _ []byte) (int, any, error) { return a.Bootstrap(ctx, actor) }})
	s.handle("GET", "/api/ui/catalog", op{Name: "read_ui_catalog", Roles: any, AllowUnselected: true, Fn: func(ctx context.Context, actor *core.Actor, _ []byte) (int, any, error) { return a.Catalog(ctx, actor) }})
	s.mux.HandleFunc("/api/events", s.events)
	s.mux.HandleFunc("/ready", s.ready)
	s.mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		writeError(w, core.NotFound("unknown API route"))
	})
	s.static()
}

// handle registers an operation with method enforcement.
func (s *Server) handle(method, path string, o op) {
	s.mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != method {
			writeJSON(w, http.StatusMethodNotAllowed, map[string]any{"error": "method not allowed", "code": "method_not_allowed"})
			return
		}
		s.serve(w, r, o)
	})
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func (s *Server) serve(w http.ResponseWriter, r *http.Request, o op) {
	ctx := r.Context()
	var body []byte
	if r.Method == http.MethodPost {
		b, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
		if err != nil {
			writeError(w, core.InvalidJSON("unable to read request body"))
			return
		}
		body = b
		if strings.TrimSpace(string(body)) == "" {
			body = []byte("{}")
		}
		var probe map[string]json.RawMessage
		if err := json.Unmarshal(body, &probe); err != nil {
			writeError(w, core.InvalidJSON("request body must be a JSON object"))
			return
		}
	}
	var actor *core.Actor
	if !o.Public {
		var err error
		actor, err = s.app.ResolveSession(ctx, bearerToken(r))
		if err != nil {
			e := core.AsError(err)
			s.app.AuditOutsideTx(ctx, nil, core.AuditEvent{Action: "permission.denied", EntityType: "operation", EntityID: o.Name, Success: false, Details: map[string]any{"code": e.Code, "path": r.URL.Path}})
			writeError(w, e)
			return
		}
		if actor.ActiveRole == "" && !o.AllowUnselected {
			e := core.RoleNotSelected()
			s.app.AuditOutsideTx(ctx, actor, core.AuditEvent{Action: "permission.denied", EntityType: "operation", EntityID: o.Name, Success: false, Details: map[string]any{"code": e.Code}})
			writeError(w, e)
			return
		}
		if o.Roles != nil && !roleAllowed(actor, o) {
			e := core.ForbiddenDefault()
			s.app.AuditOutsideTx(ctx, actor, core.AuditEvent{Action: "permission.denied", EntityType: "operation", EntityID: o.Name, Success: false, Details: map[string]any{"code": e.Code, "activeRole": actor.ActiveRole}})
			writeError(w, e)
			return
		}
	}
	key := ""
	if o.IdemRequired || o.IdemOptional {
		var probe struct {
			Key string `json:"idempotencyKey"`
		}
		_ = json.Unmarshal(body, &probe)
		key = strings.TrimSpace(probe.Key)
		if o.IdemRequired && key == "" {
			writeError(w, core.IdempotencyRequired())
			return
		}
		if key != "" {
			stored, err := s.app.CheckIdempotency(ctx, actor.ID(), key, o.Name, body)
			if err != nil {
				writeError(w, core.AsError(err))
				return
			}
			if stored != nil {
				w.Header().Set("Content-Type", "application/json")
				w.Header().Set("Idempotent-Replayed", "true")
				w.WriteHeader(stored.Status)
				_, _ = w.Write(stored.Body)
				return
			}
		}
	}
	fn := o.Fn
	if fn == nil {
		fn = s.pathOp(o, r)
	}
	status, data, err := fn(ctx, actor, body)
	if err != nil {
		e := core.AsError(err)
		if e.Status >= 500 {
			log.Printf("%s: %v", o.Name, err)
		}
		if o.Mutating || e.Status == 403 {
			s.app.AuditOutsideTx(ctx, actor, core.AuditEvent{Action: o.Name + ".rejected", EntityType: "operation", EntityID: o.Name, Success: false, Details: map[string]any{"code": e.Code, "error": e.Message}})
		}
		writeError(w, e)
		return
	}
	var out []byte
	if o.Name == "system_readiness" {
		out, _ = json.Marshal(data)
	} else {
		out, _ = json.Marshal(map[string]any{"data": data})
	}
	if key != "" {
		s.app.StoreIdempotency(ctx, actor.ID(), key, o.Name, body, status, out)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(out)
}

func roleAllowed(actor *core.Actor, o op) bool {
	roles := actor.EffectiveRoles(o.AllowUnselected)
	for _, r := range roles {
		for _, allowed := range o.Roles {
			if r == allowed {
				return true
			}
		}
	}
	return false
}

func (s *Server) pathOp(o op, r *http.Request) opFunc {
	switch o.Name {
	case "read_sample_state":
		id := r.PathValue("sampleId")
		return func(ctx context.Context, actor *core.Actor, _ []byte) (int, any, error) {
			return s.app.ReadSampleState(ctx, actor, id)
		}
	case "read_user":
		id := r.PathValue("userId")
		return func(ctx context.Context, actor *core.Actor, _ []byte) (int, any, error) {
			return s.app.ReadUser(ctx, actor, id)
		}
	}
	return func(ctx context.Context, actor *core.Actor, _ []byte) (int, any, error) {
		return 0, nil, core.NotFound("unknown operation")
	}
}

func (s *Server) ready(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if err := s.app.Pool.Ping(ctx); err != nil || s.app.Snapshot() == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "starting"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"status": "ready"})
}

// static serves the built frontend with SPA fallback and the local map assets.
func (s *Server) static() {
	mapDir := s.app.Cfg.MapAssetsDir
	s.mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir))))
	dir := s.app.Cfg.StaticDir
	index := filepath.Join(dir, "index.html")
	fs := http.FileServer(http.Dir(dir))
	s.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		p := filepath.Join(dir, filepath.Clean("/"+r.URL.Path))
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		if _, err := os.Stat(index); errors.Is(err, os.ErrNotExist) {
			http.Error(w, "frontend not built", http.StatusNotFound)
			return
		}
		w.Header().Set("Cache-Control", "no-cache")
		http.ServeFile(w, r, index)
	})
}
", "security_risk": "MEDIUM", "summary": "Create HTTP router, middleware and static serving"}

{"command": "create", "path": "/workspace/backend/internal/httpapi/events.go", "file_text": "package httpapi

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"

	"labsample/internal/core"
	"labsample/internal/realtime"
)

const wsSubprotocol = "lab-logistics-v1"

var upgrader = websocket.Upgrader{
	CheckOrigin:  func(r *http.Request) bool { return true },
	Subprotocols: []string{wsSubprotocol},
}

// tokenFromProtocols extracts a bearer token sent as the base64url-encoded
// "bearer.<token>" WebSocket subprotocol.
func tokenFromProtocols(r *http.Request) string {
	for _, p := range websocket.Subprotocols(r) {
		if strings.HasPrefix(p, "bearer.") {
			raw := strings.TrimPrefix(p, "bearer.")
			if b, err := base64.RawURLEncoding.DecodeString(raw); err == nil {
				return string(b)
			}
			if b, err := base64.URLEncoding.DecodeString(raw); err == nil {
				return string(b)
			}
			return raw
		}
	}
	return ""
}

func (s *Server) loadEvents(ctx context.Context, actor *core.Actor, since int64, limit int) ([]realtime.Message, error) {
	rows, err := s.app.Pool.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, audience_roles, audience_user_ids, created_at FROM realtime_events WHERE id > $1 ORDER BY id LIMIT $2`, since, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []realtime.Message
	for rows.Next() {
		var m realtime.Message
		var payload []byte
		if err := rows.Scan(&m.ID, &m.Type, &m.EntityType, &m.EntityID, &payload, &m.Roles, &m.UserIDs, &m.CreatedAt); err != nil {
			return nil, err
		}
		_ = json.Unmarshal(payload, &m.Payload)
		if m.Payload == nil {
			m.Payload = map[string]any{}
		}
		m.CreatedAt = m.CreatedAt.UTC()
		if m.Visible(actor.ID(), actor.ActiveRole) {
			out = append(out, m)
		}
	}
	return out, rows.Err()
}

func (s *Server) events(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]any{"error": "method not allowed", "code": "method_not_allowed"})
		return
	}
	token := bearerToken(r)
	if token == "" {
		token = tokenFromProtocols(r)
	}
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	actor, err := s.app.ResolveSession(r.Context(), token)
	if err != nil {
		writeError(w, core.AsError(err))
		return
	}
	var since int64
	if v := r.URL.Query().Get("since"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			writeError(w, core.InvalidJSON("since must be a non-negative integer"))
			return
		}
		since = n
	}
	if strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		s.websocket(w, r, actor, since)
		return
	}
	events, err := s.loadEvents(r.Context(), actor, since, 500)
	if err != nil {
		writeError(w, core.AsError(err))
		return
	}
	cursor := since
	out := make([]map[string]any, 0, len(events))
	for _, m := range events {
		out = append(out, eventView(m))
		cursor = m.ID
	}
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"events": out, "cursor": cursor}})
}

func eventView(m realtime.Message) map[string]any {
	return map[string]any{"id": m.ID, "type": m.Type, "entityType": m.EntityType, "entityId": m.EntityID, "payload": m.Payload, "createdAt": m.CreatedAt.UTC().Format(time.RFC3339Nano)}
}

func (s *Server) websocket(w http.ResponseWriter, r *http.Request, actor *core.Actor, since int64) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	token := actor.Session.Token
	// The audience follows the role the session currently has selected.
	var roleMu sync.Mutex
	role := actor.ActiveRole
	lastCheck := time.Now()
	roleFn := func() string {
		roleMu.Lock()
		defer roleMu.Unlock()
		if time.Since(lastCheck) > 2*time.Second {
			lastCheck = time.Now()
			if a, err := s.app.ResolveSession(context.Background(), token); err == nil {
				role = a.ActiveRole
			}
		}
		return role
	}
	sub := s.app.Hub.Subscribe(actor.ID(), roleFn)
	defer s.app.Hub.Unsubscribe(sub)

	var writeMu sync.Mutex
	send := func(m realtime.Message) error {
		writeMu.Lock()
		defer writeMu.Unlock()
		_ = conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
		return conn.WriteJSON(eventView(m))
	}
	// Replay durable events after the cursor before streaming live ones.
	replayed, err := s.loadEvents(r.Context(), actor, since, 5000)
	if err == nil {
		for _, m := range replayed {
			if err := send(m); err != nil {
				return
			}
			since = m.ID
		}
	}
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()
	ping := time.NewTicker(25 * time.Second)
	defer ping.Stop()
	for {
		select {
		case <-done:
			return
		case m := <-sub.Ch:
			if m.ID <= since {
				continue
			}
			since = m.ID
			if err := send(m); err != nil {
				return
			}
		case <-ping.C:
			writeMu.Lock()
			_ = conn.WriteControl(websocket.PingMessage, nil, time.Now().Add(5*time.Second))
			writeMu.Unlock()
		}
	}
}
", "security_risk": "MEDIUM", "summary": "Create realtime events endpoint (WebSocket and polling)"}

{"command": "create", "path": "/workspace/backend/cmd/server/main.go", "file_text": "package main

import (
	"context"
	"errors"
	"flag"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"labsample/internal/config"
	"labsample/internal/core"
	"labsample/internal/db"
	"labsample/internal/httpapi"
	"labsample/internal/realtime"
)

func main() {
	reset := flag.Bool("reset", false, "clear application state, apply the schema and exit")
	flag.Parse()

	cfg := config.Load()
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	pool, err := db.Connect(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("database: %v", err)
	}
	defer pool.Close()

	if *reset {
		if err := db.Reset(ctx, pool); err != nil {
			log.Fatalf("reset: %v", err)
		}
		log.Println("application state reset; schema materialised")
		return
	}
	if err := db.Migrate(ctx, pool); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	hub := realtime.NewHub()
	app := core.New(pool, cfg, hub)
	if err := app.EnsureAdmin(ctx); err != nil {
		log.Fatalf("initial administrator: %v", err)
	}
	if err := app.SeedDefaults(ctx); err != nil {
		log.Fatalf("seed defaults: %v", err)
	}
	if err := app.RefreshSnapshot(ctx); err != nil {
		log.Fatalf("serviceability snapshot: %v", err)
	}
	go app.RunMonitor(ctx, 5*time.Second)

	srv := &http.Server{Addr: "127.0.0.1:" + cfg.Port, Handler: httpapi.New(app).Handler(), ReadHeaderTimeout: 10 * time.Second}
	go func() {
		<-ctx.Done()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutdownCtx)
	}()
	log.Printf("lab sample logistics listening on http://%s", srv.Addr)
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatalf("server: %v", err)
	}
}
