const TOKEN_KEY = 'labsample.sessionToken';

export const session = {
  get token(): string | null {
    return localStorage.getItem(TOKEN_KEY);
  },
  set token(v: string | null) {
    if (v) localStorage.setItem(TOKEN_KEY, v);
    else localStorage.removeItem(TOKEN_KEY);
  },
};

export function newIdempotencyKey(): string {
  return crypto.randomUUID();
}

export function nowIso(): string {
  return new Date().toISOString();
}

async function request<T>(method: 'GET' | 'POST', path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { Accept: 'application/json' };
  if (session.token) headers.Authorization = `Bearer ${session.token}`;
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const res = await fetch(path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
  let json: any = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  if (!res.ok) {
    const code = json?.code ?? 'http_error';
    const msg = json?.error ?? `${res.status} ${res.statusText}`;
    if (res.status === 401 && session.token && code === 'unauthorized') {
      session.token = null;
      window.dispatchEvent(new Event('labsample:signed-out'));
    }
    throw new ApiError(res.status, code, msg);
  }
  return (json?.data ?? json) as T;
}

/** POST /api/<operation>. Returns the unwrapped `data` member. */
export function post<T = any>(operation: string, body: unknown = {}): Promise<T> {
  return request<T>('POST', `/api/${operation}`, body);
}

export function get<T = any>(path: string): Promise<T> {
  return request<T>('GET', path);
}

export function describeError(e: unknown): string {
  if (e instanceof ApiError) return `${e.message} (${e.code})`;
  if (e instanceof Error) return e.message;
  return String(e);
}
