import { get, post, session } from './api';
import type { BootstrapUser, Catalog, Role } from './types';

interface AppState {
  user: BootstrapUser | null;
  catalog: Catalog | null;
  bootstrapExtra: Record<string, any>;
  loading: boolean;
  refresh: () => Promise<void>;
  signIn: (username: string, password: string) => Promise<void>;
  signOut: () => void;
  selectRole: (role: Role) => Promise<void>;
  locationName: (id?: string) => string;
  userName: (id?: string) => string;
  sampleTypeName: (id?: string) => string;
}

const Ctx = createContext<AppState | null>(null);

export function AppProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<BootstrapUser | null>(null);
  const [catalog, setCatalog] = useState<Catalog | null>(null);
  const [bootstrapExtra, setExtra] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!session.token) {
      setUser(null);
      setCatalog(null);
      setLoading(false);
      return;
    }
    try {
      const [b, c] = await Promise.all([get<any>('/api/ui/bootstrap'), get<Catalog>('/api/ui/catalog')]);
      const { user: u, ...rest } = b;
      setUser(u);
      setExtra(rest);
      setCatalog(c);
    } catch {
      setUser(null);
      setCatalog(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const onOut = () => {
      setUser(null);
      setCatalog(null);
    };
    window.addEventListener('labsample:signed-out', onOut);
    return () => window.removeEventListener('labsample:signed-out', onOut);
  }, [refresh]);

  const signIn = useCallback(
    async (username: string, password: string) => {
      const data = await post<{ sessionToken: string }>('authenticate-user', { username, password });
      session.token = data.sessionToken;
      setLoading(true);
      await refresh();
    },
    [refresh],
  );

  const signOut = useCallback(() => {
    session.token = null;
    setUser(null);
    setCatalog(null);
  }, []);

  const selectRole = useCallback(
    async (role: Role) => {
      await post('select-active-role', { role });
      await refresh();
    },
    [refresh],
  );

  const value = useMemo<AppState>(() => {
    const locs = new Map(catalog?.locations.map((l) => [l.locationId, l.name]) ?? []);
    const users = new Map(catalog?.users.map((u) => [u.userId, u.fullName || u.username]) ?? []);
    const types = new Map(catalog?.sampleTypes.map((t) => [t.sampleTypeId, t.name]) ?? []);
    const short = (id?: string) => (id ? id.slice(0, 8) : '—');
    return {
      user,
      catalog,
      bootstrapExtra,
      loading,
      refresh,
      signIn,
      signOut,
      selectRole,
      locationName: (id) => (id && locs.get(id)) || short(id),
      userName: (id) => (id && (id === user?.userId ? 'you' : users.get(id))) || short(id),
      sampleTypeName: (id) => (id && types.get(id)) || short(id),
    };
  }, [user, catalog, bootstrapExtra, loading, refresh, signIn, signOut, selectRole]);

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useApp(): AppState {
  const v = useContext(Ctx);
  if (!v) throw new Error('AppProvider missing');
  return v;
}
