{"command": "create", "path": "/workspace/frontend/src/components/MapView.tsx", "file_text": "import { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';
import type { Coordinate } from '../types';

let protocolRegistered = false;
function ensureProtocol() {
  if (protocolRegistered) return;
  maplibregl.addProtocol('pmtiles', new Protocol().tile);
  protocolRegistered = true;
}

export interface MapMarker {
  id: string;
  coordinate: Coordinate;
  label: string;
  kind: 'location' | 'laboratory' | 'worker' | 'sample' | 'origin';
  stale?: boolean;
  inactive?: boolean;
  coverageKm?: number;
}

export interface MapLine {
  id: string;
  coordinates: Coordinate[];
  active?: boolean;
  highlighted?: boolean;
}

interface Props {
  markers: MapMarker[];
  lines?: MapLine[];
  tall?: boolean;
  fit?: boolean;
}

const COLORS: Record<MapMarker['kind'], string> = {
  location: '#1d4ed8',
  laboratory: '#7c3aed',
  worker: '#047857',
  sample: '#b45309',
  origin: '#dc2626',
};

const DEFAULT_CENTER: [number, number] = [77.5946, 12.9716];

function circlePolygon(c: Coordinate, km: number): number[][] {
  const pts: number[][] = [];
  const latR = km / 110.574;
  const lonR = km / (111.32 * Math.cos((c.latitude * Math.PI) / 180));
  for (let i = 0; i <= 48; i++) {
    const a = (i / 48) * 2 * Math.PI;
    pts.push([c.longitude + lonR * Math.cos(a), c.latitude + latR * Math.sin(a)]);
  }
  return pts;
}

function buildData(markers: MapMarker[], lines: MapLine[]) {
  const points: GeoJSON.Feature[] = markers.map((m) => ({
    type: 'Feature',
    id: m.id,
    properties: {
      label: m.label,
      color: COLORS[m.kind],
      opacity: m.inactive ? 0.4 : 1,
      stroke: m.stale ? '#f59e0b' : '#ffffff',
      kind: m.kind,
    },
    geometry: { type: 'Point', coordinates: [m.coordinate.longitude, m.coordinate.latitude] },
  }));
  const circles: GeoJSON.Feature[] = markers
    .filter((m) => m.coverageKm && m.coverageKm > 0)
    .map((m) => ({
      type: 'Feature',
      properties: { active: !m.inactive },
      geometry: { type: 'Polygon', coordinates: [circlePolygon(m.coordinate, m.coverageKm!)] },
    }));
  const lineFeatures: GeoJSON.Feature[] = lines.map((l) => ({
    type: 'Feature',
    id: l.id,
    properties: { color: l.highlighted ? '#dc2626' : l.active === false ? '#9ca3af' : '#1d4ed8', width: l.highlighted ? 4 : 2 },
    geometry: { type: 'LineString', coordinates: l.coordinates.map((c) => [c.longitude, c.latitude]) },
  }));
  return {
    points: { type: 'FeatureCollection', features: points } as GeoJSON.FeatureCollection,
    circles: { type: 'FeatureCollection', features: circles } as GeoJSON.FeatureCollection,
    lines: { type: 'FeatureCollection', features: lineFeatures } as GeoJSON.FeatureCollection,
  };
}

export default function MapView({ markers, lines = [], tall, fit = true }: Props) {
  const container = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const loaded = useRef(false);
  const fitted = useRef(false);

  useEffect(() => {
    if (!container.current) return;
    ensureProtocol();
    const map = new maplibregl.Map({
      container: container.current,
      style: '/map-assets/style.json',
      center: DEFAULT_CENTER,
      zoom: 11,
      attributionControl: { compact: true },
    });
    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    map.on('load', () => {
      const empty: GeoJSON.FeatureCollection = { type: 'FeatureCollection', features: [] };
      map.addSource('coverage', { type: 'geojson', data: empty });
      map.addSource('routes', { type: 'geojson', data: empty });
      map.addSource('points', { type: 'geojson', data: empty });
      map.addLayer({
        id: 'coverage-fill',
        type: 'fill',
        source: 'coverage',
        paint: { 'fill-color': ['case', ['get', 'active'], '#1d4ed8', '#9ca3af'], 'fill-opacity': 0.08 },
      });
      map.addLayer({
        id: 'coverage-line',
        type: 'line',
        source: 'coverage',
        paint: { 'line-color': ['case', ['get', 'active'], '#1d4ed8', '#9ca3af'], 'line-width': 1, 'line-dasharray': [2, 2] },
      });
      map.addLayer({
        id: 'routes-line',
        type: 'line',
        source: 'routes',
        paint: { 'line-color': ['get', 'color'], 'line-width': ['get', 'width'], 'line-opacity': 0.8 },
      });
      map.addLayer({
        id: 'points-circle',
        type: 'circle',
        source: 'points',
        paint: {
          'circle-radius': 7,
          'circle-color': ['get', 'color'],
          'circle-opacity': ['get', 'opacity'],
          'circle-stroke-width': 2,
          'circle-stroke-color': ['get', 'stroke'],
        },
      });
      map.addLayer({
        id: 'points-label',
        type: 'symbol',
        source: 'points',
        layout: {
          'text-field': ['get', 'label'],
          'text-font': ['Noto Sans Regular'],
          'text-size': 11,
          'text-offset': [0, 1.2],
          'text-anchor': 'top',
          'text-allow-overlap': false,
        },
        paint: { 'text-color': '#111827', 'text-halo-color': '#ffffff', 'text-halo-width': 1.2 },
      });
      loaded.current = true;
      map.fire('labsample:ready');
    });
    mapRef.current = map;
    return () => {
      loaded.current = false;
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const apply = () => {
      const data = buildData(markers, lines);
      (map.getSource('points') as maplibregl.GeoJSONSource | undefined)?.setData(data.points);
      (map.getSource('coverage') as maplibregl.GeoJSONSource | undefined)?.setData(data.circles);
      (map.getSource('routes') as maplibregl.GeoJSONSource | undefined)?.setData(data.lines);
      if (fit && !fitted.current && markers.length > 0) {
        const b = new maplibregl.LngLatBounds();
        markers.forEach((m) => b.extend([m.coordinate.longitude, m.coordinate.latitude]));
        map.fitBounds(b, { padding: 60, maxZoom: 13, duration: 0 });
        fitted.current = true;
      }
    };
    if (loaded.current) apply();
    else map.once('labsample:ready', apply);
  }, [markers, lines, fit]);

  return <div ref={container} className={'map' + (tall ? ' tall' : '')} role="region" aria-label="Map" data-testid="map" />;
}
