{"command": "create", "path": "/workspace/frontend/src/components/common.tsx", "file_text": "import type { TimelineEntry } from '../types';

export function fmtTime(s?: string | null): string {
  if (!s) return '—';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  return d.toLocaleString(undefined, { dateStyle: 'short', timeStyle: 'short' });
}

export function toLocalInput(s: string): string {
  const d = new Date(s);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function fromLocalInput(s: string): string {
  return new Date(s).toISOString();
}

export function plusMinutes(minutes: number, from: Date = new Date()): string {
  return new Date(from.getTime() + minutes * 60_000).toISOString();
}

export function humanize(s?: string): string {
  if (!s) return '—';
  return s.replace(/[_.]/g, ' ');
}

const BAD = new Set(['exception', 'expired', 'cancelled', 'declined', 'failed', 'unserviceable']);
const OK = new Set(['received', 'completed', 'delivered', 'confirmed', 'accepted', 'serviceable']);
const WARN = new Set(['pending', 'offered', 'planned', 'requested']);

export function StatusBadge({ status }: { status?: string }) {
  const s = status ?? 'unknown';
  const cls = BAD.has(s) ? 'bad' : OK.has(s) ? 'ok' : WARN.has(s) ? 'warn' : '';
  return (
    <span className={'badge ' + cls} data-status={s}>
      {humanize(s)}
    </span>
  );
}

export function Timeline({ entries, title = 'Status timeline' }: { entries: TimelineEntry[]; title?: string }) {
  const sorted = [...entries].sort((a, b) => a.occurredAt.localeCompare(b.occurredAt) || a.eventId - b.eventId);
  return (
    <section aria-label={title}>
      <h3>{title}</h3>
      {sorted.length === 0 ? (
        <p className="muted">No history yet.</p>
      ) : (
        <ol className="timeline">
          {sorted.map((e) => (
            <li key={e.eventId}>
              <span className="when">{fmtTime(e.occurredAt)}</span>
              <strong>{humanize(e.action)}</strong>{' '}
              <span className="muted">
                {e.role ? `by ${humanize(e.role)}` : ''} {e.success ? '' : '(failed)'}
              </span>
              {e.details && (e.details.status || e.details.newStatus || e.details.to) ? (
                <span className="muted"> → {String(e.details.newStatus ?? e.details.status ?? e.details.to)}</span>
              ) : null}
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export function Notice({ kind, children }: { kind: 'error' | 'success'; children: React.ReactNode }) {
  if (!children) return null;
  return (
    <div className={kind} role={kind === 'error' ? 'alert' : 'status'}>
      {children}
    </div>
  );
}
