// AssignmentContext is a UI helper: for one of the caller's own assignments
// it exposes the adjacent legs (needed to initiate a handoff) and any pending
// handoff on the sample, without revealing the rest of the journey.
func (a *App) AssignmentContext(ctx context.Context, actor *Actor, body []byte) (int, any, error) {
	var in struct {
		AssignmentID string `json:"assignmentId"`
	}
	if err := json.Unmarshal(body, &in); err != nil || in.AssignmentID == "" {
		return 0, nil, InvalidJSON("assignmentId is required")
	}
	asg, err := loadAssignment(ctx, a.Pool, in.AssignmentID, false)
	if err != nil {
		return 0, nil, err
	}
	if !actor.Is(RoleAdministrator, RoleDispatcher) && (asg.WorkerID == nil || *asg.WorkerID != actor.ID()) {
		return 0, nil, ForbiddenDefault()
	}
	j, err := loadJourney(ctx, a.Pool, asg.JourneyID, false)
	if err != nil {
		return 0, nil, err
	}
	asgs, err := loadJourneyAssignments(ctx, a.Pool, j)
	if err != nil {
		return 0, nil, err
	}
	var prev, next *Assignment
	for _, x := range asgs {
		if x.Status == AsgCancelled || x.ID == asg.ID {
			continue
		}
		if x.Sequence < asg.Sequence && (prev == nil || x.Sequence > prev.Sequence) {
			prev = x
		}
		if x.Sequence > asg.Sequence && (next == nil || x.Sequence < next.Sequence) {
			next = x
		}
	}
	view := func(x *Assignment) map[string]any {
		if x == nil {
			return nil
		}
		m := map[string]any{"assignmentId": x.ID, "kind": x.Kind, "status": x.Status, "sequence": x.Sequence}
		putIf(m, "workerId", x.WorkerID)
		putIf(m, "fromLocationId", x.FromLocationID)
		putIf(m, "toLocationId", x.ToLocationID)
		putIf(m, "locationId", x.LocationID)
		if x.WorkerID != nil {
			if u, err := loadUser(ctx, a.Pool, *x.WorkerID); err == nil {
				m["workerName"] = u.FullName
				m["workerUsername"] = u.Username
			}
		}
		return m
	}
	out := map[string]any{"assignmentId": asg.ID, "kind": asg.Kind, "status": asg.Status, "sampleIds": asg.SampleIDs, "journeyId": asg.JourneyID}
	if p := view(prev); p != nil {
		out["previous"] = p
	}
	if n := view(next); n != nil {
		out["next"] = n
	}
	holders := map[string]any{}
	pendings := []map[string]any{}
	for _, sid := range asg.SampleIDs {
		s, err := loadSample(ctx, a.Pool, sid)
		if err != nil {
			return 0, nil, err
		}
		putIf(holders, sid, s.CurrentHolderID)
		hs, err := loadHandoffs(ctx, a.Pool, `WHERE sample_id = $1 AND status = 'pending' ORDER BY initiated_at DESC LIMIT 1`, sid)
		if err != nil {
			return 0, nil, err
		}
		if len(hs) > 0 {
			h := hs[0]
			pendings = append(pendings, map[string]any{"handoffId": h.ID, "sampleId": sid, "senderId": h.SenderID, "receiverId": h.ReceiverID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID, "senderConfirmed": h.SenderConfirmedAt != nil, "receiverConfirmed": h.ReceiverConfirmedAt != nil, "initiatedAt": fmtTime(h.InitiatedAt)})
		}
	}
	out["currentHolders"] = holders
	out["pendingHandoffs"] = pendings
	return 200, out, nil
}
