  pendingHandoffs: {
    handoffId: string;
    sampleId: string;
    senderId: string;
    receiverId: string;
    senderConfirmed: boolean;
    receiverConfirmed: boolean;
  }[];
}

const TRANSPORT_STEPS = ['at_pickup', 'picked_up', 'in_transit', 'arrived', 'delivered'];
const TASK_STEPS = ['in_progress', 'completed'];

function nextSteps(kind: string, status: string): string[] {
  const steps = kind === 'transport' ? TRANSPORT_STEPS : TASK_STEPS;
  const idx = steps.indexOf(status);
  return steps.slice(idx + 1);
}

