  const [sampleTypeId, setSampleTypeId] = useState('');
  const [container, setContainer] = useState('');
  const [tMin, setTMin] = useState('');
  const [tMax, setTMax] = useState('');
  const [requestedAt, setRequestedAt] = useState(toLocalInput(new Date().toISOString()));
  const [earliest, setEarliest] = useState(toLocalInput(plusMinutes(15)));
  const [latest, setLatest] = useState(toLocalInput(plusMinutes(120)));
  const [deadline, setDeadline] = useState(toLocalInput(plusMinutes(360)));
  const [err, setErr] = useState('');
  const [check, setCheck] = useState<any>(null);
  const [created, setCreated] = useState<any>(null);
  const [busy, setBusy] = useState(false);

  const nodes = useMemo(() => (catalog?.locations ?? []).filter((l) => l.active), [catalog]);
  const types = catalog?.sampleTypes ?? [];

  useEffect(() => {
    const t = types.find((x) => x.sampleTypeId === sampleTypeId);
    if (t) {
      setContainer(t.containerType);
      setTMin(String(t.temperatureMinC));
      setTMax(String(t.temperatureMaxC));
    }
  }, [sampleTypeId, types]);

  useEffect(() => {
    if (originType === 'node' && originNodeId) {
      const n = nodes.find((x) => x.locationId === originNodeId);
