        setLat(String(n.coordinate.latitude));
        setLon(String(n.coordinate.longitude));
      }
    }
  }, [originType, originNodeId, nodes]);

  const validate = (): string => {
    if (!sampleTypeId) return 'Choose a sample type.';
    const la = Number(lat);
    const lo = Number(lon);
    if (isNaN(la) || isNaN(lo) || la < -90 || la > 90 || lo < -180 || lo > 180) return 'Origin coordinates are invalid.';
    if (originType === 'node' && !originNodeId) return 'Choose the network node the sample is at.';
    const e = new Date(earliest).getTime();
    const l = new Date(latest).getTime();
    const d = new Date(deadline).getTime();
    if (isNaN(e) || isNaN(l) || isNaN(d)) return 'All times are required.';
    if (l <= e) return 'The collection window must end after it starts.';
    if (d <= l) return 'The delivery deadline must be after the end of the collection window.';
    if (d <= Date.now()) return 'The delivery deadline must be in the future.';
    return '';
  };

  const body = () => ({
    origin: { latitude: Number(lat), longitude: Number(lon) },
    originType,
    originNodeId: originType === 'node' ? originNodeId : undefined,
    sampleTypeId,
    requestedAt: fromLocalInput(requestedAt),
    deliveryDeadline: fromLocalInput(deadline),
    earliestCollectionAt: fromLocalInput(earliest),
    latestCollectionAt: fromLocalInput(latest),
  });

