            {!presealed && <option value="home">Patient home</option>}
            <option value="clinic">Clinic</option>
            <option value="node">Network node</option>
          </select>
        </label>
        {originType === 'node' && (
          <label>
            Network node
            <select value={originNodeId} onChange={(e) => setOriginNodeId(e.target.value)}>
              <option value="">— choose —</option>
              {nodes.map((n) => (
                <option key={n.locationId} value={n.locationId}>
                  {n.name}
                </option>
              ))}
            </select>
          </label>
        )}
        <div className="row">
          <label>
            Latitude
            <input name="latitude" value={lat} onChange={(e) => setLat(e.target.value)} />
          </label>
          <label>
            Longitude
            <input name="longitude" value={lon} onChange={(e) => setLon(e.target.value)} />
          </label>
        </div>
        <label>
          Sample type
          <select name="sampleTypeId" value={sampleTypeId} onChange={(e) => setSampleTypeId(e.target.value)}>
            <option value="">— choose —</option>
            {types.map((t) => (
              <option key={t.sampleTypeId} value={t.sampleTypeId}>
                {t.name}
              </option>
            ))}
          </select>
        </label>
        <div className="row">
          <label>
            Container type
            <input value={container} onChange={(e) => setContainer(e.target.value)} />
          </label>
          <label>
            Min temp (°C)
            <input type="number" step="0.1" value={tMin} onChange={(e) => setTMin(e.target.value)} />
          </label>
          <label>
            Max temp (°C)
            <input type="number" step="0.1" value={tMax} onChange={(e) => setTMax(e.target.value)} />
          </label>
        </div>
        <label>
          Requested at
          <input type="datetime-local" value={requestedAt} onChange={(e) => setRequestedAt(e.target.value)} />
        </label>
        <div className="row">
          <label>
            Collection window start
            <input name="earliestCollectionAt" type="datetime-local" value={earliest} onChange={(e) => setEarliest(e.target.value)} />
          </label>
          <label>
            Collection window end
            <input name="latestCollectionAt" type="datetime-local" value={latest} onChange={(e) => setLatest(e.target.value)} />
          </label>
        </div>
        <label>
          Delivery deadline
          <input name="deliveryDeadline" type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} />
        </label>
        <Notice kind="error">{err}</Notice>
        <div className="btns">
          <button type="button" className="secondary" disabled={busy} onClick={doCheck}>
            Check serviceability (dry run)
          </button>
          <button type="submit" disabled={busy}>
            {presealed ? 'Register sample' : 'Create request'}
          </button>
        </div>
        {check && (
          <div className={check.serviceable ? 'success' : 'error'} role="status" data-testid="serviceability-result">
            <strong>{check.serviceable ? 'Serviceable' : 'Not serviceable'}</strong> — {humanize(check.reason)}
            {check.targetLaboratoryId && <> · laboratory {locationName(check.targetLaboratoryId)}</>}
            {check.estimatedArrivalAt && <> · estimated arrival {fmtTime(check.estimatedArrivalAt)}</>}
            <span className="muted"> (serviceability version {check.serviceabilityVersion}; nothing was created)</span>
          </div>
        )}
        {created && (
          <div className="success" role="status">
            {presealed ? 'Sample registered' : 'Request created'}: <Link to={`/samples/${created.sampleId}`}>sample {created.sampleId.slice(0, 8)}</Link> —{' '}
            {humanize(created.serviceability)}
            {created.serviceabilityReason ? ` (${humanize(created.serviceabilityReason)})` : ''}
            {created.targetLaboratoryId && <> · laboratory {locationName(created.targetLaboratoryId)}</>}
          </div>
        )}
      </form>
      <div className="card">
        <h2>Service coverage</h2>
        <p className="muted">Dashed circles show the 5 km coverage of active collection points.</p>
        <MapView markers={markers} />
      </div>
    </div>
  );
}
