import { Link, useNavigate, useParams } from 'react-router-dom';
import { describeError, newIdempotencyKey, post } from '../api';
import { useApp } from '../AppContext';
import MapView, { type MapLine, type MapMarker } from '../components/MapView';
import { Notice, StatusBadge, fmtTime, humanize } from '../components/common';
import type { JourneyPlan } from '../types';

const CHANGE_TYPES = ['add_stop', 'remove_stop', 'reorder_stops', 'replace_route', 'replace_worker', 'reassign_worker', 'merge_samples', 'split_samples', 'split_batch', 'cancel_work', 'reroute'];

const CHANGE_HINTS: Record<string, string> = {
  add_stop: '{"locationId": "<uuid>", "afterStopId": "<uuid, optional>", "dwellMinutes": 0}',
  remove_stop: '{"stopId": "<uuid>"}',
  reorder_stops: '{"orderedStopIds": ["<uuid>", "..."]}',
  replace_route: '{"locationIds": ["<uuid>", "..."]}',
  replace_worker: '{"assignmentId": "<uuid>", "workerId": "<uuid>"}',
  reassign_worker: '{"assignmentId": "<uuid>", "workerId": "<uuid>"}',
  merge_samples: '{"sourceJourneyIds": ["<uuid>"]}',
  split_samples: '{"sampleIds": ["<uuid>"]}',
  split_batch: '{"sampleIds": ["<uuid>"]}',
  cancel_work: '{"reason": "text"}',
  reroute: '{"reason": "text"}',
};

export default function JourneyPage() {
  const { journeyId } = useParams();
  const nav = useNavigate();
  const { user, catalog, locationName, userName } = useApp();
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [err, setErr] = useState('');
  const [msg, setMsg] = useState('');
  const [busy, setBusy] = useState(false);
  const [reason, setReason] = useState('');
  const [splitIds, setSplitIds] = useState<string[]>([]);
  const [mergeIds, setMergeIds] = useState('');
  const [changeType, setChangeType] = useState('add_stop');
  const [changes, setChanges] = useState(CHANGE_HINTS.add_stop);

  const isDispatcher = user?.activeRole === 'dispatcher' || user?.activeRole === 'administrator';

  const load = useCallback(async () => {
    if (!journeyId) return;
    try {
      setPlan(await post<JourneyPlan>('read-journey-plan', { journeyId }));
      setErr('');
    } catch (e) {
      setErr(describeError(e));
    }
  }, [journeyId]);

  useEffect(() => {
    load();
  }, [load]);

  const { markers, lines } = useMemo(() => {
    const markers: MapMarker[] = [];
    const lines: MapLine[] = [];
    if (!plan) return { markers, lines };
    const path: { latitude: number; longitude: number }[] = [];
    for (const s of plan.orderedStops) {
      const loc = catalog?.locations.find((l) => l.locationId === s.locationId);
      const c = s.coordinate ?? loc?.coordinate;
      if (!c) continue;
      markers.push({ id: s.stopId, coordinate: c, label: `${s.sequence}. ${s.stopType === 'pickup' ? 'origin' : loc?.name ?? ''}`, kind: s.stopType === 'pickup' ? 'origin' : loc?.functions.laboratory ? 'laboratory' : 'location' });
      path.push(c);
    }
    if (path.length > 1) lines.push({ id: 'route', coordinates: path, highlighted: true });
    return { markers, lines };
  }, [plan, catalog]);

  const run = async (label: string, fn: () => Promise<any>) => {
    setBusy(true);
    setErr('');
    setMsg('');
    try {
      const r = await fn();
      setMsg(`${label} succeeded`);
      await load();
      return r;
    } catch (e) {
      setErr(`${label} failed — ${describeError(e)}`);
    } finally {
      setBusy(false);
    }
  };

  if (err && !plan) return <Notice kind="error">{err}</Notice>;
  if (!plan) return <p>Loading…</p>;
  const full = plan as any;
  const pv = plan.planVersion;

