          {full.valid === false ? ' · INVALID' : ''}
        </span>
        <span className="spacer" />
        <button className="secondary" onClick={load}>
          Refresh
        </button>
      </div>
      <Notice kind="error">{err}</Notice>
      <Notice kind="success">{msg}</Notice>
      <div className="grid two">
        <div className="card">
          <dl className="kv">
            <dt>Samples</dt>
            <dd>
              {(plan.sampleIds ?? []).map((s) => (
                <Link key={s} to={`/samples/${s}`} style={{ marginRight: 8 }}>
                  {s.slice(0, 8)}
                </Link>
              ))}
            </dd>
            <dt>Estimated delivery</dt>
            <dd>{fmtTime(plan.estimatedDeliveryAt)}</dd>
            {full.totalCostUnits !== undefined && (
              <>
                <dt>Total cost</dt>
                <dd>{full.totalCostUnits}</dd>
              </>
            )}
            {full.parentJourneyId && (
              <>
                <dt>Replaces / split from</dt>
                <dd>
                  <Link to={`/journeys/${full.parentJourneyId}`}>{full.parentJourneyId.slice(0, 8)}</Link>
                </dd>
