                </dd>
              </>
            )}
            {full.assignedWorkerIds && (
              <>
                <dt>Workers</dt>
                <dd>{full.assignedWorkerIds.map(userName).join(', ') || '—'}</dd>
              </>
            )}
          </dl>
          <h2>Stops</h2>
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Location</th>
                <th>Type</th>
                <th>ETA</th>
                <th>Dwell</th>
                <th>Completed</th>
              </tr>
            </thead>
            <tbody>
              {plan.orderedStops.map((s) => (
                <tr key={s.stopId}>
                  <td>{s.sequence}</td>
                  <td>{s.stopType === 'pickup' ? 'Origin' : locationName(s.locationId)}</td>
                  <td>{humanize(s.stopType)}</td>
                  <td>{fmtTime(s.estimatedAt)}</td>
                  <td>{s.dwellMinutes ?? 0} min</td>
                  <td>{s.completedAt ? fmtTime(s.completedAt) : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <h2>Legs</h2>
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>From</th>
                <th>To</th>
                <th>Worker</th>
                <th>Status</th>
                <th>Assignment</th>
              </tr>
            </thead>
            <tbody>
              {plan.legs.map((l) => (
                <tr key={l.assignmentId}>
                  <td>{l.sequence}</td>
                  <td>{locationName(l.fromLocationId) || 'origin'}</td>
                  <td>{locationName(l.toLocationId)}</td>
                  <td>{l.workerId ? userName(l.workerId) : 'unassigned'}</td>
                  <td>
                    <StatusBadge status={l.status} />
                  </td>
                  <td className="mono">{l.assignmentId.slice(0, 8)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {full.collectionAssignmentIds && (
            <p className="muted">
              Collection assignments: {full.collectionAssignmentIds.length} · node assignments: {full.nodeAssignmentIds?.length ?? 0} · laboratory assignments:{' '}
              {full.laboratoryAssignmentIds?.length ?? 0}
            </p>
          )}
        </div>
        <div className="card">
          <MapView markers={markers} lines={lines} />
        </div>
      </div>

      {isDispatcher && plan.status === 'active' && (
        <div className="card">
          <h2>Change plan (version {pv})</h2>
          <div className="row">
            <input placeholder="Reason" value={reason} onChange={(e) => setReason(e.target.value)} />
            <button
              className="secondary"
              disabled={busy}
              onClick={() => run('Reroute', () => post('reroute-journey', { journeyId: plan.journeyId, expectedPlanVersion: pv, reason: reason || undefined, idempotencyKey: newIdempotencyKey() }))}
            >
              Reroute
            </button>
            <button
              className="danger"
              disabled={busy}
              onClick={() => run('Cancel journey', () => post('cancel-journey', { journeyId: plan.journeyId, expectedPlanVersion: pv, reason: reason || undefined, idempotencyKey: newIdempotencyKey() }))}
            >
              Cancel journey
            </button>
          </div>
          <h3>Split samples into a new journey</h3>
          <div className="row">
            {(plan.sampleIds ?? []).map((s) => (
              <label key={s} className="row">
                <input type="checkbox" checked={splitIds.includes(s)} onChange={(e) => setSplitIds(e.target.checked ? [...splitIds, s] : splitIds.filter((x) => x !== s))} />
                {s.slice(0, 8)}
              </label>
            ))}
            <button
              className="secondary"
              disabled={busy || splitIds.length === 0}
              onClick={() =>
                run('Split', async () => {
                  const r = await post<any>('split-journey', { journeyId: plan.journeyId, expectedPlanVersion: pv, sampleIds: splitIds, idempotencyKey: newIdempotencyKey() });
                  setSplitIds([]);
                  if (r?.splitJourney?.journeyId) setMsg(`Split journey created: ${r.splitJourney.journeyId}`);
                })
              }
            >
              Split
            </button>
          </div>
          <h3>Merge other journeys into this one</h3>
          <div className="row">
            <input placeholder="Source journey IDs, comma separated" value={mergeIds} onChange={(e) => setMergeIds(e.target.value)} style={{ minWidth: 360 }} />
