{"command": "create", "path": "/workspace/frontend/src/pages/Audit.tsx", "file_text": "import { useCallback, useEffect, useState, type FormEvent } from 'react';
import { describeError, post } from '../api';
import { Notice, fmtTime } from '../components/common';

export default function AuditPage() {
  const [q, setQ] = useState('');
  const [entityType, setEntityType] = useState('');
  const [entityId, setEntityId] = useState('');
  const [action, setAction] = useState('');
  const [role, setRole] = useState('');
  const [order, setOrder] = useState<'newest_first' | 'oldest_first'>('newest_first');
  const [offset, setOffset] = useState(0);
  const [limit] = useState(50);
  const [res, setRes] = useState<any>(null);
  const [err, setErr] = useState('');

  const search = useCallback(
    async (off = 0) => {
      try {
        const body: Record<string, unknown> = { limit, offset: off, order };
        if (q) body.query = q;
        if (entityType) body.entityType = entityType;
        if (entityId) body.entityId = entityId;
        if (action) body.action = action;
        if (role) body.role = role;
        setRes(await post('search-audit-trail', body));
        setOffset(off);
        setErr('');
      } catch (e) {
        setErr(describeError(e));
      }
    },
    [q, entityType, entityId, action, role, order, limit],
  );

  useEffect(() => {
    search(0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    search(0);
  };

  return (
    <section aria-label="Audit trail">
      <h1>Audit trail</h1>
      <form className="card row" onSubmit={submit} role="search" aria-label="Audit search">
        <label>
          Search
          <input name="query" value={q} onChange={(e) => setQ(e.target.value)} placeholder="free text, id, action…" />
        </label>
        <label>
          Entity type
          <input value={entityType} onChange={(e) => setEntityType(e.target.value)} placeholder="sample, journey, user…" />
        </label>
        <label>
          Entity id
          <input value={entityId} onChange={(e) => setEntityId(e.target.value)} />
        </label>
        <label>
          Action
          <input value={action} onChange={(e) => setAction(e.target.value)} placeholder="e.g. auth.login" />
        </label>
        <label>
          Role
          <input value={role} onChange={(e) => setRole(e.target.value)} />
        </label>
        <label>
          Order
          <select value={order} onChange={(e) => setOrder(e.target.value as any)}>
            <option value="newest_first">Newest first</option>
            <option value="oldest_first">Oldest first</option>
          </select>
        </label>
        <button type="submit">Search</button>
      </form>
      <Notice kind="error">{err}</Notice>
      {res && (
        <div className="card">
          <p className="muted">
            {res.total} matching entries · showing {res.returned} from offset {res.offset}
          </p>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {res.entries.map((e: any) => (
                <tr key={e.auditId}>
                  <td>{fmtTime(e.occurredAt)}</td>
                  <td className="mono">{e.actorId?.slice(0, 8) || '—'}</td>
                  <td>{e.role}</td>
                  <td>{e.action}</td>
                  <td>
                    {e.entityType} <span className="mono">{e.entityId?.slice(0, 8)}</span>
                  </td>
                  <td>{e.success ? <span className="badge ok">success</span> : <span className="badge bad">failure</span>}</td>
                  <td className="mono" style={{ maxWidth: 420, overflowWrap: 'anywhere' }}>
                    {JSON.stringify(e.details)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="btns">
            <button className="secondary" disabled={offset === 0} onClick={() => search(Math.max(0, offset - limit))}>
              Previous
            </button>
            <button className="secondary" disabled={!res.hasMore} onClick={() => search(res.nextOffset ?? offset + limit)}>
              Next
            </button>
          </div>
        </div>
      )}
    </section>
  );
}
