      const a = byId.get(c.fromLocationId);
      const b = byId.get(c.toLocationId);
      if (a && b) lines.push({ id: c.connectionId, coordinates: [a.coordinate, b.coordinate], active: c.active });
    }
    for (const w of ops?.workers ?? []) {
      if (w.latestLocation) markers.push({ id: 'w-' + w.workerId, coordinate: w.latestLocation, label: w.fullName || 'worker', kind: 'worker', stale: w.locationStale });
    }
    for (const s of ops?.samples ?? []) {
      if (s.latestLocation) markers.push({ id: 's-' + s.sampleId, coordinate: s.latestLocation, label: 'sample ' + s.sampleId.slice(0, 6), kind: 'sample', stale: s.locationStale });
    }
    return { markers, lines };
  }, [catalog, ops]);

  return (
    <section aria-label="Live map">
      <div className="row">
        <h1>Live map</h1>
        <span className={'badge ' + (connected ? 'ok' : 'warn')}>{connected ? 'live updates connected' : 'live updates reconnecting'}</span>
