// The supplied style.json uses root-relative URLs; MapLibre requires absolute sprite/glyph URLs.
function absolutizeStyle(style: maplibregl.StyleSpecification): maplibregl.StyleSpecification {
  const origin = window.location.origin;
  const abs = (u: string) => (u.startsWith('/') ? origin + u : u);
  const out: maplibregl.StyleSpecification = { ...style, sources: { ...style.sources } };
  if (typeof out.sprite === 'string') out.sprite = abs(out.sprite);
  if (out.glyphs) out.glyphs = abs(out.glyphs);
  for (const [k, src] of Object.entries(out.sources)) {
    if ('url' in src && typeof src.url === 'string' && src.url.startsWith('pmtiles:///')) {
      out.sources[k] = { ...src, url: 'pmtiles://' + origin + src.url.slice('pmtiles://'.length) };
    }
  }
  return out;
}
